:root {
  color-scheme: dark;
  --bg: #0c1012;
  --panel: #151a1f;
  --panel-2: #1e252b;
  --ink: #f5f7f4;
  --muted: #a4ada8;
  --line: rgba(255, 255, 255, 0.11);
  --green: #28d17c;
  --amber: #f7b733;
  --red: #ef4e63;
  --cyan: #4ecdc4;
  --blue: #5c9cff;
  --violet: #b78cff;
  --faircroft-pink: #ff149d;
  --faircroft-cyan: #00dff9;
  --faircroft-glow: 0 0 28px rgba(255, 20, 157, 0.18), 0 0 34px rgba(0, 223, 249, 0.12);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
  --radius: 8px;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--ink);
}

body {
  min-height: 100svh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 20, 157, 0.09), transparent 32%),
    radial-gradient(circle at 84% 88%, rgba(0, 223, 249, 0.08), transparent 34%),
    linear-gradient(140deg, rgba(12, 12, 18, 0.97), rgba(4, 5, 9, 0.99)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 96px);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

#app {
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 24px;
}

.boot-screen {
  display: grid;
  gap: 16px;
  place-items: center;
  width: min(320px, calc(100% - 42px));
  margin: 10vh auto 0;
  text-align: center;
}

.faircroft-entrance-media {
  width: min(300px, 92%);
  aspect-ratio: 16 / 9;
  border: 0;
  border-radius: 18px;
  object-fit: cover;
  background: #000;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.55), var(--faircroft-glow);
}

.faircroft-emblem {
  display: block;
  object-fit: cover;
  background: #000;
}

.boot-brand {
  display: grid;
  place-items: center;
  margin: 0;
  width: 76px;
  height: 76px;
  border-radius: 18px;
  color: #111;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0;
  background: linear-gradient(140deg, var(--green), var(--amber));
  box-shadow: 0 16px 40px rgba(40, 209, 124, 0.28);
  animation: boot-brand-pulse 1.6s ease-in-out infinite;
}

.boot-orb {
  --orb-size: 130px;
  position: relative;
  width: var(--orb-size);
  height: var(--orb-size);
  border-radius: 999px;
  display: grid;
  place-items: center;
}

.boot-orb-core {
  width: 56px;
  height: 56px;
  border-radius: 999px;
  background: radial-gradient(circle at 35% 30%, #effdff, var(--faircroft-cyan) 38%, #3d1873 62%, transparent 84%);
  box-shadow: 0 0 0 6px rgba(0, 223, 249, 0.12);
  animation: boot-orb-glow 1.75s ease-in-out infinite;
}

.boot-orb-ring {
  position: absolute;
  inset: 8px;
  border-radius: 999px;
  border: 1px solid rgba(126, 231, 255, 0.18);
  border-top-color: rgba(255, 20, 157, 0.68);
  animation: boot-orb-spin 2.4s linear infinite;
}

.boot-orb-ring + .boot-orb-ring {
  inset: 20px;
  border-color: rgba(92, 156, 255, 0.22);
  border-left-color: rgba(0, 223, 249, 0.68);
  animation-direction: reverse;
  animation-duration: 1.9s;
}

.boot-title {
  margin: 0;
  font-size: 22px;
  letter-spacing: 0;
  line-height: 1.1;
  font-weight: 900;
}

.boot-subtitle,
.boot-meta,
.boot-note,
.boot-error {
  margin: 0;
  max-width: 90%;
  color: var(--muted);
  line-height: 1.35;
  font-size: 13px;
}

.boot-subtitle {
  margin-top: -2px;
}

.boot-meta {
  color: rgba(255, 255, 255, 0.42);
  font-size: 12px;
}

.boot-note {
  color: rgba(255, 255, 255, 0.56);
}

.boot-error {
  color: #ff7a8c;
}

.boot-progress {
  width: min(220px, 80%);
  height: 4px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}

.boot-progress span {
  display: block;
  width: 38%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--faircroft-cyan), var(--faircroft-pink));
  animation: boot-sweep 1.2s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
}

.boot-screen button[data-retry-boot] {
  margin-top: 6px;
}

.boot-line {
  width: 160px;
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
}

.boot-line::after {
  content: "";
  display: block;
  width: 45%;
  height: 100%;
  border-radius: inherit;
  background: var(--green);
  animation: boot-sweep 1.1s ease-in-out infinite;
}

@keyframes boot-orb-spin {
  to { transform: rotate(360deg); }
}

@keyframes boot-orb-glow {
  0%,
  100% {
    transform: scale(0.96);
    box-shadow: 0 0 0 6px rgba(0, 223, 249, 0.1);
  }
  50% {
    transform: scale(1.07);
    box-shadow: 0 0 0 14px rgba(255, 20, 157, 0.12), 0 0 34px rgba(0, 223, 249, 0.4);
  }
}

@keyframes boot-sweep {
  from { transform: translateX(-120%); }
  to { transform: translateX(260%); }
}

@keyframes boot-brand-pulse {
  0%,
  100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

.phone-shell {
  width: min(430px, 100%);
  height: min(900px, calc(100svh - 32px));
  min-height: 700px;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(150, 131, 255, 0.25);
  border-radius: 34px;
  background:
    linear-gradient(160deg, rgba(31, 38, 42, 0.94), rgba(10, 13, 15, 0.98) 44%, rgba(24, 18, 29, 0.98)),
    linear-gradient(35deg, rgba(40, 209, 124, 0.08), rgba(255, 93, 125, 0.07), rgba(92, 156, 255, 0.08));
  box-shadow: var(--shadow);
}

.phone-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 1px 0 rgba(255, 20, 157, 0.16), inset 0 -1px 0 rgba(0, 223, 249, 0.13);
}

.phone-shell::before {
  content: "";
  position: absolute;
  top: 10px;
  left: 50%;
  z-index: 6;
  width: 112px;
  height: 28px;
  border-radius: 999px;
  background: #060708;
  transform: translateX(-50%);
}

.phone-screen {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: max(22px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
}

.phone-screen::before {
  content: "";
  position: absolute;
  inset: 34px 0 0;
  pointer-events: none;
  background:
    linear-gradient(115deg, transparent 0 24%, rgba(255, 255, 255, 0.07) 25%, transparent 28% 100%),
    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.028) 0 1px, transparent 1px 22px);
  opacity: 0.42;
  transform: translateX(-18%);
  animation: glassSweep 11s ease-in-out infinite alternate;
}

@keyframes glassSweep {
  from { transform: translateX(-22%) translateY(0); }
  to { transform: translateX(12%) translateY(-12px); }
}

.status-bar {
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 13px;
  font-weight: 700;
}

.status-icons {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.signal,
.battery {
  width: 22px;
  height: 12px;
  border: 1px solid currentColor;
  border-radius: 3px;
  position: relative;
}

.signal::after {
  content: "";
  position: absolute;
  inset: 3px;
  background: currentColor;
  border-radius: 1px;
}

.battery::after {
  content: "";
  position: absolute;
  right: -4px;
  top: 3px;
  width: 2px;
  height: 5px;
  border-radius: 0 2px 2px 0;
  background: currentColor;
}

.os-version {
  position: absolute;
  left: 0;
  right: 0;
  bottom: max(7px, calc(env(safe-area-inset-bottom) + 5px));
  z-index: 8;
  pointer-events: none;
  color: rgba(255, 255, 255, 0.36);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
}

.auth-card,
.home-stack,
.app-panel {
  position: relative;
  z-index: 1;
  animation: rise 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.auth-card {
  margin-top: auto;
  margin-bottom: auto;
  display: grid;
  gap: 18px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(12, 16, 18, 0.72);
  backdrop-filter: blur(18px);
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 12px;
}

.app-mark {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  box-shadow: var(--faircroft-glow);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 28px;
  line-height: 1;
  letter-spacing: 0;
}

.auth-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
}

.auth-tabs button,
.segmented button {
  min-height: 38px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font-weight: 800;
}

.auth-tabs button.active,
.segmented button.active {
  background: var(--ink);
  color: #111518;
}

.form-grid {
  display: grid;
  gap: 10px;
}

label {
  display: grid;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--ink);
  outline: none;
  padding: 12px;
}

select option {
  background: #151a1f;
  color: var(--ink);
}

textarea {
  min-height: 90px;
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(0, 223, 249, 0.72);
  box-shadow: 0 0 0 3px rgba(255, 20, 157, 0.1);
}

.primary,
.secondary,
.danger,
.icon-action,
.ghost {
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-weight: 900;
  transition: transform 160ms ease, background 160ms ease, border-color 160ms ease;
}

.primary {
  background: linear-gradient(110deg, var(--faircroft-cyan), #8d65ff 52%, var(--faircroft-pink));
  color: #05050a;
  box-shadow: 0 9px 24px rgba(77, 92, 255, 0.16);
}

.secondary {
  background: rgba(255, 255, 255, 0.09);
  color: var(--ink);
  border-color: var(--line);
}

.danger {
  background: var(--red);
  color: white;
}

.primary:hover,
.secondary:hover,
.danger:hover,
.ghost:hover,
.icon-action:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 26px rgba(0, 0, 0, 0.22);
}

.primary:hover {
  background: linear-gradient(110deg, #45edff, #a27aff 52%, #ff4ab3);
}

.secondary:hover,
.ghost:hover,
.icon-action:hover {
  border-color: rgba(126, 231, 255, 0.22);
  background: rgba(255, 255, 255, 0.13);
}

.danger:hover {
  background: #ff5d74;
}

.dev-tools-hero {
  border-color: rgba(139, 255, 207, 0.28);
  background: linear-gradient(135deg, rgba(49, 86, 216, 0.2), rgba(139, 255, 207, 0.1));
}

.dev-generated-code {
  margin-top: 12px;
  border: 1px solid rgba(139, 255, 207, 0.45);
}

.dev-generated-code strong {
  color: #8bffcf;
  font-size: clamp(1.35rem, 6vw, 2rem);
  letter-spacing: 0.12em;
}

.restriction-alert {
  border-color: rgba(255, 159, 92, 0.42);
  background: rgba(114, 42, 29, 0.32);
}

.restriction-hero {
  border-color: rgba(255, 159, 92, 0.36);
}

.restriction-detail {
  display: grid;
  grid-template-columns: minmax(120px, 0.35fr) minmax(0, 1fr);
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}

.restriction-detail:last-child {
  border-bottom: 0;
}

.restriction-detail span {
  color: var(--muted);
}

.restriction-detail strong {
  overflow-wrap: anywhere;
}

.dev-account-directory {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 10px;
  margin-top: 18px;
}

.dev-account-tile,
.dev-account-row {
  color: var(--ink);
  text-align: left;
}

.dev-account-tile {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
}

.dev-account-tile div {
  display: grid;
  gap: 5px;
}

.dev-account-tile small {
  color: var(--muted);
}

.dev-account-tile:hover,
.dev-account-row:hover {
  border-color: rgba(139, 255, 207, 0.42);
  background: rgba(139, 255, 207, 0.08);
}

.dev-profile-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(2, 5, 8, 0.82);
  backdrop-filter: blur(10px);
}

.dev-profile-modal {
  width: min(1380px, 100%);
  max-height: calc(100svh - 48px);
  overflow: hidden;
  border: 1px solid rgba(139, 255, 207, 0.25);
  border-radius: 18px;
  background: #0d141a;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.62);
}

.dev-profile-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 26px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(135deg, rgba(49, 86, 216, 0.18), rgba(139, 255, 207, 0.07));
}

.dev-profile-header h2,
.dev-profile-header p {
  margin-bottom: 4px;
}

.dev-profile-scroll {
  max-height: calc(100svh - 170px);
  display: grid;
  gap: 18px;
  overflow: auto;
  padding: 24px;
}

.dev-profile-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dev-profile-summary > div {
  min-width: 0;
  display: grid;
  gap: 6px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.035);
}

.dev-profile-summary span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.dev-profile-summary strong {
  overflow-wrap: anywhere;
}

.dev-profile-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.dev-detail-list {
  max-height: 330px;
  overflow: auto;
}

.dev-detail-list > div {
  display: grid;
  gap: 5px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}

.dev-detail-list small {
  color: var(--muted);
  line-height: 1.45;
}

.dev-alert,
.dev-game-db-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px;
  border: 1px solid rgba(239, 78, 99, 0.38);
  border-radius: 12px;
  background: rgba(239, 78, 99, 0.08);
}

.dev-visibility-intro,
.dev-visibility-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.dev-visibility-intro h2,
.dev-visibility-intro p,
.dev-visibility-footer p {
  margin-bottom: 0;
}

.dev-visibility-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.dev-visibility-toggle {
  min-height: 82px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  border: 1px solid #2d3943;
  border-radius: 10px;
  padding: 14px;
  background: #151b21;
  cursor: pointer;
}

.dev-visibility-toggle > span {
  display: grid;
  gap: 5px;
}

.dev-visibility-toggle small {
  color: var(--muted);
  font-weight: 600;
}

.dev-visibility-toggle input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.dev-visibility-toggle i {
  grid-column: 2;
  grid-row: 1;
  position: relative;
  width: 48px;
  height: 27px;
  border-radius: 999px;
  background: #303944;
  box-shadow: inset 0 0 0 1px #414d58;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.dev-visibility-toggle i::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #aab4bd;
  transition: transform 160ms ease, background 160ms ease;
}

.dev-visibility-toggle input:checked + i {
  background: linear-gradient(100deg, var(--faircroft-cyan), #8d65ff 55%, var(--faircroft-pink));
  box-shadow: 0 0 20px rgba(0, 223, 249, 0.16);
}

.dev-visibility-toggle input:checked + i::after {
  transform: translateX(21px);
  background: #fff;
}

.dev-visibility-toggle:has(input:checked) {
  border-color: rgba(0, 223, 249, 0.28);
}

.dev-visibility-footer {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid #2d3943;
}

.dev-visibility-footer p {
  color: var(--muted);
  font-size: 13px;
}

/* Ravenhood tradable index funds — v15 */
.market-v15-indexes{margin:28px clamp(18px,4vw,72px) 0;border-top:1px solid rgba(99,255,184,.18);border-bottom:1px solid rgba(99,255,184,.14);padding:28px 0 30px;position:relative;overflow:hidden}
.market-v15-indexes:before{content:"";position:absolute;inset:-120px 42% auto -8%;height:260px;background:radial-gradient(circle,rgba(56,255,173,.12),transparent 68%);pointer-events:none}
.market-v15-indexes>header{display:flex;align-items:end;justify-content:space-between;gap:32px;margin-bottom:22px;position:relative}
.market-v15-indexes>header small,.market-v15-index-detail header small{display:block;color:#59e3ae;font:700 10px/1.2 var(--mono,monospace);letter-spacing:.2em}
.market-v15-indexes>header h2{margin:8px 0 5px;font-size:clamp(25px,3vw,40px);letter-spacing:-.045em}
.market-v15-indexes>header p{margin:0;max-width:760px;color:#86a29a;font-size:13px;line-height:1.6}
.market-v15-indexes>header aside{text-align:right;min-width:230px;border-left:1px solid rgba(255,255,255,.1);padding-left:24px}
.market-v15-indexes>header aside strong{display:block;margin:6px 0 2px;color:#f4fbf7;font-size:24px}
.market-v15-indexes>header aside span{color:#6f8a82;font-size:10px;text-transform:uppercase;letter-spacing:.11em}
.market-v15-indexes>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;position:relative}
.market-v15-indexes>div>button{appearance:none;text-align:left;color:#effaf5;background:linear-gradient(120deg,rgba(9,25,20,.96),rgba(10,18,19,.9));border:1px solid rgba(100,255,184,.16);border-radius:3px;padding:20px 22px 18px;min-height:178px;position:relative;overflow:hidden;cursor:pointer;transition:border-color .2s,transform .2s,background .2s}
.market-v15-indexes>div>button:after{content:"";position:absolute;right:-30px;top:-55px;width:180px;height:180px;border:1px solid rgba(83,255,183,.12);border-radius:50%;box-shadow:0 0 0 25px rgba(83,255,183,.025),0 0 0 50px rgba(83,255,183,.018)}
