/* Admin Tools role delegation */
.dev-sidebar nav button.locked {
  color: #53636a;
  background: transparent;
  border-color: transparent;
  cursor: not-allowed;
  filter: saturate(.35);
}
.dev-sidebar nav button.locked:hover {
  color: #68777d;
  background: rgba(255,255,255,.018);
  border-color: transparent;
  transform: none;
}
.dev-sidebar nav button.locked i { background: #334047; box-shadow: none; }
.dev-nav-lock {
  justify-self: end;
  color: #65747a;
  font: 800 .46rem/1 ui-monospace, monospace;
  letter-spacing: .09em;
}
.dev-admin-access-control { overflow: hidden; }
.dev-admin-access-heading,
.dev-admin-access-control footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.dev-admin-access-heading { padding-bottom: 20px; border-bottom: 1px solid var(--line); }
.dev-admin-access-heading h2 { margin: 3px 0 6px; }
.dev-admin-access-heading p:last-child { margin: 0; max-width: 850px; color: var(--muted); }
.dev-admin-access-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-left: 1px solid var(--line);
  border-top: 1px solid var(--line);
  margin-top: 20px;
}
.dev-admin-access-row {
  position: relative;
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 16px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  cursor: pointer;
  transition: background .2s ease, color .2s ease;
}
.dev-admin-access-row span { display: grid; gap: 5px; }
.dev-admin-access-row small { color: var(--muted); font-size: .68rem; }
.dev-admin-access-row input { position: absolute; opacity: 0; pointer-events: none; }
.dev-admin-access-row i {
  width: 38px; height: 20px; border-radius: 999px; flex: 0 0 auto;
  background: #2d3942; border: 1px solid #41505b; transition: .2s ease;
}
.dev-admin-access-row i::after {
  content: ""; display: block; width: 14px; height: 14px; margin: 2px;
  border-radius: 50%; background: #93a1aa; transition: transform .2s ease, background .2s ease;
}
.dev-admin-access-row:has(input:checked) { background: rgba(43,211,175,.055); color: #effffc; }
.dev-admin-access-row input:checked + i { background: rgba(43,211,175,.28); border-color: #38d8b5; }
.dev-admin-access-row input:checked + i::after { transform: translateX(18px); background: #63f0d0; }
.dev-admin-access-control footer { padding-top: 18px; }
.dev-admin-access-control footer p { margin: 0; color: var(--muted); }
@media (max-width: 900px) {
  .dev-admin-access-grid { grid-template-columns: 1fr; }
  .dev-admin-access-heading, .dev-admin-access-control footer { align-items: flex-start; flex-direction: column; }
  .dev-nav-lock { display: none; }
}

