.icon-tile {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  border: 1px solid rgba(255,255,255,.18);
  border-color: color-mix(in srgb,var(--app-accent) 42%,rgba(255,255,255,.16));
  border-radius: 21px 21px 21px 8px;
  background:
    radial-gradient(circle at 20% 8%,color-mix(in srgb,var(--app-accent) 42%,transparent),transparent 38%),
    linear-gradient(148deg,rgba(255,255,255,.13),transparent 38%,rgba(0,0,0,.28)),
    var(--tile,linear-gradient(145deg,#203037,#081015));
  box-shadow:
    0 15px 30px rgba(0,0,0,.44),
    0 0 0 1px rgba(0,0,0,.35),
    0 0 24px color-mix(in srgb,var(--app-accent) 13%,transparent),
    inset 0 1px 0 rgba(255,255,255,.32),
    inset 0 -18px 30px rgba(0,0,0,.32);
  transform: translateZ(0);
}

.icon-tile::before {
  content: "";
  position: absolute;
  z-index: 0;
  inset: 4px;
  border: 1px solid color-mix(in srgb,var(--app-accent) 26%,transparent);
  border-radius: 16px 16px 16px 5px;
  background:
    linear-gradient(115deg,transparent 0 42%,rgba(255,255,255,.1) 49%,transparent 56%),
    repeating-linear-gradient(90deg,transparent 0 12px,color-mix(in srgb,var(--app-accent) 8%,transparent) 12px 13px);
  opacity: .8;
  transform: translateX(-4%);
  transition: transform .45s cubic-bezier(.16,1,.3,1),opacity .3s ease;
  pointer-events: none;
}

.icon-tile::after {
  content: var(--app-mark);
  position: absolute;
  z-index: 3;
  right: 6px;
  bottom: 4px;
  color: color-mix(in srgb,var(--app-accent) 72%,white);
  font-family: ui-monospace,SFMono-Regular,Consolas,monospace;
  font-size: 5px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: .08em;
  opacity: .72;
  text-shadow: 0 0 8px var(--app-accent);
  pointer-events: none;
}

.icon-tile svg {
  width: 35px;
  height: 35px;
  position: relative;
  z-index: 2;
  overflow: visible;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 4px 7px rgba(0,0,0,.4)) drop-shadow(0 0 7px color-mix(in srgb,var(--app-accent) 24%,transparent));
  transition: transform .35s cubic-bezier(.16,1,.3,1),filter .3s ease;
}

.icon-tile .launcher-glyph {
  color: var(--app-ink);
  fill: none;
  stroke: currentColor;
}

.icon-tile .launcher-glyph .glyph-surface {
  fill: color-mix(in srgb,var(--app-accent) 22%,transparent);
  stroke: color-mix(in srgb,var(--app-accent) 70%,white 10%);
  stroke-width: 1.1;
}

.icon-tile .launcher-glyph .glyph-detail {
  color: var(--app-accent-2);
  stroke: currentColor;
  stroke-width: 2.35;
  filter: drop-shadow(0 0 5px color-mix(in srgb,var(--app-accent-2) 52%,transparent));
}

.app-icon:not(:disabled):hover .icon-tile::before { transform:translateX(5%); opacity:1; }
.app-icon:not(:disabled):hover .icon-tile svg { transform:translateY(-1px) scale(1.08); filter:drop-shadow(0 5px 9px rgba(0,0,0,.42)) drop-shadow(0 0 11px color-mix(in srgb,var(--app-accent) 44%,transparent)); }
.app-icon:focus-visible { outline:0; }
