.beta-operations { gap: 14px; }
.beta-command-hero {
  position: relative;
  overflow: hidden;
  padding: clamp(22px, 3vw, 36px);
  border-color: rgba(111, 225, 255, .2);
  background:
    radial-gradient(circle at 92% 5%, rgba(183, 140, 255, .19), transparent 32%),
    radial-gradient(circle at 5% 100%, rgba(48, 215, 172, .1), transparent 35%),
    #101820;
}
.beta-command-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .16;
  background-image: linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, #000, transparent 75%);
}
.beta-command-copy, .beta-command-status, .beta-command-hero .beta-dev-metrics, .beta-command-actions { position: relative; z-index: 1; }
.beta-command-copy { max-width: 720px; }
.beta-command-copy h2 { margin: 3px 0 7px; font-size: clamp(28px, 4vw, 44px); letter-spacing: -.04em; }
.beta-command-copy > p:last-child { margin: 0; color: #9babb8; line-height: 1.55; }
.beta-command-status { position: absolute; top: 28px; right: 30px; display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 2px 9px; }
.beta-command-status i { grid-row: 1 / 3; width: 9px; height: 9px; border-radius: 50%; background: #35ddab; box-shadow: 0 0 0 7px rgba(53,221,171,.1); }
.beta-command-status span { color: #6f8492; font-size: 9px; font-weight: 900; letter-spacing: .14em; }
.beta-command-status strong { color: #dffcf3; font-size: 14px; }
.beta-command-hero .beta-dev-metrics { margin: 28px 0 18px; border: 1px solid rgba(255,255,255,.08); border-radius: 10px; overflow: hidden; background: rgba(4,9,14,.42); }
.beta-command-hero .dev-metric { border-radius: 0; border: 0; border-right: 1px solid rgba(255,255,255,.08); background: transparent; }
.beta-command-hero .dev-metric:last-child { border-right: 0; }
.beta-command-actions { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }
.beta-command-actions button {
  min-height: 72px;
  display: grid;
  justify-items: start;
  align-content: center;
  gap: 5px;
  padding: 13px 16px;
