.beta-command-actions button:hover { transform: translateY(-2px); border-color: rgba(111,225,255,.36); background: rgba(111,225,255,.07); }
.beta-command-actions button.primary { color: #071014; background: linear-gradient(120deg, #42e0bd, #71d9ff); border-color: transparent; }
.beta-command-actions button span { opacity: .63; font-size: 9px; font-weight: 950; letter-spacing: .14em; }
.beta-command-actions button strong { font-size: 13px; }
.beta-assignment-strip { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 20px 24px; }
.beta-assignment-strip h2 { margin: 3px 0; font-size: 20px; }
.beta-assignment-strip p { margin: 0; color: var(--muted); }
.beta-assignment-strip button { flex: 0 0 auto; }
.beta-assignment-strip button span { margin-left: 8px; padding: 2px 7px; border-radius: 10px; background: rgba(255,255,255,.1); }
.beta-control-backdrop { z-index: 80; }
.beta-control-modal {
