}

.contract-compose {
  border: 1px solid rgba(40, 209, 124, 0.2);
  border-radius: 8px;
  padding: 12px;
  background:
    linear-gradient(180deg, rgba(9, 18, 14, 0.96), rgba(5, 8, 8, 0.94)),
