  box-shadow: inset 0 0 24px rgba(40, 209, 124, 0.04);
  animation: contractDecode 360ms ease both;
}

@keyframes contractDecode {
  from {
    opacity: 0;
    filter: blur(3px);
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0);
  }
}

.contract-card h3,
.contract-card p {
