  border-radius: 6px;
  padding: 9px;
  background: rgba(40, 209, 124, 0.045);
}

.contract-meta span {
  display: block;
  color: rgba(217, 255, 229, 0.58);
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.contract-meta strong {
  display: block;
  overflow-wrap: anywhere;
  font-size: 13px;
}

.contract-brief {
