  text-transform: uppercase;
}

.contract-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.clip-link {
  justify-self: start;
  border: 1px solid rgba(92, 156, 255, 0.24);
  border-radius: 999px;
  padding: 7px 10px;
  color: #cfe0ff;
  background: rgba(92, 156, 255, 0.11);
  font-size: 12px;
  font-weight: 900;
  text-decoration: none;
}

.contract-proof-modal {
  width: min(560px, 100%);
  grid-template-rows: auto minmax(0, 1fr);
}

.contract-info-backdrop {
  background: rgba(0, 0, 0, 0.72);
}

.contract-info-modal {
  width: min(560px, 100%);
  grid-template-rows: auto minmax(0, 1fr) auto;
  border-color: rgba(40, 209, 124, 0.28);
  background:
    linear-gradient(180deg, rgba(8, 16, 12, 0.98), rgba(4, 7, 7, 0.98)),
    repeating-linear-gradient(90deg, rgba(40, 209, 124, 0.05) 0 1px, transparent 1px 22px);
}

.contract-protocol {
  display: grid;
  gap: 9px;
}

.contract-protocol p {
  margin: 0;
  border: 1px solid rgba(40, 209, 124, 0.12);
  border-radius: 6px;
  padding: 9px;
  background: rgba(40, 209, 124, 0.045);
  color: rgba(217, 255, 229, 0.86);
  font-size: 13px;
}

.progress {
  height: 8px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}

.progress span {
  display: block;
  height: 100%;
  width: var(--pct, 0%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--green), var(--amber));
}

.segmented {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
