  background: rgba(255, 255, 255, 0.04);
}

.court-tabs {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
}

.court-tabs button {
  flex: 0 0 auto;
  min-height: 36px;
