  font-size: 12px;
  font-weight: 900;
}

.court-tabs button.active {
  background: var(--ink);
  color: #111518;
}

.court-app {
  gap: 10px;
}

.court-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid rgba(183, 140, 255, 0.18);
  border-radius: 10px;
  padding: 13px;
  background:
    linear-gradient(145deg, rgba(183, 140, 255, 0.12), rgba(92, 156, 255, 0.06)),
    rgba(255, 255, 255, 0.04);
}

.court-hero h3,
.court-hero p,
.court-case-card h3,
.court-case-card p {
  margin: 0;
}

.court-hero p:not(.eyebrow) {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
}

.court-hero-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(74px, 1fr));
  gap: 8px;
}

.court-hero-stats div {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 9px;
  background: rgba(0, 0, 0, 0.16);
}

.court-hero-stats span {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
}

.court-hero-stats strong {
  font-size: 18px;
}

.court-case-card {
  display: grid;
  gap: 9px;
  border-color: rgba(183, 140, 255, 0.16);
  background:
    linear-gradient(145deg, rgba(183, 140, 255, 0.08), rgba(255, 255, 255, 0.035)),
    rgba(0, 0, 0, 0.12);
}

.court-workspace {
  position: fixed;
  inset: 0;
  z-index: 30;
  width: 100vw;
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  color: var(--ink);
  background:
    radial-gradient(circle at 82% 0, rgba(219, 184, 90, 0.065), transparent 28%),
    linear-gradient(160deg, #0b1114, #080d10 68%);
  animation: mdtBoot 260ms ease-out both;
}

.court-workspace-topbar {
  min-height: 92px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid rgba(219, 184, 90, 0.16);
  padding: 16px 24px;
  background: rgba(10, 16, 19, 0.96);
}

.court-workspace-topbar h1,
.court-workspace-topbar p {
  margin: 0;
}

.court-workspace-topbar h1 {
  margin: 2px 0 3px;
  font-size: clamp(25px, 2.6vw, 36px);
  letter-spacing: -0.025em;
}

.court-workspace-topbar p:not(.eyebrow) {
  color: rgba(205, 218, 216, 0.56);
  font-size: 11px;
}

.court-workspace-actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

.court-session-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-right: 6px;
  color: rgba(205, 218, 216, 0.62);
  font-size: 10px;
  font-weight: 850;
  text-transform: uppercase;
}

.court-session-status i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #dbb85a;
  box-shadow: 0 0 12px rgba(219, 184, 90, 0.52);
}

.court-workspace-content {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 20px 24px 28px;
  scrollbar-gutter: stable;
}

.court-workspace-content > .court-app {
  width: min(1580px, 100%);
  margin: 0 auto;
}

.court-workspace .court-identity {
  min-height: 112px;
  padding: 20px 22px;
}

.court-workspace .court-identity h3 {
  font-size: 30px;
}

.court-workspace .court-seal {
  width: 62px;
  height: 62px;
}

.court-workspace .court-bench-tabs {
  overflow: hidden;
  border: 1px solid rgba(219, 184, 90, 0.12);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.018);
}

.court-workspace .court-bench-tabs button {
  min-height: 48px;
}

.court-workspace .court-bench-layout {
  grid-template-columns: minmax(300px, 360px) minmax(0, 1fr);
  min-height: calc(100dvh - 315px);
}

.court-workspace .court-docket-list {
  max-height: calc(100dvh - 235px);
  overflow-y: auto;
  scrollbar-width: thin;
}

.court-workspace .court-docket-list > button {
  min-height: 72px;
  padding: 12px;
}

.court-workspace .court-docket-list button strong {
  font-size: 11px;
}

.court-workspace .court-case-file {
  overflow: visible;
}

.court-workspace .court-file > header {
  padding: 20px;
}

.court-workspace .court-file h3 {
  font-size: clamp(20px, 2vw, 28px);
}

.court-workspace .court-file-meta div,
.court-workspace .court-allegation,
.court-workspace .court-decision-form {
  padding: 18px 20px;
}

.court-workspace .court-file-meta dd {
  font-size: 13px;
}

.court-workspace .court-allegation p {
  max-width: 960px;
  font-size: 14px;
}

.court-workspace .court-decision-form {
  gap: 14px;
}

@media (max-width: 900px) {
  .court-workspace-topbar {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }

  .court-workspace-actions {
    width: 100%;
  }

  .court-session-status {
    margin-right: auto;
  }

  .court-workspace-content {
    padding: 14px;
  }

  .court-workspace .court-bench-layout {
    display: block;
  }

  .court-workspace .court-docket-list {
    max-height: 260px;
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  }
}

@media (max-width: 640px) {
  .court-workspace-topbar {
    min-height: 0;
    padding: max(12px, env(safe-area-inset-top)) 12px 11px;
  }

  .court-workspace-topbar h1 {
    font-size: 25px;
  }

  .court-workspace-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .court-workspace-actions button {
    width: 100%;
    min-width: 0;
  }

  .court-session-status {
    grid-column: 1 / -1;
  }

  .court-workspace-content {
    padding: 9px;
  }

  .court-workspace .court-identity {
    min-height: 0;
  }
}

