@keyframes drawerFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes mobileDrawerLeft {
  from {
    opacity: 0;
    transform: translateX(-18px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes mobileDrawerRight {
  from {
    opacity: 0;
    transform: translateX(18px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
    scroll-behavior: auto !important;
  }
}

/* Faircroft community roadmap */
.roadmap-workspace {
  position: fixed;
  inset: 0;
  z-index: 35;
  width: 100vw;
  height: 100dvh;
  min-height: 100svh;
  overflow: hidden;
  color: #f5f7f4;
  background:
    linear-gradient(180deg, rgba(9, 13, 14, 0.98), rgba(13, 17, 18, 1)),
    repeating-linear-gradient(90deg, transparent 0 79px, rgba(255, 255, 255, 0.025) 80px),
    repeating-linear-gradient(0deg, transparent 0 79px, rgba(255, 255, 255, 0.018) 80px);
  animation: roadmapWorkspaceIn 360ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.roadmap-workspace button {
  color: inherit;
}

.roadmap-topbar {
  position: absolute;
  z-index: 6;
  inset: 0 0 auto;
  min-height: 72px;
  display: grid;
  grid-template-columns: minmax(110px, 1fr) auto minmax(110px, 1fr);
  align-items: center;
  gap: 20px;
  padding: max(12px, env(safe-area-inset-top)) 24px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(8, 11, 12, 0.91);
  backdrop-filter: blur(18px);
}

.roadmap-back,
.roadmap-command,
.roadmap-refresh,
.roadmap-edit {
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.045);
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.roadmap-back:hover,
.roadmap-command:hover,
.roadmap-refresh:hover,
.roadmap-edit:hover {
  border-color: rgba(86, 227, 162, 0.52);
  background: rgba(86, 227, 162, 0.09);
  transform: translateY(-1px);
}

.roadmap-back {
  justify-self: start;
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 13px 0 9px;
  font-size: 13px;
  font-weight: 850;
}

.roadmap-back svg,
.roadmap-command svg,
.roadmap-edit svg {
  width: 19px;
  height: 19px;
  stroke-width: 1.8;
}

.roadmap-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.roadmap-brand-mark,
.roadmap-footer-mark {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(232, 184, 74, 0.72);
  border-radius: 6px;
  color: #171408;
  background: #e8b84a;
  font-size: 12px;
  font-weight: 1000;
  box-shadow: 0 0 24px rgba(232, 184, 74, 0.13);
}

.roadmap-brand p,
.roadmap-brand strong {
  display: block;
  margin: 0;
  letter-spacing: 0;
}

.roadmap-brand p {
  color: rgba(255, 255, 255, 0.46);
  font-size: 9px;
  font-weight: 900;
}

.roadmap-brand strong {
  margin-top: 2px;
  font-size: 16px;
}

.roadmap-top-actions {
  justify-self: end;
  display: flex;
  gap: 8px;
}

.roadmap-command {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  font-size: 12px;
  font-weight: 850;
}

.roadmap-refresh {
  width: 42px;
  height: 42px;
  font-size: 21px;
}

.roadmap-scroll {
  position: absolute;
  inset: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: calc(94px + env(safe-area-inset-top)) 24px max(34px, env(safe-area-inset-bottom));
  scroll-behavior: smooth;
}

.roadmap-intro,
.roadmap-telemetry,
.roadmap-filters,
.roadmap-route,
.roadmap-footer {
  width: min(1180px, 100%);
  margin-inline: auto;
}

.roadmap-intro {
  min-height: 330px;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.5fr);
  align-items: center;
  gap: 54px;
  padding: 44px 0 38px;
}

.roadmap-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 18px;
  color: #8feabb;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0;
}

.roadmap-kicker span {
  width: 26px;
  height: 2px;
  background: #56e3a2;
  box-shadow: 0 0 12px rgba(86, 227, 162, 0.7);
}

.roadmap-intro h1 {
  max-width: 820px;
  margin: 0;
  font-size: 56px;
  line-height: 0.98;
  letter-spacing: 0;
  font-weight: 950;
}

