  color: #e8b84a;
  font-style: normal;
}

.roadmap-intro-copy > p:last-child {
  max-width: 760px;
  margin: 24px 0 0;
  color: rgba(245, 247, 244, 0.62);
  font-size: 16px;
  line-height: 1.65;
}

.roadmap-launch-countdown {
  position: relative;
  min-height: 190px;
  display: grid;
  align-content: center;
  padding: 28px 0 28px 34px;
  border-left: 1px solid rgba(232, 184, 74, 0.46);
}

.roadmap-launch-countdown::before,
.roadmap-launch-countdown::after {
  content: "";
  position: absolute;
  left: -4px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #e8b84a;
}

.roadmap-launch-countdown::before {
  top: 0;
}

.roadmap-launch-countdown::after {
  bottom: 0;
}

.roadmap-launch-countdown span,
.roadmap-launch-countdown p {
  margin: 0;
  color: rgba(255, 255, 255, 0.52);
  font-size: 10px;
  font-weight: 850;
}

.roadmap-launch-countdown strong {
  margin: 10px 0 7px;
  color: #fff4cf;
  font-size: 42px;
  line-height: 1;
}

.roadmap-telemetry {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-block: 1px solid rgba(255, 255, 255, 0.11);
}

.roadmap-telemetry > div:not(.roadmap-master-progress) {
  min-height: 88px;
  display: grid;
  align-content: center;
  gap: 5px;
  padding: 16px 22px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.roadmap-telemetry > div:nth-child(4) {
  border-right: 0;
}

.roadmap-telemetry span {
  color: rgba(255, 255, 255, 0.45);
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.roadmap-telemetry strong {
  font-size: 26px;
}

.roadmap-master-progress {
  position: absolute;
  inset: auto 0 -2px;
  height: 3px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.05);
}

.roadmap-master-progress span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #56e3a2, #e8b84a, #e45f55);
  box-shadow: 0 0 18px rgba(86, 227, 162, 0.4);
  animation: roadmapProgressIn 900ms ease-out both;
}

.roadmap-filters {
  display: flex;
  gap: 6px;
  padding: 32px 0 10px;
  overflow-x: auto;
  scrollbar-width: none;
}

.roadmap-filters::-webkit-scrollbar {
  display: none;
}

.roadmap-filters button {
  flex: 0 0 auto;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 0 13px;
  border: 1px solid transparent;
  border-radius: 5px;
  color: rgba(255, 255, 255, 0.55);
  background: transparent;
  font-size: 12px;
  font-weight: 800;
}

.roadmap-filters button span {
  min-width: 21px;
  padding: 2px 6px;
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.08);
  font-size: 10px;
}

.roadmap-filters button.active {
  border-color: rgba(86, 227, 162, 0.34);
  color: #d9ffeb;
  background: rgba(86, 227, 162, 0.08);
}

.roadmap-route {
  --route-gap: 64px;
  position: relative;
  display: flow-root;
  padding: 54px 0 90px;
}

.roadmap-route-line {
  position: absolute;
  z-index: 0;
  top: 18px;
  bottom: 40px;
  left: 50%;
  width: 2px;
  transform: translateX(-1px);
  background: linear-gradient(180deg, #56e3a2 0 38%, #e8b84a 58%, #e45f55 78%, rgba(255, 255, 255, 0.12));
  box-shadow: 0 0 28px rgba(86, 227, 162, 0.13);
}

.roadmap-route-line::before,
.roadmap-route-line::after {
  content: "";
  position: absolute;
  left: 50%;
  width: 12px;
  height: 12px;
  border: 2px solid #56e3a2;
  border-radius: 50%;
  background: #0b1010;
  transform: translateX(-50%);
}

.roadmap-route-line::before {
  top: -4px;
}

.roadmap-route-line::after {
  bottom: -4px;
  border-color: rgba(255, 255, 255, 0.3);
}

.roadmap-route-line span {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0 20px, rgba(255, 255, 255, 0.42) 21px 24px, transparent 25px 42px);
  animation: roadmapLaneFlow 2.2s linear infinite;
}

.roadmap-route-line i {
  position: absolute;
  left: 50%;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #f6d87f;
  box-shadow: 0 0 0 5px rgba(232, 184, 74, 0.12), 0 0 20px rgba(232, 184, 74, 0.75);
  transform: translateX(-50%);
  animation: roadmapTraveler 9s ease-in-out infinite;
}

.roadmap-stop {
  --roadmap-accent: #56e3a2;
  position: relative;
  z-index: 1;
  width: calc(50% - var(--route-gap));
  margin-bottom: 74px;
  opacity: 0;
  transform: translateX(-22px);
  transition: opacity 520ms ease, transform 620ms cubic-bezier(0.2, 0.8, 0.2, 1);
  transition-delay: calc((var(--stop-index) % 3) * 70ms);
}

.roadmap-stop:nth-of-type(even) {
  margin-left: calc(50% + var(--route-gap));
  transform: translateX(22px);
}

.roadmap-stop.in-view {
  opacity: 1;
  transform: translateX(0);
}

.roadmap-stop.accent-gold {
  --roadmap-accent: #e8b84a;
}

.roadmap-stop.accent-coral {
  --roadmap-accent: #e66b62;
}

.roadmap-stop.accent-cyan {
  --roadmap-accent: #63d9e6;
}

.roadmap-stop.accent-violet {
  --roadmap-accent: #b69bdf;
}

.roadmap-node {
  position: absolute;
  z-index: 3;
  top: 30px;
  right: -80px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 2px solid var(--roadmap-accent);
  border-radius: 50%;
  background: #0c1111;
  box-shadow: 0 0 0 8px rgba(10, 14, 15, 0.92), 0 0 22px color-mix(in srgb, var(--roadmap-accent) 45%, transparent);
}

.roadmap-stop:nth-of-type(even) .roadmap-node {
  right: auto;
  left: -80px;
}

.roadmap-node span {
  color: var(--roadmap-accent);
  font-size: 9px;
  font-weight: 950;
}

.roadmap-stop-content {
  position: relative;
  padding: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-top: 2px solid var(--roadmap-accent);
  border-radius: 7px;
  background: rgba(17, 22, 23, 0.88);
  box-shadow: 0 22px 58px rgba(0, 0, 0, 0.24);
}

.roadmap-stop-content::before {
  content: "";
  position: absolute;
  top: 45px;
  right: calc(var(--route-gap) * -1);
  width: var(--route-gap);
  height: 1px;
  background: linear-gradient(90deg, var(--roadmap-accent), rgba(255, 255, 255, 0.1));
}

.roadmap-stop:nth-of-type(even) .roadmap-stop-content::before {
  right: auto;
  left: calc(var(--route-gap) * -1);
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.1), var(--roadmap-accent));
}

.roadmap-stop-head {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: start;
  gap: 13px;
}

.roadmap-stop-icon {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--roadmap-accent) 46%, transparent);
  border-radius: 7px;
  color: var(--roadmap-accent);
  background: color-mix(in srgb, var(--roadmap-accent) 9%, transparent);
}

.roadmap-stop-icon svg {
  width: 24px;
  height: 24px;
  stroke-width: 1.7;
}

.roadmap-stop-head p,
.roadmap-stop-head h2 {
  margin: 0;
}

.roadmap-stop-head p {
  color: var(--roadmap-accent);
  font-size: 9px;
  font-weight: 950;
  text-transform: uppercase;
}

.roadmap-stop-head h2 {
  margin-top: 5px;
  font-size: 22px;
  line-height: 1.12;
}

.roadmap-status {
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--roadmap-accent) 34%, transparent);
  border-radius: 999px;
  color: var(--roadmap-accent);
  background: color-mix(in srgb, var(--roadmap-accent) 8%, transparent);
  font-size: 9px;
  font-weight: 950;
  text-transform: uppercase;
  white-space: nowrap;
}

.roadmap-summary {
  margin: 19px 0 16px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 14px;
  line-height: 1.6;
}

.roadmap-progress-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}

.roadmap-progress-track {
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
}

.roadmap-progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--roadmap-accent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--roadmap-accent) 55%, transparent);
  animation: roadmapProgressIn 850ms ease-out both;
}

.roadmap-progress-row > strong {
  color: var(--roadmap-accent);
  font-size: 12px;
}

.roadmap-notes {
  margin-top: 15px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.roadmap-notes summary {
  padding: 13px 0 0;
  color: rgba(255, 255, 255, 0.54);
  font-size: 11px;
  font-weight: 850;
  cursor: pointer;
}

.roadmap-notes p {
  margin: 11px 0 0;
  color: rgba(255, 255, 255, 0.61);
  font-size: 13px;
  line-height: 1.58;
}

.roadmap-stop-footer {
  min-height: 41px;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-top: 18px;
}

.roadmap-votes {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.roadmap-votes button {
  min-width: 54px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 5px;
  color: rgba(255, 255, 255, 0.62);
  background: rgba(255, 255, 255, 0.035);
}

.roadmap-votes button:hover {
  border-color: rgba(255, 255, 255, 0.28);
}

.roadmap-votes button.active.up {
  border-color: rgba(86, 227, 162, 0.55);
  color: #a9ffd1;
  background: rgba(86, 227, 162, 0.11);
}

.roadmap-votes button.active.down {
  border-color: rgba(230, 107, 98, 0.55);
  color: #ffb5af;
  background: rgba(230, 107, 98, 0.11);
}

.roadmap-votes svg {
  width: 16px;
  height: 16px;
}

.roadmap-votes button span,
.roadmap-votes > strong {
  font-size: 11px;
  font-weight: 900;
}

.roadmap-votes > strong {
  min-width: 29px;
  color: #9ce8bc;
  text-align: center;
}

.roadmap-votes > strong.negative {
  color: #e9968f;
}

.roadmap-edit {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  color: rgba(255, 255, 255, 0.67);
  font-size: 10px;
  font-weight: 850;
}

.roadmap-edit svg {
  width: 15px;
  height: 15px;
}

.roadmap-signal-label {
  color: rgba(255, 255, 255, 0.27);
  font-size: 8px;
  font-weight: 950;
}

.roadmap-empty {
  position: relative;
  z-index: 2;
  max-width: 560px;
  margin: 70px auto;
  padding: 30px;
  border: 1px dashed rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.54);
  background: #0d1213;
  text-align: center;
}

.roadmap-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 26px 0 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
}

.roadmap-footer > div {
  display: flex;
  align-items: center;
  gap: 10px;
}

.roadmap-footer-mark {
  width: 28px;
  height: 28px;
  font-size: 9px;
}

.roadmap-footer strong,
.roadmap-footer p {
  margin: 0;
  color: rgba(255, 255, 255, 0.42);
  font-size: 9px;
  font-weight: 900;
}

.roadmap-editor-backdrop {
  position: fixed;
  z-index: 50;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(3, 6, 7, 0.76);
  backdrop-filter: blur(10px);
  animation: drawerFade 180ms ease-out both;
}

.roadmap-editor {
  width: min(820px, 100%);
  max-height: min(820px, calc(100dvh - 48px));
  overflow: auto;
  border: 1px solid rgba(86, 227, 162, 0.3);
  border-radius: 8px;
  background: #121819;
  box-shadow: 0 32px 100px rgba(0, 0, 0, 0.58);
  animation: roadmapEditorIn 260ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.roadmap-editor > header {
  position: sticky;
  z-index: 2;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(18, 24, 25, 0.96);
  backdrop-filter: blur(12px);
}

.roadmap-editor header p,
.roadmap-editor header h2 {
  margin: 0;
}

.roadmap-editor header p {
  color: #56e3a2;
  font-size: 9px;
  font-weight: 950;
}

.roadmap-editor header h2 {
  margin-top: 4px;
  font-size: 24px;
}

.roadmap-editor header button {
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 5px;
  color: rgba(255, 255, 255, 0.72);
  background: rgba(255, 255, 255, 0.04);
  font-size: 22px;
}

.roadmap-editor form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  padding: 22px;
}

.roadmap-editor label {
  display: grid;
  gap: 7px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  font-weight: 850;
}

.roadmap-editor input,
.roadmap-editor textarea,
.roadmap-editor select {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 5px;
  color: #f5f7f4;
  background: #0c1112;
}

.roadmap-editor input,
.roadmap-editor select {
  min-height: 44px;
  padding: 0 11px;
}

.roadmap-editor textarea {
  min-height: 92px;
  padding: 11px;
  resize: vertical;
}

.roadmap-editor-wide,
.roadmap-visibility,
.roadmap-editor-actions {
  grid-column: 1 / -1;
}

.roadmap-progress-input {
  grid-template-columns: 1fr auto;
  align-items: center;
}

.roadmap-progress-input input {
  grid-column: 1 / -1;
  min-height: 24px;
  padding: 0;
  accent-color: #56e3a2;
}

.roadmap-progress-input output {
  color: #9bf1c2;
}

.roadmap-visibility {
  display: flex !important;
  align-items: center;
  gap: 9px !important;
  min-height: 42px;
}

.roadmap-visibility input {
  width: 18px;
  min-height: 18px;
  accent-color: #56e3a2;
}

.roadmap-editor-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 8px;
}

.roadmap-editor-actions button {
  min-height: 43px;
  padding-inline: 16px;
}

@keyframes roadmapWorkspaceIn {
  from {
    opacity: 0;
    transform: scale(0.992);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes roadmapProgressIn {
  from {
    width: 0;
  }
}

@keyframes roadmapLaneFlow {
  to {
    transform: translateY(42px);
  }
}

@keyframes roadmapTraveler {
  0%,
  100% {
    top: 2%;
  }
  50% {
    top: 94%;
  }
}

@keyframes roadmapEditorIn {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 900px) {
  .roadmap-intro {
    min-height: 290px;
    grid-template-columns: minmax(0, 1fr) 230px;
    gap: 30px;
  }

  .roadmap-intro h1 {
    font-size: 42px;
  }

  .roadmap-launch-countdown strong {
    font-size: 34px;
  }

  .roadmap-stop-head {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .roadmap-status {
    grid-column: 2;
    justify-self: start;
  }
}

@media (max-width: 720px) {
  .roadmap-topbar {
    min-height: 64px;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 10px;
    padding: max(9px, env(safe-area-inset-top)) 10px 9px;
  }

  .roadmap-back {
    width: 42px;
    min-height: 42px;
    justify-content: center;
    padding: 0;
  }

  .roadmap-back span,
  .roadmap-command span,
  .roadmap-brand p {
    display: none;
  }

  .roadmap-brand {
    gap: 8px;
  }

  .roadmap-brand-mark {
    width: 32px;
    height: 32px;
  }

  .roadmap-brand strong {
    font-size: 14px;
  }

  .roadmap-command {
    width: 42px;
    padding: 0;
    justify-content: center;
  }

  .roadmap-scroll {
    padding: calc(75px + env(safe-area-inset-top)) 13px max(24px, env(safe-area-inset-bottom));
  }

  .roadmap-intro {
    min-height: 0;
    grid-template-columns: 1fr;
    gap: 26px;
    padding: 36px 0 30px;
  }

  .roadmap-intro h1 {
    font-size: 36px;
    line-height: 1.02;
  }

  .roadmap-intro-copy > p:last-child {
    margin-top: 18px;
    font-size: 14px;
  }

  .roadmap-launch-countdown {
    min-height: 98px;
    padding: 14px 0 14px 22px;
  }

  .roadmap-launch-countdown strong {
    font-size: 30px;
  }

  .roadmap-telemetry {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .roadmap-telemetry > div:not(.roadmap-master-progress) {
    min-height: 72px;
    padding: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .roadmap-telemetry > div:nth-child(2) {
    border-right: 0;
  }

  .roadmap-telemetry > div:nth-child(3),
  .roadmap-telemetry > div:nth-child(4) {
    border-bottom: 0;
  }

  .roadmap-telemetry strong {
    font-size: 22px;
  }

  .roadmap-filters {
    padding-top: 25px;
  }

  .roadmap-route {
    --route-gap: 0px;
    padding: 42px 0 64px 55px;
  }

  .roadmap-route-line {
    left: 24px;
    transform: none;
  }

  .roadmap-stop,
  .roadmap-stop:nth-of-type(even) {
    width: 100%;
    margin: 0 0 42px;
    transform: translateX(18px);
  }

  .roadmap-stop.in-view,
  .roadmap-stop:nth-of-type(even).in-view {
    transform: translateX(0);
  }

  .roadmap-node,
  .roadmap-stop:nth-of-type(even) .roadmap-node {
    top: 25px;
    right: auto;
    left: -47px;
  }

  .roadmap-stop-content {
    padding: 18px;
  }

  .roadmap-stop-content::before,
  .roadmap-stop:nth-of-type(even) .roadmap-stop-content::before {
    top: 40px;
    right: auto;
    left: -31px;
    width: 31px;
    background: linear-gradient(90deg, rgba(255, 255, 255, 0.12), var(--roadmap-accent));
  }

  .roadmap-stop-head h2 {
    font-size: 19px;
  }

  .roadmap-stop-footer {
    align-items: center;
  }

  .roadmap-signal-label {
    display: none;
  }

  .roadmap-footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .roadmap-editor-backdrop {
    align-items: end;
    padding: 0;
  }

  .roadmap-editor {
    width: 100%;
    max-height: calc(100dvh - max(20px, env(safe-area-inset-top)));
    border-width: 1px 0 0;
    border-radius: 8px 8px 0 0;
  }

  .roadmap-editor form {
    grid-template-columns: 1fr;
    padding: 16px;
  }

  .roadmap-editor-wide,
  .roadmap-visibility,
  .roadmap-editor-actions {
    grid-column: auto;
  }
}

@media (max-width: 390px) {
  .roadmap-intro h1 {
    font-size: 31px;
  }

  .roadmap-top-actions {
    gap: 5px;
  }

  .roadmap-refresh,
  .roadmap-command {
    width: 38px;
    height: 38px;
    min-height: 38px;
  }

  .roadmap-stop-head {
    grid-template-columns: 38px minmax(0, 1fr);
    gap: 10px;
  }

  .roadmap-stop-icon {
    width: 38px;
    height: 38px;
  }

  .roadmap-stop-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .roadmap-edit {
    justify-content: center;
  }
}
