.anticheat-lock-alert { border-color: rgba(255, 89, 100, .45); background: rgba(255, 89, 100, .12); }
.anticheat-lock-alert svg { color: #ff7680; }
.anticheat-lock-card { display: grid; gap: 12px; }
.anticheat-lock-apps { grid-template-columns: repeat(1, minmax(0, 112px)); }
.anticheat-lock-console { display: grid; gap: 12px; }
.anticheat-removal-list {
