/* Elite CAD shell: visual-only enhancements preserve the existing MDT workflows. */
.mdt-redesign {
  --mdt-cyan: #75efff;
  --mdt-green: #38e596;
  --mdt-panel: rgba(7, 15, 18, 0.94);
}

.mdt-redesign .mdt-topbar {
  min-height: 92px;
  background:
    radial-gradient(circle at 18% 0%, rgba(56, 229, 150, 0.09), transparent 36%),
    linear-gradient(90deg, rgba(7, 17, 20, 0.86), transparent 70%);
}

.mdt-live-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
}

.mdt-live-kicker b {
  color: rgba(117, 239, 255, 0.66);
  font-size: 9px;
  letter-spacing: 0.12em;
}

.mdt-live-dot,
.mdt-system-band b {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--mdt-green);
  box-shadow: 0 0 0 4px rgba(56, 229, 150, 0.09), 0 0 16px rgba(56, 229, 150, 0.72);
  animation: mdtSignal 1.8s ease-in-out infinite;
}

@keyframes mdtSignal {
  0%, 100% { opacity: 0.72; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1.12); }
}

.mdt-redesign .mdt-top-actions button {
  position: relative;
  overflow: hidden;
  min-height: 42px;
  padding-inline: 17px;
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.mdt-redesign .mdt-top-actions button:hover {
  transform: translateY(-2px);
  border-color: rgba(117, 239, 255, 0.42);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.34), inset 0 0 18px rgba(117, 239, 255, 0.035);
}

.mdt-redesign .mdt-stat-strip .metric {
  position: relative;
  overflow: hidden;
  transition: background 180ms ease;
}

.mdt-redesign .mdt-stat-strip .metric::after {
  content: "";
  position: absolute;
  inset: auto 12px 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--mdt-cyan), transparent);
  opacity: 0;
  transform: scaleX(0.2);
  transition: opacity 180ms ease, transform 180ms ease;
}

.mdt-redesign .mdt-stat-strip .metric:hover {
  background: rgba(117, 239, 255, 0.04);
}

.mdt-redesign .mdt-stat-strip .metric:hover::after {
  opacity: 0.8;
  transform: scaleX(1);
}

.mdt-redesign .mdt-layout {
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.42), 0 0 0 1px rgba(117, 239, 255, 0.025);
}

.mdt-redesign .mdt-nav button::after {
  content: "";
  position: absolute;
  right: 8px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.22;
}

.mdt-redesign .mdt-nav button.active::after {
  opacity: 0.72;
  box-shadow: 0 0 10px currentColor;
}

.mdt-redesign .mdt-main > * {
  animation: mdtPanelIn 260ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes mdtPanelIn {
  from { opacity: 0; transform: translateY(8px) scale(0.995); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.mdt-launchpad {
  display: grid;
  gap: 10px;
}

.mdt-launch-hero {
  position: relative;
  min-height: 128px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  overflow: hidden;
  border: 1px solid rgba(117, 239, 255, 0.14);
  border-left: 3px solid var(--mdt-green);
  border-radius: 8px;
  padding: 18px 22px;
  background:
    radial-gradient(circle at 85% 40%, rgba(117, 239, 255, 0.11), transparent 24%),
    linear-gradient(120deg, rgba(56, 229, 150, 0.09), rgba(6, 13, 16, 0.72) 55%);
}

.mdt-launch-hero h2 {
  margin: 2px 0 5px;
  font-size: clamp(24px, 2.6vw, 38px);
}

.mdt-launch-hero p:not(.eyebrow) {
  max-width: 680px;
  margin: 0;
  color: rgba(220, 241, 240, 0.64);
  font-size: 12px;
}

.mdt-radar {
  position: relative;
  width: 86px;
  height: 86px;
  flex: 0 0 86px;
  border: 1px solid rgba(117, 239, 255, 0.3);
  border-radius: 50%;
  background:
    linear-gradient(90deg, transparent 49%, rgba(117, 239, 255, 0.15) 50%, transparent 51%),
    linear-gradient(0deg, transparent 49%, rgba(117, 239, 255, 0.15) 50%, transparent 51%);
  box-shadow: inset 0 0 28px rgba(117, 239, 255, 0.07), 0 0 38px rgba(117, 239, 255, 0.05);
}

.mdt-radar::before,
.mdt-radar::after {
  content: "";
  position: absolute;
  inset: 20%;
  border: 1px solid rgba(117, 239, 255, 0.18);
  border-radius: 50%;
}

.mdt-radar::after { inset: 40%; }

.mdt-radar span {
  position: absolute;
  inset: 50% 50% 50% 0;
  transform-origin: right center;
  border-top: 1px solid var(--mdt-green);
  filter: drop-shadow(0 0 5px var(--mdt-green));
  animation: mdtRadar 3s linear infinite;
}

.mdt-radar i {
  position: absolute;
  top: 27%;
  right: 23%;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--mdt-green);
  box-shadow: 0 0 12px var(--mdt-green);
}

@keyframes mdtRadar { to { transform: rotate(360deg); } }

.mdt-launch-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.mdt-launch-grid button {
  position: relative;
  min-height: 118px;
  display: grid;
  align-content: center;
  gap: 5px;
  overflow: hidden;
  border: 1px solid rgba(117, 239, 255, 0.1);
  border-radius: 7px;
  padding: 15px 48px 15px 16px;
  color: var(--ink);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.035), rgba(117, 239, 255, 0.012));
  text-align: left;
  transition: transform 190ms ease, border-color 190ms ease, background 190ms ease;
}

.mdt-launch-grid button::after {
  content: "›";
  position: absolute;
  right: 17px;
  top: 50%;
  color: rgba(117, 239, 255, 0.5);
  font-size: 30px;
  transform: translateY(-50%);
  transition: transform 190ms ease, color 190ms ease;
}

.mdt-launch-grid button:hover {
  transform: translateY(-3px);
  border-color: rgba(56, 229, 150, 0.38);
  background: linear-gradient(135deg, rgba(56, 229, 150, 0.09), rgba(117, 239, 255, 0.025));
}

.mdt-launch-grid button:hover::after {
  color: var(--mdt-green);
  transform: translate(4px, -50%);
}

.mdt-launch-index {
  color: rgba(117, 239, 255, 0.62);
  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.11em;
}

.mdt-launch-grid strong { font-size: 17px; }
.mdt-launch-grid small { color: rgba(220, 241, 240, 0.57); line-height: 1.35; }
.mdt-launch-grid i { color: rgba(56, 229, 150, 0.72); font-size: 10px; font-style: normal; font-weight: 950; text-transform: uppercase; }

.mdt-system-band {
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 38px;
  overflow-x: auto;
  border: 1px solid rgba(117, 239, 255, 0.08);
  border-radius: 6px;
  padding: 0 12px;
  background: rgba(0, 0, 0, 0.18);
  color: rgba(220, 241, 240, 0.52);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.mdt-system-band span {
  display: flex;
  align-items: center;
  gap: 7px;
}

.mdt-system-band span:last-child {
  margin-left: auto;
  color: rgba(117, 239, 255, 0.54);
}

.mdt-redesign .modal-backdrop {
  background:
    radial-gradient(circle at 50% 45%, rgba(56, 229, 150, 0.055), transparent 35%),
    rgba(0, 4, 6, 0.76);
  backdrop-filter: blur(13px) saturate(0.85);
}

.mdt-redesign .mdt-modal {
  box-shadow: 0 34px 110px rgba(0, 0, 0, 0.72), 0 0 0 1px rgba(117, 239, 255, 0.05);
  animation: mdtEliteModal 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes mdtEliteModal {
  from { opacity: 0; transform: translateY(24px) scale(0.96); filter: blur(7px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@media (max-width: 760px) {
  .mdt-launch-grid { grid-template-columns: 1fr; }
  .mdt-launch-hero { min-height: 112px; padding: 14px; }
  .mdt-radar { width: 66px; height: 66px; flex-basis: 66px; }
  .mdt-system-band { gap: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .mdt-redesign *,
  .mdt-redesign *::before,
  .mdt-redesign *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

