.citation-workflow-nav span:last-child { border-right: 0; }
.citation-workflow-nav span.active { color: rgba(222, 247, 242, 0.9); box-shadow: inset 0 -2px 0 #38e596; }
.citation-workflow-nav b { color: #38e596; font-size: 9px; }

.citation-writer-layout {
  display: grid;
