.citation-code-actions button {
  min-height: 34px;
  font-size: 10px;
}

.citation-narrative-note {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 9px;
  border-left: 2px solid rgba(117, 239, 255, 0.32);
  padding: 8px 10px;
  color: rgba(193, 215, 211, 0.48);
  background: rgba(117, 239, 255, 0.025);
  font-size: 9px;
}

.citation-narrative-note strong {
  color: rgba(211, 232, 228, 0.74);
  text-transform: uppercase;
}

.citation-review-panel {
  align-self: start;
