.citation-review-panel dt {
  color: rgba(172, 198, 194, 0.44);
  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.citation-review-panel dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: rgba(232, 247, 244, 0.82);
  font-size: 10px;
  font-weight: 850;
