}

.citation-review-rule {
  height: 1px;
  background: rgba(117, 239, 255, 0.09);
}

.citation-review-panel > p {
  margin: 0;
  color: rgba(193, 215, 211, 0.46);
  font-size: 9px;
  line-height: 1.5;
}

.citation-file-button {
  min-height: 54px;
  display: grid;
  place-items: center;
  gap: 1px;
  border: 0;
  border-radius: 4px;
  color: #03100d;
