.citation-file-button span { font-size: 12px; font-weight: 950; }
.citation-file-button small { color: rgba(3, 16, 13, 0.66); font-size: 8px; font-weight: 900; text-transform: uppercase; }

.citation-mode-link {
  min-height: 36px;
  border: 0;
  color: rgba(193, 215, 211, 0.54);
  background: transparent;
  font-size: 9px;
  text-decoration: underline;
