}

@media (max-width: 900px) {
  .citation-writer-layout { grid-template-columns: 1fr; }
  .citation-form-body { border-right: 0; }
  .citation-review-panel { position: static; border-top: 1px solid rgba(117, 239, 255, 0.1); }
}

@media (max-width: 640px) {
  .citation-writer-head { align-items: flex-start; flex-direction: column; padding: 15px; }
  .citation-writer-ref { width: 100%; align-items: start; justify-items: start; border-left: 0; border-top: 1px solid rgba(117, 239, 255, 0.1); padding: 10px 0 0; }
  .citation-workflow-nav { grid-template-columns: repeat(2, minmax(0, 1fr)); }
