.game-intel-pulse span { font-size: .78rem; font-weight: 800; text-transform: uppercase; }
.game-intel-pulse small { color: #73848d; }
.game-intel-score { border-left: 1px solid rgba(255,255,255,.1); display: grid; min-width: 230px; padding-left: 30px; }
.game-intel-score span, .game-intel-statline span { color: #74858e; font-size: .65rem; font-weight: 900; letter-spacing: .15em; }
.game-intel-score strong { color: #fff; font-size: 3.4rem; letter-spacing: -.06em; }
.game-intel-score small { color: var(--intel-cyan); }
.game-intel-statline { display: grid; gap: 10px; grid-template-columns: repeat(4, 1fr); }
.game-intel-statline article { background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.07); border-radius: 14px; display: grid; gap: 5px; padding: 18px; }
.game-intel-statline strong { font-size: 1.15rem; }
.game-intel-statline small { color: #73848d; }
.game-intel-layout { display: grid; gap: 14px; grid-template-columns: 1.05fr 1fr; }
.game-intel-collection-grid { display: grid; gap: 7px; grid-template-columns: repeat(2, 1fr); }
.game-intel-collection-grid article { align-items: center; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.065); border-radius: 10px; display: flex; justify-content: space-between; padding: 13px; }
.game-intel-collection-grid article div { display: grid; gap: 3px; }
.game-intel-collection-grid small { color: #71828a; font-size: .68rem; }
.game-intel-collection-grid > article > strong { color: var(--intel-cyan); font-size: 1.25rem; }
.game-intel-accounts { display: grid; gap: 7px; margin-top: 18px; max-height: 490px; overflow: auto; }
.game-intel-accounts button { align-items: center; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.065); border-radius: 11px; color: inherit; display: grid; gap: 12px; grid-template-columns: 38px 1fr auto; padding: 11px; text-align: left; }
.game-intel-accounts button:hover { background: rgba(73,217,232,.065); border-color: rgba(73,217,232,.3); }
.game-intel-avatar { align-items: center; background: linear-gradient(145deg, #173441, #0b202a); border: 1px solid rgba(73,217,232,.25); border-radius: 10px; color: var(--intel-cyan); display: flex; font-weight: 900; height: 38px; justify-content: center; }
.game-intel-accounts button div { display: grid; gap: 3px; }
.game-intel-accounts small { color: #788991; overflow-wrap: anywhere; }
.game-intel-accounts i { color: var(--intel-gold); font-size: .62rem; font-style: normal; font-weight: 900; letter-spacing: .12em; }
.game-intel-disclosure { border-left: 2px solid var(--intel-gold); display: grid; gap: 5px; padding: 8px 16px; }
.game-intel-disclosure p { color: #7d8d95; margin: 0; }
.dev-persistence-summary { display: grid; gap: 10px; grid-template-columns: repeat(3, 1fr); margin: 18px 0; }
.dev-persistence-summary article { background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.065); border-radius: 12px; display: grid; gap: 4px; padding: 15px; }
.dev-persistence-summary span { color: #75858d; font-size: .68rem; font-weight: 800; text-transform: uppercase; }
.dev-persistence-summary small { color: #74848c; }
.dev-persistence-groups { display: grid; gap: 8px; }
.dev-persistence-groups details { background: rgba(5,12,17,.36); border: 1px solid rgba(255,255,255,.07); border-radius: 12px; }
.dev-persistence-groups summary { align-items: center; cursor: pointer; display: flex; justify-content: space-between; padding: 14px 16px; }
.dev-persistence-groups summary strong { color: var(--intel-cyan, #49d9e8); }
.dev-persistence-records { display: grid; gap: 8px; grid-template-columns: repeat(2, 1fr); padding: 0 12px 12px; }
.dev-persistence-records article { background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.06); border-radius: 10px; padding: 14px; }
.dev-persistence-records h3 { font-size: 1rem; margin: 10px 0 6px; }
.dev-persistence-records p, .dev-persistence-records small { color: #74858d; overflow-wrap: anywhere; }
.dev-persistence-records article > div:not(.dev-persistence-record-head) { display: flex; flex-wrap: wrap; gap: 5px; margin: 10px 0; }
.dev-persistence-records article > div:not(.dev-persistence-record-head) span { background: rgba(73,217,232,.07); border: 1px solid rgba(73,217,232,.12); border-radius: 99px; color: #9fc9ce; font-size: .64rem; padding: 4px 7px; }
.dev-persistence-record-head { align-items: center; display: flex; gap: 8px; justify-content: space-between; }
.dev-persistence-record-head code { color: #708088; font-size: .65rem; }
@media (max-width: 980px) {
  .game-intel-hero { align-items: stretch; flex-direction: column; gap: 28px; }
  .game-intel-score { border-left: 0; border-top: 1px solid rgba(255,255,255,.1); padding-left: 0; padding-top: 20px; }
  .game-intel-statline, .game-intel-layout { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 680px) {
  .game-intel-statline, .game-intel-layout, .game-intel-collection-grid, .dev-persistence-summary, .dev-persistence-records { grid-template-columns: 1fr; }
}
/* Faircroft News Now — original broadcast newsroom identity */
.fnn-workspace {
  min-height: 100vh;
  color: #111318;
  background: #f7f7f5;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.fnn-network-header {
  min-height: 76px;
  padding: 10px clamp(18px, 4vw, 64px);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  color: #fff;
  background: #101216;
  border-bottom: 4px solid #d91f2a;
}

.fnn-exit,
.fnn-header-actions button {
  width: max-content;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  background: transparent;
  border: 1px solid #3a3d44;
  border-radius: 4px;
  padding: 10px 14px;
  font-weight: 800;
}

.fnn-exit svg { width: 18px; }

.fnn-brand {
  display: flex;
  align-items: center;
  gap: 2px;
  color: #fff;
  text-decoration: none;
}

.fnn-brand b,
.fnn-empty-mark b {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  color: #fff;
  background: #d91f2a;
  font: 950 26px/1 Arial Black, Impact, sans-serif;
  letter-spacing: -2px;
  transform: skew(-5deg);
}

.fnn-brand span {
  margin-left: 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .17em;
  text-transform: uppercase;
}

.fnn-header-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 14px;
}

.fnn-header-actions button { background: #d91f2a; border-color: #d91f2a; }
.fnn-live-dot { font-size: 10px; font-weight: 900; letter-spacing: .12em; }
.fnn-live-dot i { display: inline-block; width: 7px; height: 7px; margin-right: 7px; border-radius: 50%; background: #f43c47; box-shadow: 0 0 0 5px rgba(244,60,71,.14); }

.fnn-sections {
  min-height: 42px;
  padding: 0 clamp(18px, 4vw, 64px);
  display: flex;
  align-items: center;
  gap: clamp(16px, 3vw, 38px);
  overflow-x: auto;
  white-space: nowrap;
  background: #fff;
  border-bottom: 1px solid #d7d8dc;
  color: #41434a;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: .08em;
}

.fnn-sections button {
  position: relative;
  align-self: stretch;
  padding: 0;
  color: #41434a;
  background: transparent;
  border: 0;
  border-radius: 0;
  font: inherit;
  letter-spacing: inherit;
  cursor: pointer;
}
.fnn-sections button::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: #d91f2a;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .22s ease;
}
.fnn-sections button:hover,
.fnn-sections button:focus-visible,
.fnn-sections button.active { color: #d91f2a; }
.fnn-sections button:hover::after,
.fnn-sections button:focus-visible::after,
.fnn-sections button.active::after { transform: scaleX(1); }
.fnn-sections time { margin-left: auto; color: #747780; font-weight: 650; letter-spacing: 0; }

.fnn-breaking {
  display: flex;
  align-items: stretch;
  min-height: 44px;
  background: #252831;
  color: #fff;
}

.fnn-breaking strong {
  display: grid;
  place-items: center;
  padding: 0 clamp(20px, 4vw, 64px);
  background: #d91f2a;
  font-size: 12px;
  letter-spacing: .12em;
}

.fnn-breaking span { padding: 12px 24px; font-weight: 750; }
.fnn-live-ticker{height:46px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;background:#101216;color:#fff;border-bottom:3px solid #d91f2a;overflow:hidden}.fnn-live-ticker>strong{height:100%;display:flex;align-items:center;gap:8px;padding:0 22px;background:#d91f2a;font-size:10px;letter-spacing:.12em;white-space:nowrap}.fnn-live-ticker>strong i{width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 0 5px #ffffff25;animation:fnn-live-pulse 1.8s ease-out infinite}.fnn-live-ticker>div{overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 3%,#000 97%,transparent)}.fnn-live-ticker>div>span{display:flex;width:max-content;animation:fnnTicker 75s linear infinite}.fnn-live-ticker b{font:700 12px/1.2 Arial,sans-serif;letter-spacing:.03em;white-space:nowrap}.fnn-live-ticker b:after{content:"FNN";display:inline-block;margin:0 28px;color:#e5313c;font-size:9px;font-weight:950;letter-spacing:.14em}.fnn-live-ticker>em{font-style:normal;color:#9699a1;font-size:9px;padding:0 17px}@keyframes fnnTicker{to{transform:translateX(-50%)}}

.fnn-page {
  width: min(1420px, calc(100% - 36px));
  margin: 0 auto;
  padding: clamp(28px, 4vw, 60px) 0 70px;
  display: grid;
  grid-template-columns: minmax(0, 2.15fr) minmax(290px, .85fr);
  gap: 34px 46px;
}

.fnn-lead { padding-right: clamp(0px, 2vw, 28px); border-right: 1px solid #d6d6d4; }
.fnn-kicker { margin: 0 0 12px; color: #d91f2a; font-size: 12px; font-weight: 950; letter-spacing: .15em; }
.fnn-lead h1 { max-width: 1050px; margin: 0; color: #101216; font-family: Georgia, "Times New Roman", serif; font-size: clamp(42px, 6.2vw, 88px); line-height: .96; letter-spacing: -.045em; }
.fnn-deck { max-width: 920px; margin: 24px 0 18px; color: #4b4e55; font: 400 clamp(18px, 2vw, 25px)/1.42 Georgia, serif; }
.fnn-byline { display: flex; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #202228; border-bottom: 1px solid #d8d9dc; font-size: 11px; font-weight: 850; letter-spacing: .08em; }
.fnn-byline time { color: #747780; font-weight: 650; letter-spacing: 0; }
.fnn-lead-copy { margin-top: 26px; columns: 2 290px; column-gap: 38px; color: #292c32; font: 400 17px/1.7 Georgia, serif; }
.fnn-lead-copy p:first-child::first-letter { float: left; margin: 6px 8px 0 0; color: #d91f2a; font: 800 58px/.75 Georgia, serif; }
.fnn-lead-copy p { margin: 0 0 1em; }
.fnn-source-note { margin-top: 26px; padding: 14px 16px; background: #ececea; color: #60636a; font-size: 12px; border-left: 4px solid #d91f2a; }

.fnn-brief { align-self: start; background: #fff; border-top: 6px solid #191b20; box-shadow: 0 10px 30px rgba(16,18,22,.08); }
.fnn-brief-title { padding: 20px; border-bottom: 1px solid #ddd; }
.fnn-brief-title span { display: block; color: #d91f2a; font-size: 10px; font-weight: 950; letter-spacing: .14em; }
.fnn-brief-title strong { display: block; margin-top: 4px; font: 800 30px/1 Georgia, serif; }
.fnn-brief article { padding: 18px 20px; border-bottom: 1px solid #e2e2df; }
.fnn-brief article span { color: #767982; font-size: 10px; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; }
.fnn-brief article p { margin: 7px 0 0; color: #272a30; font: 600 15px/1.45 Georgia, serif; }

.fnn-story-grid {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 5px solid #111318;
}

.fnn-story-grid article { min-height: 220px; padding: 24px; background: #fff; border-right: 1px solid #d9d9d7; border-bottom: 1px solid #d9d9d7; }
.fnn-story-grid article:nth-child(3n) { border-right: 0; }
.fnn-story-grid article > span { color: #d91f2a; font-size: 10px; font-weight: 950; letter-spacing: .13em; }
.fnn-story-grid h2 { margin: 10px 0; font: 800 clamp(23px, 2.2vw, 34px)/1.06 Georgia, serif; letter-spacing: -.02em; }
.fnn-story-grid p { color: #53565d; line-height: 1.55; }
.fnn-longform-grid { grid-template-columns: 1fr; }
.fnn-longform-grid article,
.fnn-longform-grid article:nth-child(3n) { min-height: 0; padding: clamp(26px, 4vw, 52px) clamp(22px, 5vw, 70px); border-right: 0; }
.fnn-longform-grid article:nth-child(even) { background: #f3f3f0; }
.fnn-longform-grid h2 { max-width: 950px; font-size: clamp(30px, 4vw, 52px); }
.fnn-story-deck { max-width: 920px; margin: 0 0 24px; color: #55585f !important; font: 500 clamp(17px, 2vw, 21px)/1.5 Georgia, serif; }
.fnn-story-body { max-width: 980px; columns: 2 340px; column-gap: 46px; color: #292c32; font: 400 16px/1.72 Georgia, serif; }
.fnn-story-body p { margin: 0 0 1em; color: inherit; }
.fnn-story-body p:first-child::first-letter { float: left; margin: 6px 8px 0 0; color: #d91f2a; font: 800 52px/.78 Georgia, serif; }

.fnn-archive { grid-column: 1 / -1; padding-top: 28px; border-top: 1px solid #bfc0c3; }
.fnn-archive > div span { color: #d91f2a; font-size: 10px; font-weight: 950; letter-spacing: .13em; }
.fnn-archive > div h2 { margin: 4px 0 20px; font: 800 32px Georgia, serif; }
.fnn-archive article { display: grid; grid-template-columns: 120px minmax(220px, .8fr) 1.4fr; gap: 24px; padding: 15px 0; border-top: 1px solid #ddd; }
.fnn-archive article p { margin: 0; color: #666970; }

.fnn-empty-newsroom { min-height: calc(100vh - 210px); display: grid; place-items: center; align-content: center; text-align: center; padding: 40px 20px; }
.fnn-empty-mark { display: flex; gap: 3px; margin-bottom: 26px; }
.fnn-empty-newsroom h1 { max-width: 800px; margin: 0; font: 800 clamp(40px, 6vw, 76px)/1 Georgia, serif; }
.fnn-empty-newsroom > p:not(.fnn-kicker) { max-width: 630px; color: #666970; font-size: 18px; line-height: 1.55; }
.fnn-footer { min-height: 90px; padding: 24px clamp(18px, 4vw, 64px); display: flex; align-items: center; gap: 20px; color: #d9dade; background: #101216; }
.fnn-footer strong { color: #fff; font-size: 26px; }
.fnn-footer small { margin-left: auto; color: #8f929a; }

.fnn-network-header { animation: fnn-header-in .45s cubic-bezier(.2,.8,.2,1) both; }
.fnn-brand b,
.fnn-empty-mark b { animation: fnn-tile-in .42s cubic-bezier(.2,.9,.25,1.25) both; }
.fnn-brand b:nth-child(2),
.fnn-empty-mark b:nth-child(2) { animation-delay: .06s; }
.fnn-brand b:nth-child(3),
.fnn-empty-mark b:nth-child(3) { animation-delay: .12s; }
.fnn-live-dot i { animation: fnn-live-pulse 1.8s ease-out infinite; }
.fnn-breaking span { animation: fnn-breaking-in .55s ease-out both; }
.fnn-empty-newsroom > *,
.fnn-lead > *,
.fnn-brief,
.fnn-longform-grid article { animation: fnn-rise .52s cubic-bezier(.2,.75,.25,1) both; }
.fnn-empty-newsroom > :nth-child(2),
.fnn-lead > :nth-child(2) { animation-delay: .06s; }
.fnn-empty-newsroom > :nth-child(3),
.fnn-lead > :nth-child(3) { animation-delay: .12s; }
.fnn-empty-newsroom > :nth-child(4),
.fnn-lead > :nth-child(4),
.fnn-brief { animation-delay: .18s; }
.fnn-longform-grid article:nth-child(2) { animation-delay: .08s; }
.fnn-longform-grid article:nth-child(3) { animation-delay: .16s; }
.fnn-page,
.fnn-brief,
.fnn-story-grid { scroll-margin-top: 58px; }
[data-generate-fnn] { transition: transform .18s ease, box-shadow .18s ease, filter .18s ease; }
[data-generate-fnn]:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 9px 20px rgba(217,31,42,.22); }
[data-generate-fnn].publishing {
  filter: saturate(.72);
  animation: fnn-publishing 1.1s ease-in-out infinite;
  cursor: wait;
}

@keyframes fnn-header-in {
  from { opacity: 0; transform: translateY(-12px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fnn-tile-in {
  from { opacity: 0; transform: translateY(8px) scale(.82) skew(-5deg); }
  to { opacity: 1; transform: translateY(0) scale(1) skew(-5deg); }
}
@keyframes fnn-rise {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fnn-breaking-in {
  from { opacity: 0; transform: translateX(18px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes fnn-live-pulse {
  0%, 45% { box-shadow: 0 0 0 5px rgba(244,60,71,.14); }
  70%, 100% { box-shadow: 0 0 0 10px rgba(244,60,71,0); }
}
@keyframes fnn-publishing {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(.985); opacity: .78; }
}

@media (prefers-reduced-motion: reduce) {
  .fnn-workspace *,
  .fnn-workspace *::before,
  .fnn-workspace *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

@media (max-width: 820px) {
  .fnn-network-header { grid-template-columns: auto 1fr; }
  .fnn-brand { justify-self: center; }
  .fnn-brand span, .fnn-live-dot { display: none; }
  .fnn-header-actions { grid-column: 1 / -1; justify-self: stretch; justify-content: center; }
  .fnn-page { grid-template-columns: 1fr; }
  .fnn-lead { padding-right: 0; border-right: 0; }
  .fnn-story-grid { grid-template-columns: 1fr; }
  .fnn-story-grid article { border-right: 0; }
  .fnn-archive article { grid-template-columns: 1fr; gap: 5px; }
  .fnn-footer { align-items: flex-start; flex-direction: column; }
  .fnn-footer small { margin-left: 0; }
}

/* Compact live economy console */
.game-intel-console { gap: 10px; }
.game-intel-console .game-intel-hero {
  min-height: 0;
  padding: 22px 26px;
}
.game-intel-console .game-intel-hero h2 {
  margin: 7px 0 12px;
  font-size: clamp(1.8rem, 3vw, 2.75rem);
}
.game-intel-console .game-intel-score {
  min-width: 170px;
  padding: 15px 18px;
}
.game-intel-console .game-intel-statline article {
  min-height: 78px;
  padding: 12px 14px;
  border-radius: 10px;
  animation: intel-card-in .42s both;
}
.game-intel-console .game-intel-statline:nth-of-type(3) article { animation-delay: .08s; }

.game-intel-rankings {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.game-intel-rank-card { padding: 16px; overflow: hidden; }
.game-intel-rank-card.linked { border-top: 2px solid #39e7b0; }
.game-intel-rank-card.unlinked { border-top: 2px solid #f0b64c; }
.game-intel-rank-list { display: grid; margin-top: 10px; }
.game-intel-rank-list button,
.game-intel-rank-list article {
  min-width: 0;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  padding: 9px 7px;
  color: inherit;
  background: transparent;
  border: 0;
  border-top: 1px solid rgba(255,255,255,.06);
  text-align: left;
  animation: intel-row-in .35s both;
}
.game-intel-rank-list button { cursor: pointer; }
.game-intel-rank-list button:hover { background: rgba(57,231,176,.055); }
.game-intel-rank-list b {
  color: #657780;
  font-size: .72rem;
  font-variant-numeric: tabular-nums;
}
.game-intel-rank-list div { min-width: 0; display: grid; gap: 2px; }
.game-intel-rank-list strong,
.game-intel-rank-list small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.game-intel-rank-list small { color: #71838b; font-size: .66rem; }
.game-intel-rank-list i {
  color: var(--intel-gold);
  font-size: .78rem;
  font-style: normal;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}
.game-intel-pulse i { animation: intel-pulse 1.8s ease-out infinite; }

@keyframes intel-card-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes intel-row-in {
  from { opacity: 0; transform: translateX(-6px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes intel-pulse {
  0%, 45% { box-shadow: 0 0 0 0 rgba(74,232,186,.35); }
  100% { box-shadow: 0 0 0 8px rgba(74,232,186,0); }
}
@media (prefers-reduced-motion: reduce) {
  .game-intel-console *, .game-intel-pulse i { animation: none !important; }
}
@media (max-width: 900px) {
  .game-intel-rankings { grid-template-columns: 1fr; }
