.commerce-view .business-brief { border-left-color: #2de0a1; background: #111a1b; }
.commerce-view .primary { color: #06100d; background: #2de0a1; border-color: #2de0a1; }

@keyframes commerce-enter {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce) {
  .commerce-command-strip article,
  .commerce-view .business-license-folder { animation: none; }
}
@media (max-width: 900px) {
  .business-workspace { grid-template-columns: 1fr; }
  .business-workspace-sidebar { padding: 12px; }
  .commerce-brand, .business-workspace-sidebar .dev-nav-label, .business-workspace-sidebar-note { display: none; }
  .business-workspace-sidebar nav { display: flex; overflow-x: auto; }
  .business-workspace-sidebar nav button { min-width: 160px; }
  .commerce-command-strip { grid-template-columns: repeat(2, 1fr); }
  .commerce-filing-layout:has(.commerce-active-filings) { grid-template-columns: 1fr; }
  .commerce-form-section { grid-template-columns: 1fr; }
