@keyframes fire-console-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fire-live-pulse {
  from { box-shadow: 0 0 0 0 rgba(59,221,154,.45); }
  to { box-shadow: 0 0 0 8px rgba(59,221,154,0); }
}
@media (prefers-reduced-motion: reduce) {
  .fire-command-metrics article, .fire-incident-row, .fire-command-topbar em i { animation: none; }
}
@media (max-width: 980px) {
  .fire-command-workspace { grid-template-columns: 1fr; }
  .fire-command-sidebar { min-width: 0; min-height: 0; gap: 0; padding: 9px 10px; border-right: 0; border-bottom: 1px solid #242b30; }
  .fire-command-brand, .fire-command-user { display: none; }
  .fire-command-sidebar nav { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); overflow: hidden; }
  .fire-command-sidebar nav button { min-width: 0; min-height: 46px; grid-template-columns: 22px minmax(0, 1fr); padding: 0 9px; }
  .fire-command-sidebar nav button small { display: none; }
  .fire-incident-row { grid-template-columns: 25px 1fr auto; }
  .fire-incident-report { grid-column: 2 / -1; }
  .fire-incident-units { display: none; }
}
@media (max-width: 650px) {
  .fire-command-workspace { min-height: 100dvh; }
  .fire-command-topbar { min-width: 0; min-height: 0; align-items: stretch; flex-direction: column; gap: 10px; padding: 11px 12px; }
  .fire-command-topbar h1 { font-size: 24px; }
  .fire-command-topbar > div:last-child { display: grid; grid-template-columns: 1fr 1fr; width: 100%; }
  .fire-command-topbar em { display: none; }
  .fire-command-topbar button { width: 100%; min-width: 0; padding: 0 9px; }
  .fire-command-metrics { grid-template-columns: repeat(2, 1fr); }
  .fire-command-metrics article { min-width: 0; min-height: 66px; padding: 10px 13px; }
  .fire-command-metrics article:nth-child(2) { border-right: 0; }
  .fire-command-metrics article:nth-child(-n+2) { border-bottom: 1px solid #242c31; }
  .fire-command-metrics strong { font-size: 20px; }
  .fire-command-content { padding: 10px; }
  .fire-incident-board, .fire-personnel-board, .fire-command-content > .fire-command-board { width: 100%; max-width: 100%; }
  .fire-incident-row { min-width: 0; grid-template-columns: 19px minmax(0, 1fr); gap: 8px; padding: 11px 10px; }
  .fire-incident-report { min-width: 0; }
  .fire-incident-report p, .fire-incident-report small, .fire-incident-type strong { overflow-wrap: anywhere; }
  .fire-incident-status, .fire-incident-actions { grid-column: 2; }
  .fire-incident-actions { justify-content: start; }
  .fire-incident-actions button { flex: 1; }
  .fire-cleared-log > div { grid-template-columns: 58px minmax(0, 1fr); }
  .fire-cleared-log time { grid-column: 2; }
  .fire-personnel-grid { grid-template-columns: 1fr; }
  .fire-personnel-grid article { min-width: 0; grid-template-columns: 38px minmax(0, 1fr); }
  .fire-personnel-grid article > span:last-child { grid-column: 2; }
}
@media (max-width: 390px) {
  .fire-command-sidebar nav button { grid-template-columns: 1fr; justify-items: center; padding: 6px 4px; text-align: center; }
  .fire-command-sidebar nav button b { display: none; }
  .fire-command-sidebar nav button span { font-size: 10px; }
}

/* Press Desk */
.press-desk { gap: 14px; }
.press-desk-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 22px;
  border: 1px solid rgba(244,71,71,.24);
  border-radius: 14px;
  background: radial-gradient(circle at 92% 0, rgba(244,71,71,.18), transparent 38%), #11191f;
}
.press-desk-hero h3 { margin: 4px 0 7px; font-size: 28px; }
.press-desk-hero p:last-child { margin: 0; color: var(--muted); }
.press-desk-hero > span { display: grid; justify-items: center; color: #ff7a7a; font-size: 32px; font-weight: 950; }
.press-desk-hero > span small { color: var(--muted); font-size: 9px; letter-spacing: .1em; text-transform: uppercase; }
.press-guidance { padding: 16px 18px; border-left: 4px solid #e6424b; border-radius: 7px; background: rgba(230,66,75,.08); }
.press-guidance strong { color: #ffd5d5; }
.press-guidance p { margin: 5px 0 0; color: #b6c1c6; font-size: 13px; line-height: 1.55; }
.press-report-form, .press-report-library { padding: 20px; border: 1px solid var(--line); border-radius: 13px; background: rgba(14,21,26,.92); }
.press-form-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 17px; }
.press-form-heading h3 { margin: 3px 0 0; }
.press-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.press-form-grid label { display: grid; gap: 6px; color: #93a2a9; font-size: 12px; font-weight: 800; }
.press-form-grid .wide { grid-column: 1 / -1; }
.press-form-grid textarea { min-height: 105px; }
.press-report-form > button { width: 100%; margin-top: 15px; }
.press-report-library > div:last-child { display: grid; gap: 7px; margin-top: 14px; }
.press-report-library article { display: grid; gap: 4px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255,255,255,.025); }
.press-report-library article span, .press-report-library article small { color: var(--muted); font-size: 10px; }
@media (max-width: 650px) {
  .press-desk-hero { align-items: flex-start; padding: 17px; }
  .press-desk-hero h3 { font-size: 23px; }
  .press-report-form, .press-report-library { padding: 14px; }
  .press-form-grid { grid-template-columns: 1fr; }
  .press-form-grid .wide { grid-column: auto; }
}

/* FNN Press Operations */
.press-workspace {
