/* Presentation-grade Faircroft driver credential */
.dmv-license-presentation {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 12px;
  padding: clamp(20px, 3vw, 42px);
  background:
    radial-gradient(circle at 50% 0, rgba(209, 184, 92, .06), transparent 36%),
    #0b1215;
}
.dmv-issued-license {
  --license-accent: #d7bd5b;
  position: relative;
  width: min(100%, 820px);
  aspect-ratio: 1.586 / 1;
  min-height: 410px;
  margin: 0 auto;
  overflow: hidden;
  border: 1px solid rgba(232, 220, 161, .48);
  border-radius: 24px;
  color: #152626;
  background:
    linear-gradient(105deg, transparent 0 62%, rgba(38, 123, 126, .1) 62% 63%, transparent 63%),
    radial-gradient(circle at 76% 38%, rgba(213, 183, 77, .22), transparent 24%),
    linear-gradient(135deg, #dfece4, #c8ddd5 52%, #e8e4c9);
  box-shadow:
    0 35px 80px rgba(0, 0, 0, .5),
    inset 0 0 0 4px rgba(255, 255, 255, .23);
  isolation: isolate;
}
.dmv-issued-license.restricted { --license-accent: #b94851; filter: saturate(.78); }
.dmv-license-security {
  position: absolute;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  opacity: .42;
  background:
    repeating-radial-gradient(ellipse at 18% 55%, transparent 0 9px, rgba(26, 101, 102, .2) 10px 11px, transparent 12px 17px),
    repeating-linear-gradient(118deg, transparent 0 22px, rgba(255, 255, 255, .3) 23px, transparent 24px 48px);
}
.dmv-license-security::before {
  content: "FAIRCROFT • MOTOR VEHICLE AUTHORITY • FAIRCROFT • MOTOR VEHICLE AUTHORITY";
  position: absolute;
  top: 46%;
  left: -5%;
  width: 110%;
  color: rgba(23, 94, 92, .15);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: .18em;
  white-space: nowrap;
  transform: rotate(-8deg);
}
.dmv-license-security i { position: absolute; border: 1px solid rgba(28, 97, 96, .2); border-radius: 50%; }
.dmv-license-security i:nth-child(1) { width: 330px; height: 330px; right: -80px; top: -130px; }
.dmv-license-security i:nth-child(2) { width: 220px; height: 220px; right: -26px; top: -75px; }
.dmv-license-security i:nth-child(3) { width: 110px; height: 110px; right: 28px; top: -20px; }
.dmv-license-masthead {
  min-height: 82px;
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 15px 22px 11px;
  border-bottom: 2px solid rgba(27, 84, 83, .24);
  background: linear-gradient(90deg, rgba(255,255,255,.24), rgba(255,255,255,.04));
}
.dmv-license-state-seal {
  width: 49px;
  height: 49px;
  display: grid;
  place-items: center;
  border: 2px solid #246968;
  border-radius: 50%;
  box-shadow: inset 0 0 0 4px rgba(232, 242, 230, .72);
}
.dmv-license-state-seal span { color: #195b5a; font-size: 13px; font-weight: 1000; }
.dmv-license-masthead > div:nth-child(2) { display: grid; }
.dmv-license-masthead small { color: #5f796f; font-size: 8px; font-weight: 950; letter-spacing: .21em; }
.dmv-license-masthead strong { color: #173f40; font-family: Georgia, "Times New Roman", serif; font-size: clamp(23px, 3vw, 35px); letter-spacing: .035em; line-height: 1; }
.dmv-license-masthead em { margin-top: 3px; color: #6d8178; font-size: 7px; font-style: normal; font-weight: 900; letter-spacing: .16em; }
.dmv-license-masthead > b {
  align-self: start;
  min-width: 84px;
  padding: 8px 11px;
  border: 1px solid rgba(26, 90, 88, .28);
  border-radius: 9px;
  color: #173f40;
  background: rgba(255,255,255,.2);
  font-size: 18px;
  text-align: center;
}
.dmv-license-number {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 6px 22px;
  color: #2f5b58;
  background: rgba(25, 89, 87, .07);
}
.dmv-license-number span { font-size: 7px; font-weight: 950; letter-spacing: .13em; }
.dmv-license-number strong { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; letter-spacing: .06em; }
.dmv-license-number em {
  margin-left: auto;
  padding: 4px 9px;
  border-radius: 99px;
  color: #fff;
  background: #23775f;
  font-size: 7px;
  font-style: normal;
  font-weight: 950;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.dmv-license-number em.suspended,
.dmv-license-number em.revoked,
.dmv-license-number em.expired,
.dmv-license-number em.exam.required { background: #a83f49; }
.dmv-license-face {
  position: relative;
  display: grid;
  grid-template-columns: minmax(138px, 27%) minmax(0, 1fr) 86px;
  gap: 18px;
  padding: 17px 22px 13px;
}
.dmv-license-portrait {
  position: relative;
  height: 216px;
  overflow: hidden;
  border: 2px solid rgba(24, 81, 79, .4);
  border-radius: 8px;
  background: #d3ded7;
  box-shadow: 0 5px 14px rgba(16, 57, 55, .16);
}
.dmv-license-portrait > img { width: 100%; height: 100%; object-fit: cover; object-position: center top; filter: saturate(.88) contrast(1.03); }
.dmv-photo-placeholder { width: 100%; height: 100%; display: grid; place-content: center; justify-items: center; gap: 9px; color: #315b58; background: linear-gradient(145deg, #cfddd5, #afc7bd); }
.dmv-photo-placeholder span { font-family: Georgia, serif; font-size: 74px; line-height: 1; }
.dmv-photo-placeholder small { padding: 0 8px; color: #7d4145; font-size: 7px; font-weight: 950; letter-spacing: .1em; text-align: center; }
.dmv-portrait-stamp {
  position: absolute;
  right: 5px;
  bottom: 5px;
  padding: 3px 5px;
  color: rgba(255,255,255,.92);
  background: rgba(14, 74, 72, .72);
  font-size: 6px;
  font-weight: 950;
  letter-spacing: .12em;
}
.dmv-license-data {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 10px 18px;
}
.dmv-license-field { min-width: 0; display: grid; gap: 2px; }
.dmv-license-field.wide { grid-column: 1 / -1; padding-bottom: 6px; border-bottom: 1px solid rgba(29, 85, 82, .2); }
.dmv-license-field small { color: #52736b; font-size: 6px; font-weight: 950; letter-spacing: .12em; }
.dmv-license-field strong { overflow: hidden; color: #172f30; font-size: 11px; font-weight: 850; text-overflow: ellipsis; white-space: nowrap; }
.dmv-license-field.wide strong { color: #123b3c; font-family: Georgia, "Times New Roman", serif; font-size: clamp(22px, 3vw, 34px); letter-spacing: -.025em; }
.dmv-license-signature { grid-column: 1 / -1; align-self: end; display: grid; gap: 0; margin-top: 3px; border-bottom: 1px solid rgba(23, 72, 71, .45); }
.dmv-license-signature span { color: #184f50; font-family: "Segoe Script", "Bradley Hand", cursive; font-size: clamp(18px, 2.4vw, 29px); font-style: italic; line-height: 1.05; transform: rotate(-2deg); transform-origin: left bottom; }
.dmv-license-signature small { padding: 3px 0; color: #5e7871; font-size: 5px; font-weight: 950; letter-spacing: .11em; }
.dmv-license-ghost { align-self: end; display: grid; justify-items: center; gap: 4px; opacity: .42; }
.dmv-license-ghost img { width: 68px; height: 86px; object-fit: cover; object-position: center top; filter: grayscale(1) contrast(.8) sepia(.4) hue-rotate(110deg); mix-blend-mode: multiply; }
.dmv-license-ghost > span { width: 68px; height: 68px; display: grid; place-items: center; border: 2px solid #397976; border-radius: 50%; font-size: 20px; font-weight: 950; }
.dmv-license-ghost small { color: #356764; font-size: 5px; font-weight: 950; letter-spacing: .13em; }
.dmv-license-authentication {
  min-height: 48px;
  display: grid;
  grid-template-columns: minmax(120px, 1.1fr) minmax(180px, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 7px 22px 12px;
  color: #476b64;
}
.dmv-license-barcode {
  height: 30px;
  background: repeating-linear-gradient(90deg, #1d4442 0 2px, transparent 2px 4px, #1d4442 4px 5px, transparent 5px 8px, #1d4442 8px 11px, transparent 11px 13px);
  opacity: .78;
}
.dmv-license-authentication span { font-size: 5px; font-weight: 900; letter-spacing: .08em; line-height: 1.45; text-align: center; }
