.bank-information-row { display: grid; grid-template-columns: 1.2fr .8fr; gap: 18px; margin-top: 18px; }
.bank-account-health,
.bank-fcic-notice { border-radius: 16px; padding: 26px; }
.bank-account-health > header { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-bottom: 20px; border-bottom: 1px solid #203139; }
.bank-account-health h2,
.bank-fcic-notice h2 { margin: 4px 0 0; font-size: 1.15rem; }
.bank-account-health > header > span { color: #79d8bd; font-size: .65rem; font-weight: 750; }
.bank-account-health > div { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.bank-account-health > div > span { position: relative; display: grid; gap: 5px; padding: 23px 20px 2px 30px; }
.bank-account-health > div > span + span { border-left: 1px solid #1e3037; }
.bank-account-health i { position: absolute; top: 27px; left: 8px; width: 9px; height: 9px; border-radius: 50%; background: #c99a49; }
