.bank-fcic-notice small { color: #5f747b; font-size: .6rem; line-height: 1.45; }
@media (max-width: 980px) {
  .bank-dashboard-grid,
  .bank-information-row { grid-template-columns: 1fr; }
  .bank-credit-panel { min-height: 0; }
}
@media (max-width: 650px) {
  .bank-workspace-topbar { position: relative; align-items: flex-start; padding: 14px 16px; }
  .bank-workspace-brand small,
  .bank-secure-session { display: none; }
  .bank-workspace-actions { gap: 6px; }
  .bank-workspace-actions button { min-height: 38px; padding: 8px 10px; font-size: .68rem; }
  .bank-dashboard { width: calc(100% - 24px); padding: 24px 0 max(40px, env(safe-area-inset-bottom)); }
  .bank-welcome { align-items: stretch; flex-direction: column; margin-bottom: 20px; }
  .bank-welcome h1 { font-size: 2.15rem; }
  .bank-sync-state { min-width: 0; }
  .bank-balance-panel,
  .bank-credit-panel { min-height: 0; padding: 22px 18px; border-radius: 15px; }
  .bank-balance-amount { margin: 42px 0; }
  .bank-balance-amount strong { font-size: clamp(2.15rem, 11vw, 3.2rem); overflow-wrap: anywhere; }
