.character-assignment-modal { width:min(560px,calc(100vw - 28px)); padding:0; overflow:hidden; }
.character-assignment-modal > header { padding:28px 30px 22px; border-bottom:1px solid var(--border); background:linear-gradient(135deg,rgba(31,211,163,.12),rgba(44,154,255,.08)); }
.character-assignment-modal > header h2 { margin:4px 0 8px; font-size:clamp(1.55rem,4vw,2.25rem); }
.character-assignment-progress,.character-assignment-record,.character-assignment-modal form { margin:20px 30px; }
.character-assignment-progress { display:flex; align-items:center; gap:16px; color:var(--muted); font-size:.82rem; }
.character-assignment-progress i { flex:1; height:3px; overflow:hidden; background:var(--border); }
.character-assignment-progress b { display:block; height:100%; background:var(--mint); }
.character-assignment-record { display:grid; gap:6px; padding:18px; border:1px solid var(--border); border-left:3px solid var(--mint); background:rgba(255,255,255,.025); }
.character-assignment-record small { color:var(--mint); font-weight:800; letter-spacing:.08em; text-transform:uppercase; }
.character-assignment-record strong { font-size:1.08rem; }
.character-assignment-record span { color:var(--muted); font-size:.8rem; }
.character-assignment-modal form { display:grid; gap:18px; }
.character-assignment-modal form > div { display:flex; align-items:center; justify-content:space-between; gap:18px; }
.character-assignment-modal form > div small { max-width:300px; color:var(--muted); }
.court-wipe-control { display:grid; gap:28px; border-top:2px solid var(--amber); }
.court-wipe-control.critical { border-top-color:var(--danger); }
.court-wipe-control > div > span { color:var(--muted); font-size:.72rem; font-weight:900; letter-spacing:.12em; }
.court-wipe-control > div > strong { display:block; margin:18px 0 4px; font-size:3rem; font-family:var(--display); }
.court-wipe-control form { display:grid; grid-template-columns:1fr auto; align-items:end; gap:14px; }
.dmv-vehicle-source-reset { display:grid; grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr); gap:30px; border-top:2px solid #4bc8ff; }
.dmv-vehicle-source-reset > div > span { color:#65d5ff; font-size:.72rem; font-weight:900; letter-spacing:.12em; }
.dmv-vehicle-source-reset dl { display:grid; grid-template-columns:repeat(3,1fr); margin:20px 0; border-block:1px solid var(--border); }
.dmv-vehicle-source-reset dl div { padding:15px 12px; border-right:1px solid var(--border); }
.dmv-vehicle-source-reset dl div:last-child { border-right:0; }
.dmv-vehicle-source-reset dt { color:var(--muted); font-size:.68rem; text-transform:uppercase; letter-spacing:.08em; }
.dmv-vehicle-source-reset dd { margin:7px 0 0; font-weight:800; }
.dmv-vehicle-source-reset form { align-self:center; display:grid; gap:14px; padding-left:28px; border-left:1px solid var(--border); }
.dmv-vehicle-source-reset output { color:var(--muted); font-size:.75rem; }
.resident-court-ledger { display:grid; gap:1px; margin-top:14px; border:1px solid var(--border); background:var(--border); }
.resident-court-ledger article { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:20px; padding:20px; background:#0d1619; }
.resident-court-ledger article > div > span { color:var(--mint); font-size:.67rem; font-weight:900; letter-spacing:.12em; }
.resident-court-ledger h3 { margin:6px 0; }.resident-court-ledger p,.resident-court-ledger footer span { color:var(--muted); }
.resident-court-ledger dl { display:grid; grid-template-columns:repeat(3,minmax(90px,1fr)); margin:0; }
.resident-court-ledger dl div { padding:8px 14px; border-left:1px solid var(--border); }
.resident-court-ledger dt { color:var(--muted); font-size:.65rem; text-transform:uppercase; }.resident-court-ledger dd { margin:5px 0 0; font-weight:800; }
.resident-court-ledger footer { grid-column:1 / -1; display:flex; align-items:center; justify-content:space-between; gap:18px; padding-top:14px; border-top:1px solid var(--border); }
.myfc-code-authority { border-top:2px solid #49d1aa; }.myfc-code-authority .dev-generated-code strong { letter-spacing:.28em; font-size:2.2rem; }
.myfc-payment-code-ledger { max-height:410px; overflow:auto; }.myfc-payment-code-ledger > div > span { display:grid; gap:3px; }.myfc-payment-code-ledger small { color:var(--muted); }
@media (max-width:620px) {
  .character-assignment-modal > header { padding:22px 20px 18px; }
  .character-assignment-progress,.character-assignment-record,.character-assignment-modal form { margin:16px 20px; }
  .character-assignment-modal form > div,.court-wipe-control form { grid-template-columns:1fr; display:grid; }
  .character-assignment-modal form button,.court-wipe-control button { width:100%; }
  .dmv-vehicle-source-reset { grid-template-columns:1fr; }
  .dmv-vehicle-source-reset dl { grid-template-columns:1fr; }
  .dmv-vehicle-source-reset dl div { border-right:0; border-bottom:1px solid var(--border); }
  .dmv-vehicle-source-reset form { padding:20px 0 0; border-left:0; border-top:1px solid var(--border); }
  .resident-court-ledger article { grid-template-columns:1fr; padding:15px; }
  .resident-court-ledger dl { grid-template-columns:1fr; }
  .resident-court-ledger dl div { border-left:0; border-top:1px solid var(--border); }
  .resident-court-ledger footer { align-items:stretch; flex-direction:column; }
  .resident-court-ledger footer button { width:100%; }
}
