/* Ravenhood 0.2.2 layout stabilization: the exchange owns the viewport. */
#app:has(.market-terminal-workspace){
  width:100%;
  min-height:100dvh;
  display:block;
  place-items:initial;
  padding:0;
  overflow:hidden;
}
.market-v4{
  width:100%;
  height:100dvh;
  min-height:0;
  overflow:auto;
  overscroll-behavior:contain;
  scrollbar-gutter:stable;
}
.market-v4 .market-topbar{
  width:100%;
  animation:none;
  opacity:1;
  transform:none;
}
.market-v4 .market-tape{
  width:100%;
}
.market-v4 .market-command{
  width:min(1680px,100%);
  min-height:0;
  grid-template-columns:220px minmax(0,1fr) 300px;
  align-items:start;
  margin:0 auto;
  background:transparent;
}
.market-v4 .market-rail,
.market-v4 .market-terminal,
.market-v4 .market-trade-dock{
  min-width:0;
  animation:none;
  opacity:1;
  transform:none;
}
.market-v4 .market-rail,
.market-v4 .market-trade-dock{
  position:sticky;
  top:118px;
  max-height:calc(100dvh - 118px);
  overflow:auto;
  scrollbar-width:thin;
  scrollbar-color:#245b46 transparent;
}
.market-v4 .market-terminal{
  padding:30px clamp(24px,3vw,48px) 72px;
}
.market-v4 .market-instrument-head h1{
  margin:12px 0 7px;
  font-size:clamp(3rem,5vw,4.5rem);
}
.market-v4 .market-quote-strip{
  margin:24px 0 10px;
}
.market-v4 .market-live-chart{
  height:clamp(230px,30vh,310px);
}
.market-v4 .market-directory>div:last-child>button{
  opacity:1;
  animation:none;
  transform:none;
}
.market-v4 .market-persistent-exit{
  display:none;
}
@media(max-width:1180px){
  .market-v4 .market-command{grid-template-columns:200px minmax(0,1fr)}
  .market-v4 .market-trade-dock{
    position:relative;
    top:auto;
    max-height:none;
    overflow:visible;
    grid-column:1/-1;
    display:grid;
    grid-template-columns:minmax(260px,1fr) minmax(240px,1fr) minmax(220px,.8fr);
  }
  .market-v4 .market-persistent-exit{display:flex}
}
@media(max-width:760px){
  #app:has(.market-terminal-workspace){overflow:hidden}
  .market-v4 .market-command{display:block;width:100%}
  .market-v4 .market-rail,
  .market-v4 .market-trade-dock{position:relative;top:auto;max-height:none;overflow:visible}
  .market-v4 .market-terminal{padding:22px 14px 70px}
  .market-v4 .market-instrument-head{align-items:flex-start}
  .market-v4 .market-instrument-head h1{font-size:2.65rem}
  .market-v4 .market-live-chart{height:220px}
  .market-v4 .market-trade-dock{display:block}
  .market-v4 .market-persistent-exit{display:flex}
}

