/* Full-browser RP OS shell */
#app:has(.rp-workspace-shell) {
  width: 100%;
  min-height: 100dvh;
  display: block;
  padding: 0;
  overflow: hidden;
}
.rp-workspace-shell.phone-shell {
  width: 100%;
  height: 100dvh;
  min-height: 100dvh;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background:
    radial-gradient(circle at 12% 2%, rgba(31,167,159,.12), transparent 34%),
    radial-gradient(circle at 92% 100%, rgba(145,65,171,.11), transparent 35%),
    linear-gradient(145deg,#10171b,#090d10 48%,#121018);
  box-shadow: none;
  animation: rp-shell-open 520ms cubic-bezier(.16,1,.3,1) both;
}
.rp-workspace-shell.phone-shell::before { display: none; }
.rp-workspace-shell.phone-shell::after {
  border-radius: 0;
  box-shadow: inset 0 1px rgba(0,223,249,.13), inset 0 -1px rgba(255,20,157,.1);
}
.rp-workspace-shell .phone-screen {
  width: 100%;
  height: 100dvh;
  padding: 0 clamp(18px,4vw,70px) max(26px,env(safe-area-inset-bottom));
}
.rp-workspace-shell .phone-screen::before {
  inset: 0;
  opacity: .22;
  background: repeating-linear-gradient(135deg,rgba(255,255,255,.025) 0 1px,transparent 1px 28px);
}
.rp-workspace-shell .status-bar { display: none; }
.rp-workspace-shell .phone-screen > .home-stack {
  width: min(1480px,100%);
  margin: 0 auto;
  padding: clamp(28px,5vh,62px) 0 max(72px,calc(env(safe-area-inset-bottom) + 54px));
}
.rp-workspace-shell .home-header {
  min-height: 88px;
  margin-bottom: 8px;
  padding: 14px 4px 22px;
  border-bottom: 1px solid rgba(255,255,255,.11);
}
.rp-workspace-shell .home-header h1 { font-size: clamp(1.75rem,3vw,2.65rem); letter-spacing: -.035em; }
.rp-workspace-shell .home-emblem { width: 56px; height: 56px; flex-basis: 56px; border-radius: 13px; }
.rp-workspace-shell .user-chip { padding: 10px 15px; border-radius: 7px; background: rgba(12,20,24,.7); backdrop-filter: blur(12px); }
.rp-workspace-shell .home-alert { border-radius: 8px; margin: 8px 0 20px; }
.rp-workspace-shell .app-grid {
  grid-template-columns: repeat(8,minmax(96px,1fr));
  gap: clamp(24px,4vh,44px) clamp(14px,2vw,30px);
  align-content: start;
  padding: clamp(22px,4vh,46px) clamp(4px,1vw,14px) 32px;
}
.rp-workspace-shell .app-icon { gap: 11px; }
.rp-workspace-shell .icon-tile { width: 76px; height: 76px; border-radius: 24px 24px 24px 9px; transition: transform .28s cubic-bezier(.16,1,.3,1),box-shadow .28s ease,border-color .28s ease; }
.rp-workspace-shell .app-icon:not(:disabled):hover .icon-tile { transform: translateY(-5px) scale(1.045); border-color:color-mix(in srgb,var(--app-accent) 70%,white 12%); box-shadow:0 24px 45px rgba(0,0,0,.48),0 0 34px color-mix(in srgb,var(--app-accent) 26%,transparent),inset 0 1px 0 rgba(255,255,255,.34); }
.rp-workspace-shell .icon-tile svg { width: 38px; height: 38px; }
.rp-workspace-shell .app-icon > span:not(.icon-tile) { min-height: 30px; max-width: 110px; font-size: .72rem; line-height: 1.22; }
.rp-workspace-shell .os-version { position: fixed; bottom: 0; min-height: 27px; display:grid; place-items:center; background:linear-gradient(transparent,rgba(8,12,14,.94)); }

.rp-workspace-shell .app-panel {
  position: fixed;
  inset: 0;
  padding: 0 clamp(18px,4vw,70px) max(34px,calc(env(safe-area-inset-bottom) + 24px));
  background: radial-gradient(circle at 80% 0,rgba(39,151,164,.08),transparent 35%),linear-gradient(150deg,#0d1519,#080c0f 60%,#110e16);
}
.rp-workspace-shell .app-panel .panel-top,
.rp-workspace-shell .app-panel .panel-body { width: min(1480px,100%); margin-inline:auto; }
.rp-workspace-shell .app-panel .panel-top {
  min-height: 88px;
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 16px 0;
  border-bottom: 1px solid rgba(255,255,255,.11);
  background: rgba(9,15,18,.86);
  backdrop-filter: blur(18px);
}
.rp-workspace-shell .app-panel .panel-top h2 { font-size: clamp(1.45rem,2.5vw,2.15rem); }
.rp-workspace-shell .app-panel .panel-body { padding: clamp(22px,4vw,48px) 0 max(70px,calc(env(safe-area-inset-bottom) + 50px)); scrollbar-width: thin; }
.rp-workspace-shell .auth-card { width: min(520px,calc(100% - 32px)); margin:auto; }
@keyframes rp-shell-open { from { opacity:0; transform:scale(.992) } to { opacity:1; transform:none } }
@media (max-width: 1180px) { .rp-workspace-shell .app-grid { grid-template-columns:repeat(6,minmax(88px,1fr)); } }
@media (max-width: 820px) { .rp-workspace-shell .app-grid { grid-template-columns:repeat(4,minmax(72px,1fr)); } }
@media (max-width: 560px) {
  .rp-workspace-shell .phone-screen { padding-inline:14px; }
  .rp-workspace-shell .phone-screen > .home-stack { padding-top:max(18px,env(safe-area-inset-top)); }
  .rp-workspace-shell .home-header { min-height:72px; }
  .rp-workspace-shell .home-header h1 { font-size:1.65rem; }
  .rp-workspace-shell .home-emblem { width:46px; height:46px; flex-basis:46px; }
  .rp-workspace-shell .app-grid { gap:25px 8px; padding-top:22px; }
  .rp-workspace-shell .icon-tile { width:62px; height:62px; border-radius:19px 19px 19px 7px; }
  .rp-workspace-shell .icon-tile svg { width:31px; height:31px; }
  .rp-workspace-shell .app-panel { padding-inline:14px; }
  .rp-workspace-shell .app-panel .panel-top { min-height:68px; }
}

