/* Anti-Cheat intelligence console — Roadmap motion language */
.anticheat-console {
  --ac-live: #58e2bd;
  --ac-cyan: #55b9d0;
  --ac-danger: #ff6575;
  position: relative;
  gap: 18px;
  isolation: isolate;
  animation: ac-console-open 560ms cubic-bezier(.16,1,.3,1) both;
}
.anticheat-console::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -22px -24px auto;
  height: 330px;
  pointer-events: none;
  background: radial-gradient(circle at 16% 0, rgba(57,196,175,.12), transparent 48%);
  opacity: 0;
  animation: ac-ambient-in 1.1s 120ms ease-out forwards;
}
.anticheat-console .anticheat-command {
  position: relative;
  min-height: 142px;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: center;
  overflow: hidden;
  padding: 25px 28px;
  border: 1px solid rgba(95,226,195,.25);
  border-left: 3px solid var(--ac-live);
  border-radius: 7px;
  background: linear-gradient(105deg, rgba(30,104,94,.22), transparent 55%), #0a1419;
  box-shadow: 0 24px 65px rgba(0,0,0,.2);
  animation: ac-masthead-in 680ms 80ms cubic-bezier(.16,1,.3,1) both;
}
.anticheat-console .anticheat-command::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(90deg, transparent 0 84px, rgba(98,229,206,.027) 84px 85px);
  mask-image: linear-gradient(90deg,#000,transparent 88%);
}
.anticheat-console .anticheat-command::after {
  content: "LIVE INTELLIGENCE LINK";
  position: absolute;
  right: 28px;
  bottom: 15px;
  color: rgba(101,228,199,.44);
  font: 900 .52rem/1 ui-monospace,Consolas,monospace;
  letter-spacing: .2em;
}
.anticheat-console .anticheat-command-mark {
  position: relative;
  width: 62px;
  height: 62px;
  border-radius: 7px;
  background: #0b1c1c;
  box-shadow: inset 0 0 0 1px rgba(105,238,207,.28), 0 0 32px rgba(76,221,188,.08);
}
.anticheat-console .anticheat-command-mark::after {
  content: "";
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(88,226,189,.16);
  border-radius: 10px;
  animation: ac-signal 2.2s ease-in-out infinite;
}
.anticheat-console .anticheat-command h2 { margin: 4px 0 6px; font-size: clamp(1.5rem,2.5vw,2.15rem); letter-spacing: -.035em; }
.anticheat-console .anticheat-command p:last-child { color: #82979f; }
.anticheat-console .anticheat-sync { position: relative; z-index: 1; max-width: 440px; justify-content: flex-end; }
.anticheat-console .anticheat-sync .pill { border-radius: 4px; background: rgba(8,19,22,.8); backdrop-filter: blur(7px); }

.anticheat-console .anticheat-metric-grid {
  border-color: #24383d;
  border-radius: 7px;
  background: #091217;
  box-shadow: 0 15px 40px rgba(0,0,0,.16);
  animation: ac-rail-in 720ms 210ms cubic-bezier(.16,1,.3,1) both;
}
.anticheat-console .anticheat-metric-grid .dev-metric {
  min-height: 132px;
  padding: 20px 17px 16px;
  background: transparent;
  overflow: hidden;
}
.anticheat-console .anticheat-metric-grid .dev-metric::before {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background: var(--ac-live);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 360ms cubic-bezier(.16,1,.3,1);
}
.anticheat-console .anticheat-metric-grid .dev-metric:hover::before,
.anticheat-console .anticheat-metric-grid .dev-metric:focus-visible::before { transform: scaleX(1); }
.anticheat-console .anticheat-metric-grid .dev-metric strong { margin: 8px 0 3px; font-size: 1.9rem; letter-spacing: -.04em; }
.anticheat-console .anticheat-metric-grid .dev-metric span { color: #9cb0b6; }
.anticheat-console .anticheat-metric-grid .dev-metric small { color: #667d85; }
.anticheat-console .anticheat-metric-grid .dev-metric i { transform: translateX(-5px); opacity: .62; transition: transform .25s ease,opacity .25s ease; }
.anticheat-console .anticheat-metric-grid .dev-metric:hover i { transform: translateX(0); opacity: 1; }

.anticheat-console .anticheat-directory {
  position: relative;
  border-color: #263b40;
  border-radius: 7px;
  background: #0a1318;
  box-shadow: 0 26px 70px rgba(0,0,0,.22);
  animation: ac-ledger-in 760ms 330ms cubic-bezier(.16,1,.3,1) both;
}
.anticheat-console .anticheat-directory::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,var(--ac-live),var(--ac-cyan),transparent 74%);
}
.anticheat-console .anticheat-directory-head {
  min-height: 108px;
  padding: 21px 24px;
  background: linear-gradient(90deg,rgba(30,86,81,.12),transparent 58%);
}
.anticheat-console .anticheat-directory-head h2 { margin: 5px 0 3px; font-size: 1.55rem; letter-spacing: -.035em; }
.anticheat-console .dev-command-search input { height: 43px; border-radius: 5px; background: #071015; transition: border-color .2s ease,box-shadow .2s ease; }
.anticheat-console .dev-command-search input:focus { border-color: rgba(88,226,189,.55); box-shadow: 0 0 0 3px rgba(88,226,189,.08); }
.anticheat-console .anticheat-player-head { min-height: 40px; align-items: center; padding-inline: 24px; background: #071015; }
.anticheat-console .anticheat-player-list { padding: 0 14px; background: #0a1318; }
.anticheat-console .anticheat-player-row {
  position: relative;
  min-height: 72px;
  margin: 0;
  padding-inline: 12px;
  border: 0;
  border-bottom: 1px solid #1d3035;
  border-radius: 0;
  background: transparent;
  opacity: 0;
  animation: ac-record-in 480ms cubic-bezier(.16,1,.3,1) forwards;
  transition: background .2s ease,padding-left .25s cubic-bezier(.16,1,.3,1);
}
.anticheat-console .anticheat-player-row::after { content: ""; position: absolute; inset: 9px auto 9px 0; width: 2px; background: var(--ac-live); transform: scaleY(0); transition: transform .25s ease; }
.anticheat-console .anticheat-player-row:hover { padding-left: 18px; border-color: #1d3035; background: linear-gradient(90deg,rgba(65,198,173,.09),transparent 72%); box-shadow: none; }
.anticheat-console .anticheat-player-row:hover::after { transform: scaleY(1); }
.anticheat-console .anticheat-player-row:nth-child(1){animation-delay:390ms}.anticheat-console .anticheat-player-row:nth-child(2){animation-delay:435ms}.anticheat-console .anticheat-player-row:nth-child(3){animation-delay:480ms}.anticheat-console .anticheat-player-row:nth-child(4){animation-delay:525ms}.anticheat-console .anticheat-player-row:nth-child(5){animation-delay:570ms}.anticheat-console .anticheat-player-row:nth-child(6){animation-delay:615ms}.anticheat-console .anticheat-player-row:nth-child(7){animation-delay:660ms}.anticheat-console .anticheat-player-row:nth-child(8){animation-delay:705ms}
.anticheat-console .anticheat-presence.online { box-shadow: 0 0 0 5px rgba(72,223,167,.07),0 0 13px rgba(72,223,167,.55); animation: ac-live 1.7s ease-in-out infinite; }
.anticheat-console .anticheat-player-id strong { font-size: .84rem; letter-spacing: -.01em; }
.anticheat-console .anticheat-player-id small { color: #64828b; font-family: ui-monospace,Consolas,monospace; }
.anticheat-console .dev-platform-mini img { filter: drop-shadow(0 0 5px rgba(83,200,220,.22)); }
.anticheat-console .anticheat-directory-footer { min-height: 68px; padding-inline: 24px; background: #071015; }
.anticheat-console .anticheat-directory-footer button { border-radius: 5px; transition: border-color .2s ease,background .2s ease,transform .2s ease; }
.anticheat-console .anticheat-directory-footer button:not(:disabled):hover { border-color: rgba(88,226,189,.45); background: #10231f; transform: translateY(-1px); }

@keyframes ac-console-open { from { opacity:0; transform:translateY(14px) scale(.995) } to { opacity:1; transform:none } }
@keyframes ac-ambient-in { to { opacity:1 } }
@keyframes ac-masthead-in { from { opacity:0; transform:translateY(-18px) } to { opacity:1; transform:none } }
@keyframes ac-rail-in { from { opacity:0; clip-path:inset(0 100% 0 0) } to { opacity:1; clip-path:inset(0) } }
@keyframes ac-ledger-in { from { opacity:0; transform:translateY(24px) } to { opacity:1; transform:none } }
@keyframes ac-record-in { from { opacity:0; transform:translateX(16px) } to { opacity:1; transform:none } }
@keyframes ac-signal { 50% { opacity:.34; transform:scale(1.05) } }
@keyframes ac-live { 50% { opacity:.48; box-shadow:0 0 0 8px rgba(72,223,167,0),0 0 5px rgba(72,223,167,.25) } }
@media (max-width: 760px) {
  .anticheat-console .anticheat-command { grid-template-columns:1fr; min-height:0; padding:20px; }
  .anticheat-console .anticheat-command::after { display:none; }
  .anticheat-console .anticheat-metric-grid .dev-metric { min-height:102px; padding:13px 10px; }
  .anticheat-console .anticheat-directory-head { min-height:0; padding:18px; }
  .anticheat-console .anticheat-player-list { padding-inline:8px; }
}
@media (prefers-reduced-motion: reduce) {
  .anticheat-console,.anticheat-console::before,.anticheat-console .anticheat-command,.anticheat-console .anticheat-metric-grid,.anticheat-console .anticheat-directory,.anticheat-console .anticheat-player-row,.anticheat-console .anticheat-presence.online,.anticheat-console .anticheat-command-mark::after { animation:none !important; opacity:1; transform:none; }
}

