/* Staff Operations: one desktop scroll surface, with navigation kept in view. */
@media (min-width: 1051px) {
  #app:has(.dev-workspace) {
    height: auto;
    min-height: 100dvh;
    overflow: visible;
    place-items: start center;
  }

  .dev-workspace {
    height: auto;
    min-height: calc(100dvh - 32px);
    overflow: visible;
    align-items: start;
  }

  .dev-sidebar {
    position: sticky;
    top: 16px;
    align-self: start;
    height: calc(100dvh - 32px);
  }

  .dev-main {
    height: auto;
    min-height: calc(100dvh - 32px);
    max-height: none;
    display: block;
    overflow: visible;
  }

  .dev-topbar { top: 0; }

  .dev-content {
    min-height: calc(100dvh - 120px);
    overflow: visible;
    scrollbar-gutter: auto;
  }

  .dev-content::after { display: none; }
}

/* Faircroft Careers — public-service campaign experience */
.recruit-workspace {
  --career: #65b7ff;
  --career-hot: #63f2c5;
  --career-deep: #071019;
  grid-template-columns: 318px minmax(0, 1fr);
  background:
    radial-gradient(circle at 78% 9%, rgba(47, 131, 203, .16), transparent 32%),
    linear-gradient(140deg, #071019, #050b11 68%);
}
.recruit-sidebar {
  position: sticky;
  top: 0;
  height: 100dvh;
  padding: 30px 22px 20px;
  border-right: 1px solid rgba(112, 162, 192, .18);
  background: linear-gradient(180deg, rgba(14, 34, 49, .96), rgba(7, 17, 25, .98));
  scrollbar-width: thin;
}
.recruit-brand { padding: 0 5px 27px; border-bottom: 1px solid rgba(112,162,192,.17); }
.recruit-brand>span {
  width: 48px; height: 48px; border: 1px solid #69baff; border-radius: 50%;
  background: radial-gradient(circle at 32% 28%, #1f7fc1, #092237 72%);
  color: #d9efff; box-shadow: 0 0 35px rgba(79,171,237,.2), inset 0 0 18px rgba(97,188,255,.15);
}
.recruit-brand strong { font-size: 1rem; letter-spacing: -.02em; }
.recruit-brand small { margin-top: 4px; color: #5f8298; font-size: .55rem; }
.recruit-nav-label { display:flex; justify-content:space-between; margin: 24px 7px 10px; color:#66889d; }
.recruit-nav-label small { color:#64e5bb; }
.recruit-sidebar nav { gap: 0; }
.recruit-sidebar nav button {
  position: relative; min-height: 92px; grid-template-columns: 1fr auto; gap: 12px;
  padding: 17px 7px 16px 16px; border: 0; border-bottom: 1px solid rgba(112,162,192,.12);
  transition: padding .25s cubic-bezier(.16,1,.3,1), background .25s ease, color .25s ease;
}
.recruit-sidebar nav button:before {
  content:""; position:absolute; left:0; top:17px; bottom:17px; width:2px;
  background:transparent; box-shadow:none; transition:.25s;
}
.recruit-sidebar nav button:hover,.recruit-sidebar nav button.active {
  padding-left: 23px; border-color: rgba(112,162,192,.12); background: linear-gradient(90deg, rgba(77,169,232,.12), transparent); color:#f0f8ff;
}
.recruit-sidebar nav button.active:before { background:var(--career-hot); box-shadow:0 0 16px var(--career-hot); }
.recruit-sidebar nav button i { display:none; }
.recruit-sidebar nav button div { min-width:0; }
.recruit-sidebar nav button small { color:#557386; font-size:.54rem; letter-spacing:.08em; text-transform:uppercase; }
.recruit-sidebar nav button strong { margin:5px 0 3px; font-size:.86rem; }
.recruit-sidebar nav button span { display:block; overflow:hidden; color:#8ba3b2; font-size:.7rem; text-overflow:ellipsis; white-space:nowrap; }
.recruit-sidebar nav button em { align-self:start; margin-top:3px; color:#65e7bd; font-size:.52rem; font-weight:950; letter-spacing:.11em; }
.recruit-sidebar nav button em.closed { color:#d67c84; }
.recruit-my-files {
  min-height: 70px; margin-top: 22px; padding: 14px 8px; border:0; border-block:1px solid rgba(112,162,192,.15);
  background:transparent; color:#a9c0cd;
}
.recruit-my-files:hover,.recruit-my-files.active { border-color:rgba(99,242,197,.3); background:linear-gradient(90deg,rgba(99,242,197,.08),transparent); }
.recruit-my-files>span { width:26px; color:#65e7bd; }
.recruit-my-files>div { flex:1; display:grid; gap:3px; margin-left:10px; }
.recruit-my-files small { color:#607e90; font-size:.58rem; }
.recruit-my-files em { color:#65e7bd; font-style:normal; }
.recruit-main { min-height:100dvh; background:linear-gradient(90deg,rgba(255,255,255,.01),transparent 35%); }
.recruit-topbar {
  height: 86px; padding: 0 clamp(24px,4vw,66px); border-color:rgba(112,162,192,.15);
  background:rgba(5,12,18,.82); backdrop-filter:blur(22px);
}
.recruit-topbar>div:first-child p { margin:0 0 5px; color:#62dcb8; font-size:.55rem; font-weight:950; letter-spacing:.17em; }
.recruit-topbar h1 { font-size:1.22rem; letter-spacing:-.025em; }
.recruit-topbar>div:last-child { align-items:center; }
.recruit-topbar>div:last-child>span { display:flex; align-items:center; gap:8px; margin-right:9px; color:#6f8998; font-size:.58rem; letter-spacing:.08em; }
.recruit-topbar>div:last-child>span i { width:6px; height:6px; border-radius:50%; background:#61e5b9; box-shadow:0 0 13px #61e5b9; animation:careerLive 1.7s ease-in-out infinite; }
.recruit-topbar button { min-height:40px; border-radius:999px; padding-inline:18px; }
.recruit-content { width:min(1540px,100%); max-width:none; padding:clamp(28px,4vw,66px); }
.recruit-opening-view { animation:careerEnter .65s cubic-bezier(.16,1,.3,1) both; }
.recruit-opening-hero {
