.recruit-opening-hero.legal .recruit-dept-mark:before { content:"FCJ"; font-size:1rem; }
.recruit-dept-mark:after { content:""; position:absolute; inset:-13px; border:1px dashed rgba(101,183,255,.25); border-radius:50%; animation:careerOrbit 16s linear infinite reverse; }
.recruit-opening-hero>div:nth-child(2) { position:relative; z-index:2; }
.recruit-opening-hero>div:nth-child(2)>p { margin:0; color:#69dcb9; font-size:.62rem; font-weight:950; letter-spacing:.17em; text-transform:uppercase; }
