.recruit-opening-hero>div:nth-child(2)>span { display:block; max-width:700px; color:#a9c2d0; font-size:clamp(.85rem,1.2vw,1.05rem); line-height:1.55; }
.recruit-opening-status { align-self:end; padding:20px 0 4px 22px; border-left:1px solid rgba(115,185,230,.28); text-align:left; }
.recruit-opening-status:before { content:"BUILD A CAREER"; color:#4e7187; font-size:.5rem; font-weight:900; letter-spacing:.17em; }
.recruit-opening-status small { margin-top:18px; color:#5d7d90; }
.recruit-opening-status strong { font-size:.75rem; letter-spacing:.07em; }
.recruit-opening-layout { grid-template-columns:minmax(0,1fr) 380px; gap:0; border:0; background:#08121a; }
.recruit-opening-layout>main { min-width:0; padding:clamp(35px,4vw,64px); }
.recruit-position-intro { padding:0 0 44px; border-bottom:1px solid rgba(112,162,192,.18); }
