.recruit-position-intro>span { display:block; max-width:860px; color:#91aab8; font-size:.8rem; line-height:1.75; letter-spacing:.04em; }
.recruit-facts { grid-template-columns:repeat(3,1fr); margin:0; border:0; border-bottom:1px solid rgba(112,162,192,.18); }
.recruit-facts div { min-height:115px; display:grid; align-content:center; gap:8px; padding:20px 28px 20px 0; border:0; }
