/* Official Faircroft identity carried through the passport credential. */
.passport-intro>div:first-child {
  position: relative;
  padding-left: 68px;
}
.passport-intro>div:first-child:before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 50px;
  height: 50px;
  border: 1px solid rgba(79, 207, 230, .34);
  border-radius: 12px;
  background: #03060a url("/static/brand/faircroft-emblem.webp") center / 88% auto no-repeat;
  box-shadow: 0 0 28px rgba(0, 223, 249, .12), 0 0 28px rgba(255, 20, 157, .1);
  transform: translateY(-50%);
}
.passport-coat {
  background:
    linear-gradient(rgba(8, 38, 47, .2), rgba(8, 38, 47, .2)),
    #061018 url("/static/brand/faircroft-emblem.webp") center / 80% auto no-repeat;
}
.passport-coat i,
.passport-coat b { display: none; }
.passport-page-seal {
  overflow: hidden;
  border-color: rgba(39, 113, 129, .48);
  border-radius: 11px;
  background: #061018 url("/static/brand/faircroft-emblem.webp") center / 88% auto no-repeat;
  box-shadow: 0 5px 14px rgba(13, 55, 67, .18);
}
.passport-page-seal b { display: none; }
.passport-data-page:before {
  content: "";
  position: absolute;
  z-index: 0;
  right: 8%;
  top: 26%;
  width: 280px;
  height: 220px;
  opacity: .035;
  filter: grayscale(1) contrast(1.5);
  background: url("/static/brand/faircroft-emblem.webp") center / contain no-repeat;
  pointer-events: none;
}
.passport-data-page>header,
.passport-data-page>main,
.passport-signature,
.passport-data-page>footer { z-index: 1; }
.passport-hologram {
  position: relative;
  color: transparent;
  background:
    url("/static/brand/faircroft-emblem.webp") center / 72% auto no-repeat,
    conic-gradient(from 45deg,rgba(39,203,203,.2),rgba(155,83,218,.22),rgba(229,193,64,.22),rgba(39,203,203,.2));
}
.passport-hologram b { color: transparent; }
.passport-authentication:before {
  content: "";
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  border-radius: 7px;
  background: #03070a url("/static/brand/faircroft-emblem.webp") center / 90% auto no-repeat;
}
@media(max-width:720px) {
  .passport-intro>div:first-child { padding-left: 58px; }
  .passport-intro>div:first-child:before { width: 43px; height: 43px; }
  .passport-data-page:before { right: 3%; width: 190px; height: 160px; }
}
