/* Court parking registry and verified settlement command */
.court-tab-parking > .resident-court-ledger:not(.parking-court-ledger) { display: none; }
.parking-ledger-heading { display:flex; justify-content:space-between; gap:24px; align-items:end; padding:22px 24px; border-bottom:1px solid var(--line); background:linear-gradient(120deg,rgba(234,179,8,.1),transparent 55%); }
.parking-ledger-heading h2 { margin:4px 0; }
.parking-ledger-heading > span { color:#f5c84c; font-weight:900; letter-spacing:.12em; }
.settlement-command { display:grid; gap:18px; }
.settlement-command-hero { display:flex; justify-content:space-between; align-items:end; gap:30px; padding:30px 32px; border-block:1px solid var(--line); background:linear-gradient(110deg,rgba(33,214,176,.1),transparent 58%); }
.settlement-command-hero h2 { margin:4px 0 8px; font-size:clamp(28px,3vw,48px); }
.settlement-command-hero dl { display:flex; gap:0; margin:0; }
.settlement-command-hero dl div { min-width:130px; padding:0 20px; border-left:1px solid var(--line); }
.settlement-command-hero dt,.settlement-resident-ledger dt { color:var(--muted); font-size:10px; text-transform:uppercase; letter-spacing:.1em; }
.settlement-command-hero dd { margin:5px 0 0; font-size:24px; font-weight:900; }
.settlement-command-grid { display:grid; grid-template-columns:minmax(330px,.75fr) minmax(520px,1.25fr); border:1px solid var(--line); }
.settlement-notice-composer { padding:28px; border-right:1px solid var(--line); }
.settlement-notice-composer fieldset { display:grid; gap:8px; padding:0; margin:24px 0; border:0; }
.settlement-notice-composer legend { margin-bottom:10px; color:var(--muted); text-transform:uppercase; font-size:10px; letter-spacing:.12em; }
.settlement-notice-composer fieldset label { display:flex; gap:12px; align-items:center; padding:13px 0; border-bottom:1px solid var(--line); }
.settlement-notice-composer fieldset span { display:grid; gap:2px; }
.settlement-send-actions { display:flex; gap:10px; margin-top:16px; }
.settlement-notice-composer aside { display:grid; gap:5px; margin-top:24px; padding:16px 0 0 16px; border-left:3px solid #f5c84c; color:var(--muted); }
.settlement-resident-ledger { max-height:580px; overflow:auto; }
.settlement-resident-ledger > header { position:sticky; top:0; z-index:2; display:flex; justify-content:space-between; padding:22px 26px; background:var(--panel); border-bottom:1px solid var(--line); }
.settlement-resident-ledger > label { display:grid; grid-template-columns:auto 1fr auto; gap:16px; align-items:center; padding:16px 26px; border-bottom:1px solid var(--line); cursor:pointer; }
.settlement-resident-ledger > label:hover { background:rgba(33,214,176,.05); }
.settlement-resident-ledger label > span { display:grid; }
.settlement-resident-ledger dl { display:flex; gap:24px; margin:0; text-align:right; }
.settlement-resident-ledger dd { margin:3px 0 0; font-weight:800; }
.settlement-notice-history { border-top:1px solid var(--line); padding-top:22px; }
.settlement-notice-history > article { display:grid; grid-template-columns:auto minmax(180px,1fr) minmax(180px,1fr) auto; gap:14px; align-items:center; padding:13px 4px; border-bottom:1px solid var(--line); }
.settlement-notice-history article > span { width:9px; height:9px; border-radius:50%; background:#f5c84c; box-shadow:0 0 12px currentColor; }
.settlement-notice-history article > span.acknowledged { background:#35dbab; }
.settlement-notice-modal { max-width:720px; }
.settlement-notice-modal header { display:flex; gap:18px; align-items:center; }
.settlement-notice-seal { display:grid; place-items:center; width:58px; height:58px; border:1px solid #f5c84c; border-radius:50%; color:#f5c84c; font-weight:900; }
.settlement-notice-body { display:grid; gap:18px; padding:24px 0; }
.settlement-notice-body > strong { color:#ff687d; letter-spacing:.12em; }
.settlement-notice-body dl { display:grid; grid-template-columns:repeat(3,1fr); margin:0; border-block:1px solid var(--line); }
.settlement-notice-body dl div { padding:14px; border-right:1px solid var(--line); }
.settlement-notice-body dd { margin:5px 0 0; font-size:20px; font-weight:900; }
.settlement-notice-body aside { display:grid; gap:5px; padding:15px; background:rgba(245,200,76,.08); border-left:3px solid #f5c84c; }
.settlement-tax-ledger > article { display:grid; grid-template-columns:1fr auto minmax(300px,.7fr); gap:24px; align-items:center; padding:18px 4px; border-bottom:1px solid var(--line); }
.settlement-tax-ledger dl { display:flex; gap:22px; }
.settlement-command:has(.settlement-business-tax-command) > .settlement-tax-ledger { display:none; }
.settlement-business-tax-command { border:1px solid var(--line); border-top:2px solid #35dbab; background:linear-gradient(145deg,rgba(33,214,176,.055),transparent 42%); }
.settlement-business-tax-command > header { display:grid; grid-template-columns:minmax(300px,1fr) auto; gap:32px; align-items:end; padding:28px 30px 22px; border-bottom:1px solid var(--line); }
.settlement-business-tax-command > header h2 { margin:4px 0 6px; font-size:clamp(27px,2.4vw,42px); letter-spacing:-.045em; }
.settlement-business-tax-command > header p { max-width:720px; margin:0; color:var(--muted); }
.settlement-business-tax-command > header dl { display:flex; margin:0; }
.settlement-business-tax-command > header dl div { min-width:130px; padding-left:22px; border-left:1px solid var(--line); }
.settlement-business-tax-command dt,.settlement-business-ledger dt { color:var(--muted); font-size:9px; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }
.settlement-business-tax-command dd { margin:5px 0 0; font-size:20px; font-weight:900; }
.settlement-tax-status-line { display:flex; gap:24px; align-items:center; padding:12px 30px; border-bottom:1px solid var(--line); color:var(--muted); font-size:12px; }
.settlement-tax-status-line b { color:var(--text); font-size:16px; }
.settlement-tax-status-line small { margin-left:auto; }
.settlement-business-ledger > article { display:grid; grid-template-columns:minmax(240px,.8fr) auto minmax(400px,1.15fr); gap:26px; align-items:center; padding:20px 30px; border-bottom:1px solid var(--line); box-shadow:inset 3px 0 transparent; }
.settlement-business-ledger > article:hover { background:rgba(33,214,176,.035); }
