.market-v7-light{--r7-bg:#f4f8f6;--r7-paper:#fffffc;--r7-panel:#f7fbf8;--r7-ink:#10291f;--r7-muted:#62756e;--r7-line:rgba(16,40,68,.12);--r7-green:#008f5d;--r7-blue:#3177bc;--r7-alert:#c93445}
.market-v7-dark .market-v7-top{background:rgba(7,17,15,.86);border-color:var(--r7-line);box-shadow:0 18px 70px rgba(0,0,0,.36)}.market-v7-dark .market-v7-top nav{background:rgba(255,255,255,.045)}.market-v7-dark .market-v7-top button{color:#d9f7ec}.market-v7-dark .market-v7-top button:hover{background:rgba(52,226,154,.12);box-shadow:none}.market-v7-dark .market-v7-top>div:last-child button:last-child{background:#eefaf5;color:#07110f}.market-v7-dark .market-v7-home{background:linear-gradient(145deg,rgba(13,27,24,.96),rgba(7,18,15,.98));border-color:var(--r7-line);box-shadow:var(--r7-shadow)}
.market-v7-dark .market-v7-account,.market-v7-dark .market-v7-order{background:linear-gradient(180deg,rgba(13,27,24,.96),rgba(7,18,15,.82));border-color:var(--r7-line)}.market-v7-dark .market-v7-focus{background:radial-gradient(circle at 86% 12%,rgba(52,226,154,.12),transparent 30%),linear-gradient(180deg,rgba(13,27,24,.92),rgba(6,14,12,.95))}.market-v7-dark .market-v7-hero h1,.market-v7-dark .market-v7-discover h2,.market-v7-dark .market-v7-chart-head strong{color:#f5fff9}.market-v7-dark .market-v7-hero p,.market-v7-dark .market-v7-account small,.market-v7-dark .market-v7-statline small,.market-v7-dark .market-v7-positions small{color:var(--r7-muted)}.market-v7-dark .market-v7-statline{border-color:var(--r7-line)}.market-v7-dark .market-v7-statline span{border-color:var(--r7-line);background:rgba(255,255,255,.02)}.market-v7-dark .market-v7-chart{background:linear-gradient(180deg,#0f241f,#081410)!important;box-shadow:inset 0 0 0 1px var(--r7-line),0 28px 80px rgba(0,0,0,.26)!important}.market-v7-dark .market-v7-chart .market-chart-grid{background:repeating-linear-gradient(0deg,transparent,transparent 70px,rgba(116,255,197,.08) 71px),repeating-linear-gradient(90deg,transparent,transparent 16.5%,rgba(116,255,197,.08) 16.7%)}.market-v7-dark .market-v7-order .market-order-ticket{background:rgba(255,255,255,.04)!important;color:#eefaf5!important;box-shadow:inset 0 0 0 1px var(--r7-line),0 22px 54px rgba(0,0,0,.2)!important}.market-v7-dark .market-v7-order .market-order-ticket input,.market-v7-dark .market-v7-order .market-order-ticket select{background:#07110f!important;color:#eefaf5!important;border-color:var(--r7-line)!important}
.market-v7-ops{margin-top:30px;padding-top:26px;border-top:1px solid var(--r7-line)}.market-v7-ops header{align-items:center}.market-v7-ops>div{display:grid!important;grid-template-columns:1fr!important;gap:0!important;overflow:visible!important;padding:0!important;border:1px solid var(--r7-line);border-radius:28px;background:linear-gradient(180deg,rgba(255,255,255,.7),rgba(255,255,255,.36));box-shadow:inset 0 1px rgba(255,255,255,.7)}.market-v7-dark .market-v7-ops>div{background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.018));box-shadow:inset 0 1px rgba(255,255,255,.06)}
.market-v7-ops button{width:100%;min-height:62px!important;display:grid!important;grid-template-columns:48px minmax(180px,1fr) minmax(130px,.7fr) 120px 90px!important;align-items:center;gap:18px;border:0!important;border-radius:0!important;background:transparent!important;color:var(--r7-ink)!important;text-align:left!important;box-shadow:none!important;border-bottom:1px solid var(--r7-line)!important;transition:background .18s,transform .18s,padding .18s}.market-v7-ops button:last-child{border-bottom:0!important}.market-v7-ops button:hover,.market-v7-ops button.active{transform:none!important;background:linear-gradient(90deg,rgba(52,226,154,.14),transparent 72%)!important;padding-left:22px!important}.market-v7-ops button>b{font-size:12px;color:var(--r7-muted);letter-spacing:.14em}.market-v7-ops button span{display:grid;gap:2px}.market-v7-ops button span strong{font-size:15px;margin:0}.market-v7-ops button span small,.market-v7-ops button i{font-style:normal;color:var(--r7-muted);font-size:12px}.market-v7-ops button em{font-style:normal;font-weight:950;text-align:right}.market-v7-ops button mark{justify-self:end;border-radius:999px;padding:6px 9px;background:rgba(52,226,154,.12);font-size:11px;font-weight:1000}.market-v7-ops button mark.down{background:rgba(255,84,112,.13)}
.market-v7-light .market-v7-ops button.active{background:linear-gradient(90deg,rgba(0,143,93,.12),transparent 72%)!important}
@media(max-width:860px){.market-v7-top>div:last-child button[data-market-theme]{display:inline-flex}.market-v7-ops>div{border-radius:22px}.market-v7-ops button{grid-template-columns:34px 1fr auto!important;gap:10px;min-height:72px!important;padding:12px!important}.market-v7-ops button i,.market-v7-ops button em{display:none}.market-v7-ops button mark{grid-column:3}.market-v7-dark .market-v7-mobile-actions{background:rgba(7,17,15,.92)!important;border-color:var(--r7-line)!important}.market-v7-dark .market-v7-mobile-actions button{background:rgba(52,226,154,.13)!important;color:#eafff5!important}}

/* Ravenhood v8.5: denser 2026 trader surface, account standing, and institutional charting. */
.market-v7-home{grid-template-columns:minmax(220px,260px) minmax(0,1fr);width:min(1760px,calc(100% - 36px));border-radius:26px}
.market-v7-account{padding:22px}.market-v7-card{padding:22px;border-radius:24px}.market-v7-card strong{font-size:clamp(28px,2.4vw,38px)}.market-v7-actions button{min-height:42px;font-size:12px}
.market-v7-standing{padding:16px 0!important}.market-v7-standing dl{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0}.market-v7-standing div{padding:12px;border-radius:14px;background:rgba(52,226,154,.07);border:1px solid var(--r7-line)}.market-v7-standing dt{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--r7-muted);font-weight:1000}.market-v7-standing dd{margin:5px 0 0;font-weight:1000;color:var(--r7-ink);font-size:13px}
.market-v7-focus{padding:34px clamp(24px,3.4vw,54px)}.market-v7-hero{grid-template-columns:minmax(0,1fr) minmax(190px,250px);align-items:stretch}.market-v7-hero h1{display:grid;gap:6px;margin:12px 0 14px;line-height:.88}.market-v7-hero h1>b{font-size:clamp(74px,8.5vw,142px);letter-spacing:-.11em;color:var(--r7-ink);font-weight:1000}.market-v7-hero h1>small{font-size:clamp(24px,2.4vw,42px);letter-spacing:-.055em;color:var(--r7-muted);font-weight:850;line-height:1.05}.market-v7-quote-card{position:relative;overflow:hidden;border-radius:28px!important;text-align:left!important;background:linear-gradient(155deg,rgba(52,226,154,.16),rgba(105,183,255,.08)),#07110f!important;border:1px solid var(--r7-line);box-shadow:0 24px 70px rgba(0,0,0,.28)!important}.market-v7-light .market-v7-quote-card{background:linear-gradient(155deg,#102844,#0a7656)!important;color:#fff}.market-v7-quote-card:after{content:"";position:absolute;inset:auto -45px -55px auto;width:170px;height:170px;border-radius:50%;border:34px solid rgba(255,255,255,.055)}.market-v7-quote-card span{display:block;margin-top:14px;color:var(--r7-muted);font-size:11px}.market-v7-light .market-v7-quote-card span{color:rgba(255,255,255,.7)}
.market-v7-statline{grid-template-columns:repeat(4,minmax(0,1fr));margin:22px 0}.market-v7-chart-head{margin-top:10px}.market-v7-chart{position:relative;height:clamp(500px,54vh,680px)!important;border-radius:22px!important;overflow:hidden}.market-v7-chart:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 80% 18%,rgba(52,226,154,.18),transparent 26%),linear-gradient(90deg,transparent,rgba(255,255,255,.045),transparent);pointer-events:none;animation:marketDepthPulse 7s ease-in-out infinite alternate}.market-v7-depth{position:absolute;inset:50px 24px 54px 24px;display:grid;grid-template-columns:repeat(6,1fr);align-items:end;gap:10px;opacity:.55;pointer-events:none}.market-v7-depth i{display:block;border-radius:10px 10px 0 0;background:linear-gradient(180deg,rgba(52,226,154,.24),rgba(52,226,154,.025));height:calc(42px + var(--bar, 1)*26px);animation:marketBarPulse 4s ease-in-out infinite alternate}.market-v7-depth i:nth-child(1){--bar:3}.market-v7-depth i:nth-child(2){--bar:5;animation-delay:.25s}.market-v7-depth i:nth-child(3){--bar:4;animation-delay:.5s}.market-v7-depth i:nth-child(4){--bar:7;animation-delay:.75s}.market-v7-depth i:nth-child(5){--bar:5;animation-delay:1s}.market-v7-depth i:nth-child(6){--bar:6;animation-delay:1.25s}.market-v7-chart svg{position:relative;z-index:2}.market-v7-chart .market-recorded-line{filter:drop-shadow(0 0 12px currentColor)}.market-v7-chart-readout{position:absolute;z-index:4;left:18px;right:18px;top:16px;display:flex;gap:10px;justify-content:flex-end}.market-v7-chart-readout span{border-radius:999px;background:rgba(255,255,255,.08);border:1px solid var(--r7-line);padding:7px 10px;font-size:10px;font-weight:1000;color:var(--r7-ink)}.market-v7-light .market-v7-chart-readout span{background:rgba(255,255,255,.72)}
.market-v7-order{padding:0 22px 24px}.market-v7-order .market-order-ticket{border-radius:22px!important}.market-v7-positions button{min-height:42px}.market-v7-ops>div{border-radius:18px}.market-v7-ops button{min-height:54px!important;grid-template-columns:42px minmax(160px,1fr) minmax(120px,.6fr) 108px 82px!important}
@keyframes marketDepthPulse{to{filter:saturate(1.35) brightness(1.08)}}@keyframes marketBarPulse{to{transform:scaleY(1.12);opacity:.9}}
@media(max-width:1180px){.market-v7-home{grid-template-columns:1fr}.market-v7-account{grid-template-columns:1fr 1fr}.market-v7-standing{grid-column:auto!important}.market-v7-order{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:860px){.market-v7-home{width:100%;border-radius:0}.market-v7-account{display:block;padding:14px}.market-v7-focus{padding:18px 14px}.market-v7-hero{display:block}.market-v7-hero h1>b{font-size:64px}.market-v7-hero h1>small{font-size:24px}.market-v7-quote-card{margin-top:14px}.market-v7-chart{height:420px!important}.market-v7-chart-readout{justify-content:flex-start;flex-wrap:wrap}.market-v7-standing dl{grid-template-columns:1fr 1fr}.market-v7-order{display:block;padding:0 14px 108px}.market-v7-ops button{grid-template-columns:34px 1fr auto!important}}

/* Ravenhood v9: trading-floor restructure, not boxed app panels. */
.market-v9{background:#030806;color:#eafff5}.market-v9 .market-v7-top{height:64px;background:rgba(3,8,6,.92);border-bottom:1px solid rgba(77,255,183,.18)}.market-v9 .market-v7-brand>span{width:40px;height:40px;border-radius:13px}.market-v9 .market-v7-top nav{background:transparent;border:1px solid rgba(77,255,183,.14)}.market-v9 .market-v7-tape{height:36px;background:#06100d;border-bottom:1px solid rgba(77,255,183,.12)}.market-v9 .market-v7-tape button{height:36px;min-width:138px;font-size:11px}
