.market-v9 .market-v7-focus{grid-column:1;grid-row:2;padding:28px clamp(22px,3vw,48px);background:radial-gradient(circle at 80% 0,rgba(52,226,154,.12),transparent 30%),#030806}.market-v9 .market-v7-hero{grid-template-columns:minmax(0,1fr) 210px;gap:24px;padding-bottom:18px;border-bottom:1px solid rgba(77,255,183,.14)}.market-v9 .market-v7-hero h1>b{font-size:clamp(58px,6vw,100px);line-height:.8}.market-v9 .market-v7-hero h1>small{font-size:clamp(22px,2vw,34px);font-weight:800;color:#9fbdb1}.market-v9 .market-v7-hero p{font-size:15px;max-width:820px;color:#91b5a7}.market-v9 .market-v7-quote-card{border-radius:18px!important;background:rgba(255,255,255,.045)!important;box-shadow:inset 0 0 0 1px rgba(77,255,183,.16)!important}.market-v9 .market-v7-quote-card:after{opacity:.45}
.market-v9 .market-v7-statline{margin:18px 0 16px;border:1px solid rgba(77,255,183,.12);background:rgba(255,255,255,.022);border-radius:16px}.market-v9 .market-v7-statline span{padding:13px 16px}.market-v9 .market-v7-chart-head{margin:12px 0}.market-v9 .market-v7-chart-head nav{background:rgba(255,255,255,.06);border:1px solid rgba(77,255,183,.12)}.market-v9 .market-v7-chart{height:min(58vh,610px)!important;border-radius:18px!important;background:linear-gradient(180deg,#081710,#030806)!important}.market-v9 .market-v7-depth{opacity:.32;z-index:1}.market-v9 .market-v9-candles{position:absolute;z-index:3;inset:44px 28px 62px 28px;pointer-events:none}.market-v9 .market-v9-candles i{position:absolute;bottom:calc(100% - var(--mid));left:calc(var(--x)*5.68%);width:9px;height:var(--h);border-radius:8px;background:#39e6a1;box-shadow:0 0 14px rgba(57,230,161,.45);transform:translateY(50%)}.market-v9 .market-v9-candles i:before{content:"";position:absolute;left:4px;top:-14px;bottom:-14px;width:1px;background:currentColor;opacity:.65}.market-v9 .market-v9-candles i.down{background:#ff4d6b;color:#ff4d6b;box-shadow:0 0 14px rgba(255,77,107,.38)}.market-v9 .market-v7-chart svg{opacity:.74}.market-v9 .market-v7-chart-readout{top:14px}.market-v9 .market-v7-chart-readout span{background:rgba(3,8,6,.72);border-color:rgba(77,255,183,.16)}
.market-v9 .market-v7-ops{margin-top:20px}.market-v9 .market-v7-ops>div{border-radius:14px;background:rgba(255,255,255,.025)}.market-v9 .market-v7-ops button{min-height:46px!important}
