.market-v9.market-v7-light{background:#eef4f0;color:#10291f}.market-v9.market-v7-light .market-v7-top{background:rgba(255,255,255,.9)}.market-v9.market-v7-light .market-v7-home{background:#f7faf8}.market-v9.market-v7-light .market-v7-focus{background:#fff}.market-v9.market-v7-light .market-v7-order{background:#edf5f1}.market-v9.market-v7-light .market-v7-chart{background:linear-gradient(180deg,#f9fffc,#e8f4ee)!important}
