/* Ravenhood v10: account-first trading desk */
.market-v10 .market-v7-top nav{border:0;background:rgba(255,255,255,.035);backdrop-filter:blur(18px)}
.market-v10 .market-v7-top nav button{border-radius:999px}
.market-v10 .market-v7-home{grid-template-columns:minmax(0,1fr) 330px;background:
  radial-gradient(circle at 18% 18%,rgba(73,255,184,.11),transparent 24%),
  radial-gradient(circle at 86% 42%,rgba(59,139,255,.08),transparent 28%),
  linear-gradient(135deg,#020605,#06120e 52%,#020604)}
.market-v10 .market-v7-account{grid-template-columns:260px minmax(0,1fr) 220px;padding:16px 26px;background:rgba(2,8,6,.56);backdrop-filter:blur(18px)}
.market-v10 .market-v7-card{background:linear-gradient(135deg,rgba(49,233,158,.25),rgba(67,129,255,.16));border:1px solid rgba(104,255,202,.16);box-shadow:0 24px 80px rgba(0,0,0,.32),inset 0 1px rgba(255,255,255,.08)}
.market-v10 .market-v7-standing div{background:transparent;border:0;border-bottom:1px solid rgba(104,255,202,.11);border-radius:0}
.market-v10 .market-v7-actions button{border-radius:999px;border:1px solid rgba(104,255,202,.22);background:rgba(255,255,255,.045);color:#eafff5;box-shadow:none}
.market-v10 .market-v7-actions button:first-child{background:linear-gradient(135deg,#37eba3,#69b7ff);color:#04100b;border:0}
.market-v10 .market-v7-focus{padding-top:24px;background:
  linear-gradient(90deg,rgba(255,255,255,.018),transparent 28%,rgba(255,255,255,.018)),
  radial-gradient(circle at 75% 4%,rgba(52,226,154,.14),transparent 28%)}
