.market-v10 .market-v7-quote-card{border-radius:30px!important;background:
  linear-gradient(145deg,rgba(52,226,154,.2),rgba(105,183,255,.08)),
  rgba(255,255,255,.035)!important}
.market-v10-portfolio{margin:16px 0 22px;padding:0;border-top:1px solid rgba(104,255,202,.16);border-bottom:1px solid rgba(104,255,202,.16);position:relative;overflow:hidden}
.market-v10-portfolio:before{content:"";position:absolute;inset:-40% -10% auto 45%;height:220px;background:radial-gradient(circle,rgba(54,235,160,.16),transparent 62%);filter:blur(8px);pointer-events:none;animation:marketV10Sweep 6s ease-in-out infinite alternate}
.market-v10-portfolio-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding:24px 4px 18px;position:relative;z-index:1}
