.market-v10-portfolio-head h2{font-size:clamp(28px,3vw,48px);letter-spacing:-.055em;margin:6px 0 5px}
.market-v10-portfolio-head p{margin:0;color:#92b3a7}
.market-v10-portfolio-head>strong{font-size:clamp(24px,2.5vw,38px);letter-spacing:-.04em;text-align:right}
