.property-tax-rate-selector {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: .55rem;
  margin: .25rem 0;
  padding: 0;
  border: 0;
}
.property-tax-rate-selector legend { grid-column: 1 / -1; color: var(--muted); font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; }
.property-tax-rate-selector label { cursor: pointer; }
.property-tax-rate-selector input { position: absolute; opacity: 0; pointer-events: none; }
.property-tax-rate-selector span { display: flex; flex-direction: column; padding: .7rem .8rem; border: 1px solid var(--line); background: color-mix(in srgb, var(--panel) 88%, transparent); transition: .18s ease; }
.property-tax-rate-selector b { font-size: 1rem; }
.property-tax-rate-selector small { color: var(--muted); }
.property-tax-rate-selector input:checked + span { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 13%, var(--panel)); box-shadow: inset 0 -2px var(--accent); }
@media (max-width: 680px) { .property-tax-rate-selector { grid-template-columns: 1fr; } }
