/* Faircroft public statistics bureau */
.stats-workspace{--stats-cyan:#68e8ee;--stats-blue:#4d8dff;--stats-gold:#efc66a;--stats-ink:#071117;min-height:100vh;color:#edf8f7;background:radial-gradient(circle at 78% 8%,rgba(37,112,137,.22),transparent 32%),linear-gradient(145deg,#061015,#091820 48%,#071218);font-family:Inter,ui-sans-serif,system-ui,sans-serif;overflow:hidden}
.stats-topbar{min-height:78px;padding:0 clamp(24px,4vw,72px);display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:1px solid rgba(125,222,226,.16);background:rgba(4,12,17,.9);backdrop-filter:blur(18px);position:relative;z-index:5}.stats-brand{display:flex;gap:13px;align-items:center;color:inherit;text-decoration:none}.stats-brand>span{width:42px;height:42px;border:1px solid var(--stats-cyan);border-radius:50%;display:grid;place-items:center;font-family:Georgia,serif;font-weight:800;color:var(--stats-cyan);box-shadow:0 0 28px rgba(104,232,238,.14)}.stats-brand small,.stats-brand strong{display:block}.stats-brand small{font-size:9px;letter-spacing:.22em;color:#6ca4aa}.stats-brand strong{font-family:Georgia,serif;font-size:17px}.stats-topbar nav{height:78px;display:flex}.stats-topbar nav button{border:0;border-bottom:2px solid transparent;background:none;color:#7f9ba0;padding:0 24px;font-size:13px;cursor:pointer}.stats-topbar nav button:hover,.stats-topbar nav button.active{color:#fff;border-color:var(--stats-cyan)}.stats-topbar>div{justify-self:end;display:flex;align-items:center;gap:10px}.stats-topbar>div button,.stats-footer button{border:1px solid rgba(133,210,215,.28);background:rgba(255,255,255,.06);color:#edf8f7;padding:11px 16px;border-radius:999px;cursor:pointer}.stats-topbar>div button:last-child{border-color:var(--stats-cyan);color:var(--stats-cyan)}.stats-live{font-size:9px;letter-spacing:.16em;color:#8eafb2;margin-right:8px}.stats-live i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#4ff1b4;box-shadow:0 0 15px #4ff1b4;margin-right:7px;animation:statsPulse 1.8s infinite}
.stats-masthead{max-width:1500px;margin:auto;padding:clamp(70px,9vw,150px) clamp(28px,6vw,96px) 70px;display:grid;grid-template-columns:1fr 310px;position:relative}.stats-masthead:before{content:"FAIRCROFT";position:absolute;right:-.03em;bottom:-.14em;font-size:clamp(120px,20vw,350px);font-weight:950;letter-spacing:-.08em;color:rgba(112,232,236,.018);pointer-events:none}.stats-masthead small,.stats-story header>span,.stats-economy-number>small{font-size:10px;letter-spacing:.24em;color:var(--stats-cyan);font-weight:800}.stats-masthead h1{font-size:clamp(64px,9vw,142px);line-height:.78;letter-spacing:-.075em;margin:24px 0 32px}.stats-masthead h1 em{font-style:normal;color:transparent;-webkit-text-stroke:1px rgba(120,229,234,.72)}.stats-masthead p{max-width:650px;color:#9bb4b7;font-size:18px;line-height:1.65}.stats-masthead aside{align-self:end;border-left:1px solid rgba(104,232,238,.25);padding:28px 0 28px 34px}.stats-masthead aside span,.stats-masthead aside small,.stats-masthead aside time{display:block}.stats-masthead aside span{font-size:9px;letter-spacing:.2em;color:#73969b}.stats-masthead aside strong{display:block;font:700 64px/1 Georgia,serif;margin:16px 0 5px}.stats-masthead aside small{color:#8fa6aa}.stats-masthead aside time{margin-top:25px;font-size:10px;color:#56747a}
.stats-view{border-top:1px solid rgba(116,215,220,.16)}.stats-story{max-width:1500px;margin:auto;min-height:750px;padding:75px clamp(28px,6vw,96px) 110px;position:relative}.stats-story>header{max-width:850px;margin-bottom:62px}.stats-story h2{font:700 clamp(42px,5vw,76px)/.98 Georgia,serif;letter-spacing:-.04em;margin:14px 0 20px}.stats-story header p{color:#90a9ad;font-size:16px;line-height:1.7;max-width:720px}.stats-overview-story{display:grid;grid-template-columns:minmax(0,1fr) 400px;column-gap:70px}.stats-overview-story>header{grid-column:1}.stats-radar{grid-column:2;grid-row:1/3;width:min(32vw,400px);aspect-ratio:1;place-self:start center;border:1px solid rgba(104,232,238,.26);border-radius:50%;position:relative;display:grid;place-items:center;background:radial-gradient(circle,rgba(65,193,202,.15),transparent 62%)}.stats-radar i{position:absolute;border:1px solid rgba(104,232,238,.16);border-radius:50%;inset:12%}.stats-radar i:nth-child(2){inset:27%}.stats-radar i:nth-child(3){inset:41%}.stats-radar b{position:absolute;width:48%;height:1px;left:50%;top:50%;transform-origin:left;transform:rotate(-35deg);background:linear-gradient(90deg,var(--stats-cyan),transparent);animation:statsSweep 5s linear infinite}.stats-radar span{font:700 70px Georgia,serif;color:var(--stats-cyan);text-shadow:0 0 35px rgba(104,232,238,.35)}.stats-kpi-run{grid-column:1;display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid rgba(120,212,217,.18);border-bottom:1px solid rgba(120,212,217,.18)}.stats-kpi-run article{padding:28px 25px 28px 0}.stats-kpi-run article:nth-child(even){padding-left:30px;border-left:1px solid rgba(120,212,217,.18)}.stats-kpi-run small,.stats-kpi-run span{display:block}.stats-kpi-run small{color:#6c9095;font-size:9px;letter-spacing:.16em}.stats-kpi-run strong{font:700 42px Georgia,serif}.stats-kpi-run strong em{font-size:16px;color:#79989d}.stats-kpi-run span{font-size:12px;color:#8ca8ac;margin-top:5px}.stats-rate-field{grid-column:1/3;display:grid;grid-template-columns:repeat(4,1fr);gap:34px;margin-top:70px}.stats-arc{display:flex;align-items:center;gap:18px}.stats-arc-visual{width:98px;height:98px;position:relative;flex:none}.stats-arc svg{width:100%;transform:rotate(-90deg)}.stats-arc circle{fill:none;stroke:rgba(131,207,212,.12);stroke-width:7}.stats-arc .meter{stroke:var(--stats-cyan);stroke-linecap:round;stroke-dasharray:314;stroke-dashoffset:calc(314 - (314 * var(--stat-value))/100);filter:drop-shadow(0 0 5px rgba(104,232,238,.55));animation:statsDraw 1.1s ease-out}.stats-arc.gold .meter{stroke:var(--stats-gold)}.stats-arc.violet .meter{stroke:#b994ff}.stats-arc.green .meter{stroke:#53e8a9}.stats-arc-visual strong{position:absolute;inset:0;display:grid;place-items:center;font:700 23px Georgia,serif}.stats-arc-visual small{font-size:10px}.stats-arc>div+div span{font-weight:700}.stats-arc p{font-size:12px;color:#769399;line-height:1.5;margin-top:7px}
.stats-split-signal{display:grid;grid-template-columns:440px 1fr;gap:80px;align-items:center}.stats-crime-orbit{aspect-ratio:1;border:1px solid rgba(104,232,238,.2);border-radius:50%;display:grid;place-items:center;position:relative;background:radial-gradient(circle,rgba(78,170,190,.12),transparent 65%)}.stats-crime-orbit:before,.stats-crime-orbit:after{content:"";position:absolute;border-radius:50%;border:1px dashed rgba(104,232,238,.16);inset:9%}.stats-crime-orbit:after{inset:24%}.stats-crime-orbit div{text-align:center;z-index:1}.stats-crime-orbit strong,.stats-crime-orbit span{display:block}.stats-crime-orbit strong{font:700 72px Georgia,serif}.stats-crime-orbit span{color:#88a7ab}.stats-crime-orbit i{position:absolute;inset:-7px;border-radius:50%;background:conic-gradient(#ff6375 var(--violent),rgba(87,224,183,.2) 0);mask:radial-gradient(transparent 70%,#000 71%);animation:statsRotate 18s linear infinite}.stats-split-signal dl{margin:0}.stats-split-signal dl div{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid rgba(110,207,212,.16);padding:23px 0}.stats-split-signal dt{color:#8ea6aa}.stats-split-signal dd{font:700 36px Georgia,serif}.stats-split-signal dd small{font:700 12px sans-serif;color:var(--stats-cyan);margin-left:12px}.stats-flow-line{display:grid;grid-template-columns:1fr 50px 1fr 50px 1fr 50px 1fr;align-items:center;margin-top:75px}.stats-flow-line article{padding:20px 0}.stats-flow-line span{font-size:10px;color:var(--stats-cyan)}.stats-flow-line strong{display:block;font:700 38px Georgia,serif}.stats-flow-line p{color:#79969b;font-size:12px}.stats-flow-line>i{height:1px;background:linear-gradient(90deg,var(--stats-cyan),transparent)}.stats-service-ledger{display:grid;grid-template-columns:repeat(4,1fr);margin-top:50px;border-top:1px solid rgba(110,207,212,.16);border-bottom:1px solid rgba(110,207,212,.16)}.stats-service-ledger article{padding:28px}.stats-service-ledger article+article{border-left:1px solid rgba(110,207,212,.16)}.stats-service-ledger span{font-size:9px;letter-spacing:.18em;color:#698c91}.stats-service-ledger strong{display:block;font:700 30px Georgia,serif;margin:7px 0}.stats-service-ledger p{font-size:12px;color:#789499}
.stats-economy-number{margin-top:30px;padding:15px 0 48px;border-bottom:1px solid rgba(110,207,212,.18)}.stats-economy-number strong{display:block;font:700 clamp(64px,8vw,120px)/1 Georgia,serif;letter-spacing:-.045em;margin:20px 0}.stats-economy-number span{color:#819fa4}.stats-benchmark{display:grid;grid-template-columns:1fr 120px 1fr;align-items:center;padding:38px 0}.stats-benchmark div span,.stats-benchmark div strong{display:block}.stats-benchmark div span{font-size:10px;letter-spacing:.16em;color:#6d9297}.stats-benchmark div strong{font:700 34px Georgia,serif;margin-top:8px}.stats-benchmark div:last-child{text-align:right}.stats-benchmark>i{height:1px;background:linear-gradient(90deg,transparent,var(--stats-cyan),transparent)}.stats-distribution{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;margin:30px 0 55px}.stats-distribution>div{animation:statsRise .65s both;animation-delay:calc(var(--segment-index)*.08s)}.stats-distribution span,.stats-distribution strong,.stats-distribution small{display:block}.stats-distribution span{font-weight:700}.stats-distribution i{display:block;height:90px;border-left:2px solid rgba(102,231,236,.18);margin:15px 0;position:relative}.stats-distribution i b{position:absolute;bottom:0;left:-2px;width:2px;height:var(--segment);max-height:100%;background:var(--stats-cyan);box-shadow:0 0 12px var(--stats-cyan)}.stats-distribution strong{font:700 28px Georgia,serif}.stats-distribution small{color:#6f9095;margin-top:4px}.stats-privacy-seal{display:flex;align-items:center;gap:20px;border-top:1px solid rgba(110,207,212,.16);padding-top:30px}.stats-privacy-seal>span{width:48px;color:#55e6ad}.stats-privacy-seal svg{width:100%}.stats-privacy-seal strong{display:block}.stats-privacy-seal p{color:#759399;font-size:12px;margin-top:6px}
.stats-economy-number strong em{font:400 .25em/1 sans-serif;color:#7ea0a4;letter-spacing:0}.stats-activity-measure{align-self:stretch;display:flex;flex-direction:column;justify-content:center;border-left:1px solid rgba(110,207,212,.18);padding-left:30px}.stats-activity-measure small{color:#6c9095;font-size:9px;letter-spacing:.16em}.stats-activity-measure strong{font:700 52px/1 Georgia,serif;margin:12px 0 8px}.stats-activity-measure span{font-size:12px;color:#78969b}
.stats-community-map{display:grid;grid-template-columns:1.25fr 1fr 1fr;border-top:1px solid rgba(110,207,212,.18);border-bottom:1px solid rgba(110,207,212,.18)}.stats-community-map article{padding:38px 35px 36px 0}.stats-community-map article+article{border-left:1px solid rgba(110,207,212,.18);padding-left:35px}.stats-community-map small{letter-spacing:.16em;color:#6e9297}.stats-community-map strong{display:block;font:700 54px Georgia,serif;margin:15px 0 0}.stats-community-map p{color:#88a3a7}.stats-community-map>article>i,.stats-platform-strip i{display:block;height:3px;background:rgba(108,205,210,.12);margin:26px 0}.stats-community-map i b,.stats-platform-strip i b{display:block;height:100%;width:var(--fill);background:linear-gradient(90deg,var(--stats-cyan),#4b88ff);box-shadow:0 0 12px rgba(104,232,238,.35);animation:statsWidth .9s ease-out}.stats-community-map footer{display:flex;gap:20px;flex-wrap:wrap}.stats-community-map footer span{font-size:11px;color:#79979c}.stats-platform-strip{margin-top:65px}.stats-platform-strip header{display:flex;justify-content:space-between;border-bottom:1px solid rgba(110,207,212,.18);padding-bottom:18px}.stats-platform-strip header span{font-size:10px;letter-spacing:.18em;color:var(--stats-cyan)}.stats-platform-strip>div{display:grid;grid-template-columns:180px 1fr 70px;align-items:center;gap:18px;padding-top:16px}.stats-platform-strip>div i{margin:0}.stats-platform-strip>div strong{text-align:right}.stats-platform-strip>p{color:#789499;padding:30px 0}
.stats-footer{min-height:90px;border-top:1px solid rgba(110,207,212,.16);display:flex;align-items:center;gap:25px;padding:0 clamp(28px,6vw,96px);background:#050d11}.stats-footer>span{font-size:10px;letter-spacing:.2em;color:var(--stats-cyan)}.stats-footer p{color:#66858a;font-size:11px;flex:1}.stats-footer button{background:transparent}
@keyframes statsPulse{50%{opacity:.35;transform:scale(.75)}}@keyframes statsSweep{to{transform:rotate(325deg)}}@keyframes statsRotate{to{transform:rotate(360deg)}}@keyframes statsDraw{from{stroke-dashoffset:314}}@keyframes statsRise{from{opacity:0;transform:translateY(18px)}}@keyframes statsWidth{from{width:0}}
@media(max-width:900px){.stats-topbar{grid-template-columns:1fr auto;padding:12px 18px}.stats-topbar nav{grid-column:1/3;grid-row:2;height:auto;overflow:auto}.stats-topbar nav button{padding:16px 18px;white-space:nowrap}.stats-live{display:none}.stats-topbar>div button:first-of-type{display:none}.stats-masthead{grid-template-columns:1fr;padding-top:70px}.stats-masthead aside{margin-top:45px}.stats-story{padding:52px 24px 80px}.stats-overview-story{display:block}.stats-radar{width:min(78vw,360px);margin:45px auto}.stats-kpi-run{grid-template-columns:1fr 1fr}.stats-rate-field{grid-template-columns:1fr 1fr;gap:30px}.stats-split-signal{grid-template-columns:1fr}.stats-crime-orbit{width:min(78vw,420px);margin:auto}.stats-flow-line{grid-template-columns:1fr 1fr}.stats-flow-line>i{display:none}.stats-service-ledger,.stats-distribution,.stats-community-map{grid-template-columns:1fr 1fr}.stats-community-map article:nth-child(3){border-left:0;border-top:1px solid rgba(110,207,212,.18);padding-left:0}.stats-economy-number strong{font-size:clamp(42px,11vw,75px)}}
@media(max-width:560px){.stats-brand div,.stats-topbar>div button:last-child{display:none}.stats-masthead h1{font-size:62px}.stats-masthead p{font-size:15px}.stats-kpi-run,.stats-rate-field,.stats-service-ledger,.stats-distribution,.stats-community-map{grid-template-columns:1fr}.stats-kpi-run article:nth-child(even),.stats-service-ledger article+article,.stats-community-map article+article{border-left:0;padding-left:0}.stats-kpi-run article+article,.stats-service-ledger article+article,.stats-community-map article+article{border-top:1px solid rgba(110,207,212,.16)}.stats-arc{justify-content:flex-start}.stats-activity-measure{border-left:0;border-top:1px solid rgba(110,207,212,.18);padding:24px 0}.stats-flow-line{grid-template-columns:1fr}.stats-benchmark{grid-template-columns:1fr}.stats-benchmark>i{margin:20px 0}.stats-benchmark div:last-child{text-align:left}.stats-platform-strip>div{grid-template-columns:100px 1fr 55px}.stats-footer{align-items:flex-start;flex-direction:column;padding-top:25px;padding-bottom:25px}}
@media(prefers-reduced-motion:reduce){.stats-workspace *{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important}}

/* Statewide economy index: full-value typography and an RP currency desk. */
.stats-workspace-v2 .stats-signal strong{font-size:clamp(19px,1.8vw,34px);overflow:visible;text-overflow:clip;white-space:normal;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.stats-workspace-v2 .stats-command-panel.economy header strong{max-width:70%;text-align:right;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.stats-currency-stage{display:grid;grid-template-columns:1.15fr .85fr;border-block:1px solid rgba(239,198,106,.28);background:radial-gradient(circle at 15% 45%,rgba(239,198,106,.09),transparent 36%);position:relative;overflow:hidden}
.stats-currency-stage:before{content:"FCD";position:absolute;right:-.04em;bottom:-.28em;font:950 clamp(130px,23vw,360px)/1 Inter,sans-serif;color:rgba(239,198,106,.025);pointer-events:none}
.stats-currency-stage>section{padding:58px 52px 52px 0;position:relative;z-index:1}.stats-currency-stage>section>span{color:var(--stats-gold);font:800 9px ui-monospace,monospace;letter-spacing:.2em}
.stats-currency-quote{display:flex;align-items:baseline;gap:18px;margin:24px 0 14px}.stats-currency-quote small{font-size:24px;color:#91aaad}.stats-currency-quote strong{font-size:clamp(52px,6.4vw,100px);line-height:.9;letter-spacing:-.07em;font-variant-numeric:tabular-nums}.stats-currency-quote em{font-style:normal;color:#769398;font-size:11px}
.stats-currency-stage>section>p{color:#94aaad}.stats-currency-stage>section>i{display:block;height:3px;background:rgba(239,198,106,.1);margin-top:28px}.stats-currency-stage>section>i b{display:block;width:var(--currency-index);height:100%;background:linear-gradient(90deg,var(--stats-gold),var(--stats-green));box-shadow:0 0 16px rgba(239,198,106,.45);animation:statsWidth .9s ease}
.stats-currency-stage>aside{border-left:1px solid rgba(239,198,106,.2);padding:38px 0 38px 44px;display:grid;grid-template-columns:1fr 1fr;align-content:center;position:relative;z-index:1}.stats-currency-stage>aside div{padding:22px 18px 22px 0;border-bottom:1px solid rgba(104,232,238,.11)}.stats-currency-stage>aside span,.stats-currency-stage>aside strong{display:block}.stats-currency-stage>aside span{color:#718e93;font-size:10px}.stats-currency-stage>aside strong{font-size:20px;margin-top:7px;font-variant-numeric:tabular-nums}
.stats-currency-stage>footer{grid-column:1/3;padding:15px 0;border-top:1px solid rgba(239,198,106,.18);color:#637f84;font:700 9px ui-monospace,monospace;letter-spacing:.08em;position:relative;z-index:1}
@media(max-width:1050px){.stats-currency-stage{grid-template-columns:1fr}.stats-currency-stage>section{padding-right:0}.stats-currency-stage>aside{border-left:0;border-top:1px solid rgba(239,198,106,.2);padding-left:0}.stats-currency-stage>footer{grid-column:1}}
@media(max-width:720px){.stats-currency-stage>aside{grid-template-columns:1fr}.stats-currency-quote{display:block}.stats-currency-quote small,.stats-currency-quote strong,.stats-currency-quote em{display:block}.stats-currency-quote strong{font-size:clamp(42px,13vw,72px);margin:10px 0}.stats-workspace-v2 .stats-signal strong{font-size:27px}.stats-workspace-v2 .stats-command-panel.economy header strong{max-width:none;text-align:left}}

/* Statewide Intelligence 2.0 — open-data command experience */
.stats-workspace-v2{--stats-red:#ff6478;--stats-green:#4ce6a4;--stats-violet:#b598ff;background:radial-gradient(circle at 72% 2%,rgba(34,115,141,.24),transparent 28%),linear-gradient(135deg,#040b10,#07161c 48%,#050d12);overflow-x:hidden}
.stats-workspace-v2 .stats-topbar{position:sticky;top:0}.stats-newswire{height:38px;overflow:hidden;border-bottom:1px solid rgba(104,232,238,.16);background:#061014}.stats-newswire>div{height:100%;display:flex;align-items:center;width:max-content;animation:statsTicker 32s linear infinite}.stats-newswire span{padding:0 34px;border-right:1px solid rgba(104,232,238,.14);color:#68898e;font:800 9px ui-monospace,monospace;letter-spacing:.12em}.stats-newswire b{color:#ddfafa;margin-left:8px}.stats-workspace-v2 .stats-masthead{padding-top:95px;padding-bottom:90px}.stats-workspace-v2 .stats-masthead h1{font-family:Inter,sans-serif;font-weight:900}.stats-workspace-v2 .stats-story{max-width:1640px;padding-inline:clamp(24px,5vw,80px)}
