/* Ravenhood header identity — the launcher raven carries through into the exchange. */
.market-v13-brand>.market-v13-brand-mark{
  position:relative;
  width:44px;
  height:44px;
  flex:0 0 44px;
  display:grid;
  place-items:center;
  overflow:hidden;
  border:1px solid rgba(118,255,208,.38);
  border-radius:15px 6px 15px 6px;
  background:
    radial-gradient(circle at 78% 18%,rgba(255,85,174,.2),transparent 27%),
    linear-gradient(145deg,#103d31 0%,#071e18 58%,#020a07 100%);
  box-shadow:
    0 0 0 1px rgba(3,19,13,.95),
    0 0 24px rgba(73,235,168,.18),
    inset 0 1px 0 rgba(215,255,241,.12);
}
