.lottery-open-cap {
  display: inline-flex;
  margin-top: 12px;
  padding: 7px 11px;
  border: 1px solid rgba(250, 210, 82, .3);
  border-radius: 999px;
  color: #f7d96c;
  background: rgba(250, 210, 82, .07);
  font: 700 11px/1.2 var(--font-mono, monospace);
  letter-spacing: .08em;
  text-transform: uppercase;
}

.lottery-payment-recovery {
  overflow: hidden;
  border-color: rgba(85, 220, 205, .24);
  background: linear-gradient(145deg, rgba(8, 24, 28, .96), rgba(10, 16, 23, .98));
}

.lottery-recovery-policy {
  display: flex;
  align-items: center;
  gap: 20px;
  margin: 0 0 18px;
  padding: 13px 0;
  border-block: 1px solid rgba(135, 178, 185, .16);
}

.lottery-recovery-policy > span {
  display: flex;
  align-items: baseline;
  gap: 9px;
  min-width: max-content;
}

.lottery-recovery-policy b {
  color: #68e6d6;
  font-size: 25px;
}

.lottery-recovery-policy small,
.lottery-recovery-ledger article > div:first-child > span,
.lottery-command-state small {
  color: #7fa1aa;
  font: 800 10px/1.2 var(--font-mono, monospace);
  letter-spacing: .12em;
  text-transform: uppercase;
}

.lottery-recovery-policy p {
  margin: 0;
  color: #9ab0b5;
  font-size: 13px;
}

.lottery-recovery-ledger {
  display: grid;
}

.lottery-recovery-ledger article {
  display: grid;
  grid-template-columns: minmax(240px, 1.4fr) minmax(220px, 1fr) auto;
  align-items: center;
  gap: 20px;
  padding: 16px 0;
  border-bottom: 1px solid rgba(135, 178, 185, .13);
}

.lottery-recovery-ledger article:last-child {
  border-bottom: 0;
}

.lottery-recovery-ledger article > div:first-child {
  display: grid;
  gap: 4px;
}

.lottery-recovery-ledger article > div:first-child strong {
  color: #edf8f7;
  font-size: 15px;
}

.lottery-recovery-ledger article > div:first-child small {
  color: #80959b;
}

.lottery-command-state {
  display: grid;
  gap: 3px;
}

.lottery-command-state strong {
  color: #ffbf5e;
  font-size: 12px;
}

.lottery-command-state.completed strong {
  color: #56e3b1;
}

.lottery-command-state.failed strong,
.lottery-command-state.cancelled strong,
.lottery-command-state.missing strong {
  color: #ff7889;
}

.lottery-command-state code {
  max-width: 260px;
  overflow: hidden;
  color: #7f969d;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lottery-recovery-ledger button {
  min-width: 160px;
  border: 1px solid rgba(89, 226, 208, .35);
  color: #dffcf7;
  background: rgba(30, 118, 112, .18);
}

.lottery-recovery-ledger button:hover:not(:disabled) {
  border-color: #61e8d7;
  background: rgba(30, 118, 112, .34);
}

.lottery-recovery-clear {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 0 6px;
}

.lottery-recovery-clear i {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(74, 221, 170, .35);
  border-radius: 50%;
  color: #53dfa9;
  background: rgba(74, 221, 170, .08);
  font-style: normal;
}

.lottery-recovery-clear div {
  display: grid;
  gap: 3px;
}

.lottery-recovery-clear span {
  color: #849a9f;
  font-size: 12px;
}

@media (max-width: 820px) {
  .lottery-recovery-policy,
  .lottery-recovery-ledger article {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .lottery-recovery-policy {
    flex-direction: column;
    gap: 8px;
  }

  .lottery-recovery-ledger button {
    width: 100%;
  }
}

