/* Faircroft Foundry cinematic primary-market entrance. */
.issuer-workspace{
  --foundry-glow:rgba(88,232,185,.2);
  background:
    radial-gradient(1000px 640px at 100% 5%,rgba(33,213,174,.11),transparent 68%),
    radial-gradient(900px 600px at -5% 40%,rgba(234,57,166,.075),transparent 70%),
    linear-gradient(145deg,#030708 0%,#06100f 48%,#04080a 100%);
}

