/* FEC Ravenhood account supervision */
.market-compliance-banner {
  margin: 0;
  min-height: 66px;
  padding: 13px clamp(18px, 3vw, 50px);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 15px;
  color: #dafcf1;
  background: linear-gradient(90deg, rgba(37, 216, 167, .13), rgba(7, 23, 19, .98) 56%, rgba(61, 171, 255, .08));
  border-block: 1px solid rgba(89, 231, 187, .2);
}
.market-compliance-banner > i {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(91, 239, 193, .56);
  border-radius: 50%;
  color: #67f2c4;
  font: 800 10px/1 var(--mono, monospace);
  font-style: normal;
  letter-spacing: .08em;
  box-shadow: 0 0 22px rgba(54, 224, 170, .12);
}
.market-compliance-banner span { min-width: 0; display: grid; gap: 3px; }
.market-compliance-banner strong { font-size: 13px; letter-spacing: .02em; }
.market-compliance-banner small { color: #8eaaa1; font-size: 10px; line-height: 1.45; }
.market-compliance-banner > b {
  color: #6df2c6;
  font: 800 9px/1 var(--mono, monospace);
  letter-spacing: .18em;
  white-space: nowrap;
}
.market-compliance-banner.restricted {
  background: linear-gradient(90deg, rgba(255, 82, 112, .13), rgba(24, 9, 13, .98) 58%, rgba(255, 183, 77, .07));
  border-color: rgba(255, 97, 126, .2);
}
.market-compliance-banner.restricted > i,
.market-compliance-banner.restricted > b { color: #ff758e; border-color: rgba(255, 105, 131, .54); }
.market-v18-read-only {
  margin-top: 14px;
  display: inline-flex !important;
  align-items: center;
  gap: 7px;
  padding: 10px 12px;
  border: 1px solid rgba(92, 231, 188, .27);
  border-radius: 999px;
  color: #6fe8c2 !important;
  background: rgba(20, 82, 65, .18);
  font: 800 9px/1 var(--mono, monospace) !important;
  letter-spacing: .13em;
  white-space: nowrap;
}
.market-v18-read-only i { width: 6px; height: 6px; border-radius: 50%; background: #63f0c1; box-shadow: 0 0 12px #4ee1b2; }

.fec-account-restriction-console { overflow: hidden; }
.fec-account-restriction-head {
  padding: 26px 30px;
  display: flex;
  justify-content: space-between;
  gap: 28px;
  border-bottom: 1px solid rgba(105, 229, 192, .18);
  background: linear-gradient(115deg, rgba(15, 65, 54, .42), transparent 62%);
}
.fec-account-restriction-head > div > span,
.fec-account-restriction-form small,
.fec-account-active-restrictions > header span {
  color: #66eac1;
  font: 800 9px/1.2 var(--mono, monospace);
  letter-spacing: .15em;
}
.fec-account-restriction-head h2 { margin: 7px 0 5px; font-size: clamp(25px, 3vw, 39px); }
.fec-account-restriction-head p { max-width: 790px; margin: 0; color: #93aba4; line-height: 1.55; }
.fec-account-restriction-head > aside { min-width: 205px; padding-left: 25px; border-left: 1px solid rgba(105, 229, 192, .18); display: grid; align-content: center; gap: 4px; }
.fec-account-restriction-head > aside small,
.fec-account-restriction-head > aside em { color: #78958c; font: 800 9px/1.2 var(--mono, monospace); font-style: normal; letter-spacing: .12em; }
.fec-account-restriction-head > aside strong { color: #68efc2; font-size: 31px; }
.fec-account-restriction-head > aside.alert strong,
.fec-account-restriction-head > aside.alert em { color: #ff708a; }
