.fec-account-restriction-form label { display: grid; gap: 8px; color: #d8eee7; font-size: 11px; font-weight: 750; }
.fec-account-restriction-form label > small { color: #718f86; letter-spacing: normal; line-height: 1.5; font-weight: 500; }
.fec-account-restriction-form input,
.fec-account-restriction-form select,
.fec-account-restriction-form textarea,
.fec-account-active-restrictions input {
  width: 100%;
  color: #e5fff6;
  background: rgba(7, 23, 19, .78);
  border: 1px solid rgba(103, 220, 185, .23);
  border-radius: 8px;
}
