.fec-account-active-restrictions > header strong { color: #ff718b; font: 800 10px/1 var(--mono, monospace); letter-spacing: .12em; }
.fec-account-active-restrictions > div > article { padding: 19px 0; display: grid; grid-template-columns: minmax(175px, .7fr) minmax(240px, 1.2fr) minmax(180px, .8fr); gap: 18px; align-items: center; border-bottom: 1px solid rgba(105, 229, 192, .14); }
.fec-account-restriction-person { display: flex; align-items: center; gap: 11px; min-width: 0; }
.fec-account-restriction-person > i { width: 37px; height: 37px; flex: 0 0 37px; display: grid; place-items: center; border: 1px solid rgba(108, 235, 195, .43); border-radius: 50%; color: #6cf0c4; font-style: normal; font-weight: 900; }
.fec-account-restriction-person span,
.fec-account-restriction-order { min-width: 0; display: grid; gap: 4px; }
