.fec-account-restriction-order p { margin: 0; color: #b9cec7; font-size: 10px; line-height: 1.45; }
.fec-account-active-restrictions form { display: grid; gap: 8px; }
.fec-account-active-restrictions form input { min-height: 36px; font-size: 10px; }
.fec-account-active-restrictions form button { min-height: 37px; }
.fec-account-restriction-history { border-top: 1px solid rgba(105, 229, 192, .17); }
.fec-account-restriction-history > summary { padding: 17px 30px; display: flex; justify-content: space-between; cursor: pointer; color: #cbe2db; }
.fec-account-restriction-history > summary strong { color: #718f86; font: 800 9px/1 var(--mono, monospace); letter-spacing: .11em; }
.fec-account-restriction-history > div { padding: 0 30px 25px; }
.fec-account-restriction-history article { display: grid; grid-template-columns: .8fr .85fr .65fr 1.4fr; gap: 16px; padding: 13px 0; border-top: 1px solid rgba(105, 229, 192, .12); }
.fec-account-restriction-history article span { display: grid; gap: 3px; }
.fec-account-restriction-history article small { color: #718f86; font-size: 9px; }
.fec-account-restriction-history article p { margin: 0; color: #a7beb6; font-size: 10px; line-height: 1.4; }
.fec-account-restriction-history article.active > span:nth-child(3) b { color: #ff718b; }
