  --fec-panel-2: rgba(19, 30, 51, .92);
  --fec-blue: #4c8dff;
  --fec-cyan: #45d7ee;
  --fec-violet: #a77cff;
  --fec-green: #36d4ae;
  --fec-red: #ff6475;
  --fec-amber: #f2b84b;
  gap: 0;
  min-width: 0;
  color: var(--fec-ink);
  background:
    radial-gradient(circle at 92% 2%, rgba(76, 141, 255, .13), transparent 28rem),
    radial-gradient(circle at 6% 32%, rgba(69, 215, 238, .07), transparent 25rem),
