.fec-command-brand > span { display: grid; min-width: 0; gap: 3px; }
.fec-command-brand small,
.fec-dashboard-v2 .fec-analytics-card > header span,
.fec-dashboard-v2 .fec-kpi-card small,
.fec-dashboard-v2 .fec-case-rail > header span,
.fec-security-intelligence > header span,
