.fec-kpi-card::after { content: ''; position: absolute; inset: auto 0 0; height: 2px; background: var(--accent, var(--fec-blue)); opacity: .7; transform-origin: left; animation: fecLineIn .65s ease-out both; }
@keyframes fecLineIn { from { transform: scaleX(0); } }
.fec-kpi-card.blue { --accent: var(--fec-blue); }
.fec-kpi-card.cyan { --accent: var(--fec-cyan); }
