.fec-analytics-card > header { min-height: 72px; padding: 17px 19px; display: flex; align-items: center; justify-content: space-between; gap: 14px; border-bottom: 1px solid var(--fec-line); }
.fec-analytics-card > header > div { display: grid; gap: 4px; }
.fec-analytics-card h3 { margin: 0; font-size: 17px; }
.fec-analytics-card > header strong { color: #aec1db; font: 800 10px/1 var(--mono, monospace); }
.fec-analytics-card > header button,
