.fec-execution-hour { min-width: 0; flex: 1 1 0; display: grid; grid-template-rows: 1fr auto; gap: 10px; }
.fec-execution-hour > span { min-height: 196px; display: flex; align-items: end; justify-content: center; gap: 2px; border-bottom: 1px solid rgba(126, 153, 192, .17); background: repeating-linear-gradient(to top, transparent 0 48px, rgba(126, 153, 192, .075) 49px 50px); }
