.fec-market-structure-grid { min-width: 0; display: grid; grid-template-columns: .82fr 1.12fr 1.06fr; gap: 15px; }
.fec-structure-panel { min-width: 0; overflow: hidden; background: linear-gradient(155deg, rgba(16, 27, 46, .92), rgba(9, 17, 30, .91)); border: 1px solid var(--fec-line); border-radius: 13px; }
.fec-structure-panel > header { min-height: 57px; padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; gap: 14px; border-bottom: 1px solid var(--fec-line); }
.fec-structure-panel > header strong { color: #c1cfe2; font: 850 9px/1 var(--mono, monospace); text-align: right; }
.fec-breadth-gauge { width: 150px; margin: 24px auto 17px; aspect-ratio: 1; display: grid; place-items: center; border-radius: 50%; background: conic-gradient(var(--fec-green) 0 var(--advance), rgba(255,100,117,.56) var(--advance) 100%); box-shadow: 0 0 44px rgba(54,212,174,.08); }
.fec-breadth-gauge::before { content: ''; width: 80%; aspect-ratio: 1; grid-area: 1/1; border-radius: 50%; background: #0d1728; border: 1px solid var(--fec-line); }
.fec-breadth-gauge > div { z-index: 1; grid-area: 1/1; display: grid; gap: 5px; text-align: center; }
.fec-breadth-gauge strong { font-size: 27px; line-height: 1; }
.fec-breadth-gauge small { color: #71869f; font: 800 7px/1 var(--mono, monospace); letter-spacing: .12em; }
.fec-breadth-counts { padding: 0 15px 17px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.fec-breadth-counts span { display: grid; gap: 4px; color: #788da7; font-size: 8px; text-align: center; }
.fec-breadth-counts b { color: #dce7f6; font-size: 15px; }
.fec-breadth-counts .positive b { color: var(--fec-green); }
.fec-breadth-counts .negative b { color: var(--fec-red); }
.fec-breadth-panel > footer { padding: 13px 16px; display: flex; align-items: center; justify-content: space-between; gap: 15px; border-top: 1px solid var(--fec-line); color: #71849e; font: 800 8px/1 var(--mono, monospace); }
.fec-breadth-panel > footer strong { font-size: 12px; }
.fec-concentration-meter { height: 8px; margin: 20px 16px 12px; overflow: hidden; background: rgba(92, 119, 157, .15); border-radius: 99px; }
.fec-concentration-meter i { height: 100%; display: block; background: linear-gradient(90deg, #4386ee, #a679ff); box-shadow: 0 0 16px rgba(76,141,255,.35); border-radius: inherit; }
.fec-concentration-panel > p { margin: 0; padding: 0 16px 14px; color: #8092aa; font-size: 9px; line-height: 1.5; }
.fec-concentration-panel > p b { color: #dce7f6; }
.fec-cap-rank-list,
.fec-mover-table { border-top: 1px solid var(--fec-line); }
.fec-cap-rank-list button,
.fec-mover-table button { width: 100%; min-width: 0; min-height: 49px; padding: 9px 13px; color: #e8effb; background: transparent; border: 0; border-bottom: 1px solid var(--fec-line); border-radius: 0; text-align: left; }
.fec-cap-rank-list button:last-child,
.fec-mover-table button:last-child { border-bottom: 0; }
.fec-cap-rank-list button:hover,
.fec-mover-table button:hover { background: rgba(76,141,255,.065); }
.fec-cap-rank-list button { display: grid; grid-template-columns: auto minmax(0,1fr) auto; align-items: center; gap: 10px; }
.fec-cap-rank-list button > i,
.fec-mover-table button > i { color: #6c82a0; font: 800 8px/1 var(--mono, monospace); font-style: normal; }
.fec-cap-rank-list button span { min-width: 0; display: grid; gap: 3px; }
.fec-cap-rank-list button b { font-size: 10px; }
.fec-cap-rank-list button small { color: #6f829b; font-size: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fec-cap-rank-list button em { min-width: 0; display: grid; gap: 3px; text-align: right; font-style: normal; }
.fec-cap-rank-list button em small { color: #7ea5d4; }
.fec-mover-table button { display: grid; grid-template-columns: auto minmax(82px,.9fr) minmax(90px,1.1fr) auto; align-items: center; gap: 10px; }
.fec-mover-table button > span { min-width: 0; display: grid; gap: 3px; }
.fec-mover-table button > span b { font-size: 10px; }
.fec-mover-table button > span small { color: #70839c; font-size: 7px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fec-mover-table button > em { height: 5px; overflow: hidden; background: rgba(105,132,168,.13); border-radius: 99px; font-style: normal; }
.fec-mover-table button > em i { height: 100%; display: block; border-radius: inherit; }
.fec-mover-table button > em i.positive { background: var(--fec-green); }
.fec-mover-table button > em i.negative { background: var(--fec-red); }
.fec-mover-table button > strong { font: 850 9px/1 var(--mono, monospace); text-align: right; }

.fec-institutional-analytics-grid { min-width: 0; display: grid; grid-template-columns: minmax(0, 1.85fr) minmax(315px, .65fr); gap: 15px; align-items: stretch; }
.fec-flow-terminal .fec-market-chart { height: 370px; }
.fec-flow-terminal > footer { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.fec-flow-terminal > footer span { align-content: center; }
.fec-flow-terminal > footer em { color: #687d98; font-size: 8px; font-style: normal; }
.fec-chart-key i.delta { background: var(--fec-violet); box-shadow: 0 0 9px rgba(167,124,255,.45); }
.fec-orderflow-svg .buy-bar { fill: rgba(65, 216, 180, .62); }
.fec-orderflow-svg .sell-bar { fill: rgba(255, 100, 121, .6); }
.fec-orderflow-svg .delta-zero { stroke: rgba(159, 174, 203, .28); stroke-width: 1; stroke-dasharray: 4 5; }
.fec-orderflow-svg .delta-area { fill: url(#fecDeltaFill); }
.fec-orderflow-svg .delta-line { fill: none; stroke: var(--fec-violet); stroke-width: 2.7; vector-effect: non-scaling-stroke; filter: drop-shadow(0 0 5px rgba(167,124,255,.5)); }
.fec-orderflow-svg circle.delta { fill: #c1a9ff; stroke: #101a2d; stroke-width: 2; }
.fec-risk-matrix { display: flex; flex-direction: column; }
.fec-risk-matrix .fec-trade-mix-body { min-height: 202px; grid-template-columns: 112px 1fr; gap: 15px; }
.fec-risk-matrix .fec-trade-donut { width: 112px; }
.fec-risk-register { margin-top: auto; border-top: 1px solid var(--fec-line); }
.fec-risk-register button { width: 100%; min-height: 49px; padding: 10px 15px; display: flex; align-items: center; justify-content: space-between; gap: 15px; color: #9aacbf; background: transparent; border: 0; border-bottom: 1px solid var(--fec-line); border-radius: 0; text-align: left; }
.fec-risk-register button:last-child { border-bottom: 0; }
.fec-risk-register button:hover { color: #edf4ff; background: rgba(76,141,255,.07); }
.fec-risk-register button strong { color: #edf4ff; font: 900 14px/1 var(--mono, monospace); }
.fec-secondary-intelligence { min-width: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 15px; }

@media (max-width: 1280px) {
  .fec-market-command-head { grid-template-columns: 1fr; }
  .fec-market-command-head > aside { max-width: 760px; }
  .fec-market-structure-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .fec-volatility-panel { grid-column: 1 / -1; }
  .fec-mover-table { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); }
  .fec-mover-table button:nth-child(odd) { border-right: 1px solid var(--fec-line); }
  .fec-institutional-analytics-grid { grid-template-columns: 1fr; }
  .fec-risk-matrix { display: grid; grid-template-columns: minmax(300px,.7fr) minmax(0,1fr); }
  .fec-risk-matrix > header { grid-column: 1 / -1; }
  .fec-risk-register { margin-top: 0; border-top: 0; border-left: 1px solid var(--fec-line); }
}
@media (max-width: 980px) {
  .fec-index-grid { grid-template-columns: 1fr; }
  .fec-index-card.volatility { border-left: 0; border-top: 1px solid var(--fec-line); }
  .fec-market-structure-grid,
  .fec-secondary-intelligence { grid-template-columns: 1fr; }
  .fec-volatility-panel { grid-column: auto; }
  .fec-flow-terminal > footer { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .fec-flow-terminal > footer span:nth-child(2) { border-right: 0; }
  .fec-flow-terminal > footer span:nth-child(-n+2) { border-bottom: 1px solid var(--fec-line); }
}
@media (max-width: 720px) {
  .fec-market-command-head { gap: 17px; }
  .fec-market-command-head > aside { grid-template-columns: 1fr; border: 1px solid var(--fec-line); }
  .fec-market-command-head > aside > span { min-height: 62px; border-right: 0; border-bottom: 1px solid var(--fec-line); }
  .fec-market-command-head > aside > span:last-child { border-bottom: 0; }
  .fec-index-command > header { align-items: flex-start; flex-direction: column; }
  .fec-index-command > header > small { text-align: left; }
  .fec-index-card > header { align-items: flex-start; }
  .fec-index-card > header > em b { font-size: 18px; }
  .fec-index-chart { height: 218px; overflow: hidden; padding-inline: 7px; }
  .fec-index-svg { min-width: 0; }
  .fec-index-card > footer { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .fec-index-card > footer span:nth-child(n) { border-right: 1px solid var(--fec-line); border-bottom: 1px solid var(--fec-line); }
  .fec-index-card > footer span:nth-child(even) { border-right: 0; }
  .fec-index-card > footer span:nth-last-child(-n+2) { border-bottom: 0; }
  .fec-mover-table { grid-template-columns: 1fr; }
  .fec-mover-table button:nth-child(odd) { border-right: 0; }
  .fec-risk-matrix { display: flex; }
  .fec-risk-matrix .fec-trade-mix-body { grid-template-columns: 105px 1fr; }
  .fec-risk-register { border-left: 0; border-top: 1px solid var(--fec-line); }
}
@media (max-width: 470px) {
  .fec-index-card > header { flex-direction: column; }
  .fec-index-card > header > em { width: 100%; grid-template-columns: 1fr auto; align-items: end; text-align: left; }
  .fec-breadth-counts { grid-template-columns: 1fr; }
  .fec-flow-terminal > footer { grid-template-columns: 1fr; }
  .fec-flow-terminal > footer span:nth-child(n) { border-right: 0; border-bottom: 1px solid var(--fec-line); }
  .fec-flow-terminal > footer span:last-child { border-bottom: 0; }
  .fec-risk-matrix .fec-trade-mix-body { grid-template-columns: 1fr; justify-items: center; }
}
